// Otomatik üretilir (araclar/yks-havuz-uret.js). Elle düzenlemeyin.
// YKS özel dersi için kısa konu anlatımları (5–12. sınıf bölümlerinden): YKS_ANLAT["sınıf:konu"], YKS_ANLAT_SEC[YKS dersi][konu sırası].
window.YKS_ANLAT={"9:ede4k2":{"a":"Sözcükte Anlam ve Anlam İlişkileri","o":["Gerçek, yan, mecaz, terim anlam","Eş anlamlı (siyah-kara), zıt anlamlı (uzun-kısa), eş sesli (yüz: sayı / surat)","Deyim aktarması: benzetme yoluyla (masanın ayağı)","Ad aktarması (mecaz-ı mürsel): benzetme olmadan (Saray bu karara karşı çıktı)","Somut-soyut, genel-özel anlam"],"t":["Bir sözcüğün akla gelen ilk anlamı gerçek anlamdır. Gerçek anlamla ilgisi olan yeni anlamlara yan anlam ('kapının kolu'), gerçek anlamından uzaklaşmış anlamlara mecaz ('ağır söz') denir. Bilim, sanat ve meslek alanlarına özgü anlam terim anlamdır.","Anlam aktarmalarında benzetme yoluyla bir sözcüğün başka bir kavram için kullanılmasına deyim aktarması, benzetme amacı olmadan parça-bütün, yer-insan gibi ilgilerle yapılan aktarmaya ad aktarması denir: 'Bütün sınıf bu kararı alkışladı' (sınıftaki öğrenciler)."],"e":["Deyim nedir?   A) Genellikle mecaz anlamlı, kalıplaşmış söz grubu   B) Bilimsel terim   C) Öğüt veren cümle   D) Tek bir sözcük","Doğru cevap: A) Genellikle mecaz anlamlı, kalıplaşmış söz grubu. Örnek: \"etekleri zil çalmak\"."]},"8:tur3k2":{"a":"Cümlede Anlam: Neden-Sonuç, Amaç-Sonuç, Koşul, Öznel-Nesnel","o":["Neden-sonuç: eylemin gerçekleşme sebebi (çünkü, için, -den dolayı, -dığı için)","Amaç-sonuç: amaç belirtilir (… için, -mek üzere) — sonuç henüz gerçekleşmemiş olabilir","Koşul-sonuç: bir şarta bağlı (-se, -ince, -dikçe)","Öznel yargı: kişisel görüş, kanıtlanamaz · Nesnel yargı: kanıtlanabilir","Karşılaştırma: iki varlık arasında benzerlik/farklılık (daha, en, -den…)"],"t":["Cümleler anlam ilişkilerine göre sınıflandırılır. Neden-sonuçta bir eylemin sebebi verilir ('Yağmur yağdığı için maç ertelendi.'); amaç-sonuçta ise yapılan işin amacı ('Sınavı kazanmak için çalışıyor.'). Ayırt etmek için 'için' yerine 'amacıyla' koyabiliyorsak amaç-sonuçtur.","Kişiden kişiye değişebilen, kanıtlanamayan yargılar öznel ('Bu film çok sıkıcıydı.'); doğruluğu araştırılarak kanıtlanabilen yargılar nesneldir ('Film 2 saat sürdü.'). Koşul cümlelerinde temel yargı bir şarta bağlıdır ('Erken gelirsen konuşuruz.')."],"e":["\"Telefonu bozulduğundan bizi arayamadı.\" cümlesinin anlam ilişkisi nedir?   A) Neden-sonuç   B) Karşılaştırma   C) Amaç-sonuç   D) Koşul-sonuç","Doğru cevap: A) Neden-sonuç. Arayamamanın nedeni telefonun bozulmasıdır."]},"7:t5c":{"a":"Parçada Anlatım: Anlatım Biçimleri","o":["Öyküleyici anlatım: olaylar, kişiler, zaman ve yer anlatılır; hareket vardır.","Betimleyici anlatım: bir varlığın görünüşü, rengi, sesi, kokusu anlatılır; okurun gözünde canlanır.","Bilgilendirici (açıklayıcı) anlatım: okura bilgi verir.","Düşünceyi geliştirme yolları: tanımlama, örneklendirme, karşılaştırma, benzetme, tanık gösterme, sayısal verilerden yararlanma."],"t":["Yazarlar metinlerini farklı anlatım biçimleriyle oluşturur. Öyküleyici anlatımda bir olay belli bir zaman ve yerde, kişilerin başından geçer; 'sonra', 'ertesi gün' gibi zaman ifadeleri ve hareket bildiren fiiller çoktur.","Betimleyici anlatımda bir varlık, yer ya da kişi sözcüklerle resmedilir. Renkler, sesler, kokular, şekiller anlatılır; okur o yeri gözünün önüne getirir: 'Kırmızı kiremitli küçük evin önünde mis kokulu güller açmıştı.'","Bilgilendirici anlatımda amaç okura bilgi vermektir. Ders kitapları, ansiklopediler ve haber metinleri bu anlatımla yazılır.","Yazarlar düşüncelerini açıklamak için bazı yollardan yararlanır: Tanımlama (bir kavramın ne olduğunu söylemek), örneklendirme (örnek vermek), karşılaştırma (benzerlik ve farkları göstermek), tanık gösterme (bir uzmanın sözünü aktarmak), sayısal verilerden yararlanma (rakam ve istatistik vermek)."],"e":["Hangisinde bilgilendirici anlatım kullanılmıştır?   A) Geçen yaz dedemlerin köyüne gittik. İlk gün ahırdaki buzağıyı besledik, ertesi gün dereye yüzmeye gittik.   B) Pazar yeri rengârenk meyvelerle doluydu; portakallar turuncu bir dağ gibi yükseliyordu.   C) Arılar, çiçeklerden topladıkları nektarı kovanda bala dönüştürür. Bir arı ömrü boyunca yaklaşık yarım çay kaşığı bal üretir.   D) Kedi önce masaya, sonra rafa sıçradı. Raftaki vazo yere düşüp kırıldı.","Doğru cevap: C) Arılar, çiçeklerden topladıkları nektarı kovanda bala dönüştürür. Bir arı ömrü boyunca yaklaşık yarım çay kaşığı bal üretir.. Bu metinde bilgilendirici anlatım vardır."]},"8:tur3k3":{"a":"Paragrafta Anlam: Ana Düşünce, Yardımcı Düşünce, Başlık","o":["Konu: paragrafta üzerinde durulan şey · Ana düşünce: yazarın vermek istediği mesaj","Ana düşünce genellikle giriş ya da sonuç cümlesindedir.","Yardımcı düşünceler ana düşünceyi destekler, açıklar.","Başlık: paragrafın konusunu kısa ve özlü yansıtır.","Paragrafı ikiye bölme: konunun ya da bakış açısının değiştiği yer"],"t":["Bir paragrafta konu 'ne anlatılıyor?', ana düşünce 'yazar ne demek istiyor?' sorusunun cevabıdır. Ana düşünce çoğu zaman yazarın vardığı sonuçtur ve paragrafın tamamını kapsar; yardımcı düşünceler ise onu örnek, karşılaştırma, tanımlama gibi yollarla destekler.","Paragraf sorularında önce soru kökü okunmalı, sonra paragraf dikkatle okunup anahtar sözcükler işaretlenmelidir. 'Değinilmemiştir', 'ulaşılamaz' gibi olumsuz köklere dikkat edilmeli; seçenekler paragraftaki bilgiyle tek tek karşılaştırılmalıdır."],"e":["Paragrafın konusunu bulmak için hangi soru sorulur?   A) Hangi yayınevi?   B) Paragraf kaç satır?   C) Yazar kimdir?   D) Paragrafta ne anlatılıyor?","Doğru cevap: D) Paragrafta ne anlatılıyor?. Konu, üzerinde durulan olay ya da durumdur."]},"7:t5d":{"a":"Parçada Yapı: Giriş, Gelişme, Sonuç","o":["Giriş cümlesi: konuya girer, kendinden önce bir cümleye ihtiyaç duymaz.","Gelişme: konuyu açıklar, örneklerle genişletir.","Sonuç: düşünceyi bağlar; 'kısacası, bu yüzden, sonuç olarak' ile başlayabilir.","Akışı bozan cümle: konunun dışına çıkan cümle.","'Bu, bunun, ama, çünkü, o yüzden' ile başlayan cümleler giriş cümlesi olamaz."],"t":["Bir paragraf giriş, gelişme ve sonuç bölümlerinden oluşur. Giriş cümlesi paragrafın ilk cümlesidir; konuyu tanıtır ve anlaşılmak için önceki bir cümleye ihtiyaç duymaz.","'Bu yüzden', 'ama', 'çünkü', 'bunun için', 'o' gibi bağlayıcı sözcüklerle başlayan cümleler kendinden önce bir cümle olduğunu gösterir; bu nedenle giriş cümlesi olamaz.","Gelişme bölümünde konu açıklanır, örnekler verilir. Sonuç cümlesi ise paragrafı toparlar; genellikle ana düşünceyi verir.","Paragrafta konunun dışına çıkan, akışı bozan cümle bulunabilir. Bu cümleyi çıkardığımızda paragrafın anlamı bozulmaz, aksine daha düzenli olur. Cümlelerin sırası değiştirildiğinde de anlamlı bir sıra bulmak için bağlayıcı sözcüklere dikkat ederiz."],"e":["Hangisi bir paragrafın giriş cümlesi olabilir?   A) Kısacası dostlarımıza değer vermeliyiz.   B) O da bu düşünceye katıldı.   C) Kitap okumak insanın hayal dünyasını zenginleştirir.   D) Böylece sağlığımızı koruyabiliriz.","Doğru cevap: C) Kitap okumak insanın hayal dünyasını zenginleştirir.. Bağlayıcı sözcükle başlamayan, kendi başına anlaşılan cümle giriş cümlesi olabilir."]},"9:ede1k2":{"a":"Ses Bilgisi ve Ses Olayları","o":["Büyük ünlü uyumu: kalın-ince uyumu (a, ı, o, u / e, i, ö, ü)","Ünsüz benzeşmesi: sert ünsüzden sonra ek sertleşir (kitap-cı → kitapçı)","Ünsüz yumuşaması: p, ç, t, k → b, c, d, ğ (kitap-ı → kitabı)","Ünlü düşmesi: ağız → ağzı · Ünlü daralması: başla-yor → başlıyor","Kaynaştırma: ünlüyle biten sözcüğe ünlüyle başlayan ek → y, ş, s, n (kapı-y-a)"],"t":["Türkçede sözcüklere ek getirilirken ses olayları görülür. Ünsüz yumuşamasında p, ç, t, k ile biten sözcükler ünlüyle başlayan ek alınca b, c, d, ğ olur: ağaç → ağacı. Ünsüz benzeşmesinde (sertleşme) sert ünsüzle biten sözcüğe gelen c, d, g ile başlayan ekler ç, t, k olur: sokak-da → sokakta.","Ünlü düşmesinde ikinci hecesinde dar ünlü bulunan bazı sözcükler ünlüyle başlayan ek alınca bu ünlüyü kaybeder: burun → burnu. Ünlü daralmasında a, e ile biten fiiller -yor eki alınca ı, i, u, ü'ye dönüşür: bekle-yor → bekliyor. Kaynaştırma ünsüzleri iki ünlünün yan yana gelmesini önler."],"e":["Hangi sözcük büyük ünlü uyumuna uymaz?   A) Okul   B) Çocuk   C) Kitap   D) Kalem","Doğru cevap: C) Kitap. Kitap'ta i (ince) ve a (kalın) birlikte bulunur."]},"8:tur4k4":{"a":"Yazım ve Noktalama","o":["\"de/da\" bağlacı ayrı, hâl eki bitişik yazılır: \"Sen de gel.\" – \"Evde kaldı.\"","\"ki\" bağlacı ayrı; sıfat ve iyelik \"-ki\" bitişik: \"Biliyorum ki...\" – \"evdeki\"","\"mi\" soru eki ayrı yazılır, kendinden önceki sözcüğe uyar.","Noktalı virgül: sıralı cümleler ve ögeleri virgülle ayrılmış eş görevli gruplar arasında.","İki nokta: açıklama ve örnek verilecek yerlerde."],"t":["Bağlaç olan 'de, da' ve 'ki' ile soru eki 'mi' her zaman ayrı yazılır. Bulunma hâl eki '-de, -da' ve '-ki' eki bitişiktir. Bir 'de'nin bağlaç olup olmadığını anlamak için cümleden çıkarılır; anlam bozulmuyorsa bağlaçtır.","Nokta cümle sonunda, virgül eş görevli sözcükler arasında ve sıralı cümlelerde, noktalı virgül ögeleri arasında virgül bulunan sıralı cümlelerde, iki nokta açıklama yapılacak ya da örnek verilecek yerlerde kullanılır. Soru işareti soru cümlelerinin, ünlem işareti ise heyecan, şaşırma, seslenme bildiren cümlelerin sonuna konur."],"e":["Hangisinde virgül doğru kullanılmıştır?   A) Sevgili kardeşim mektubunu, aldım.   B) Sevgili kardeşim mektubunu aldım,   C) Sevgili kardeşim, mektubunu aldım.   D) Sevgili, kardeşim mektubunu aldım.","Doğru cevap: C) Sevgili kardeşim, mektubunu aldım.. Hitaptan sonra virgül konur."]},"7:tr6k2":{"a":"Noktalama İşaretleri","o":["Nokta (.): tamamlanmış cümlenin sonuna, kısaltmalardan sonra, saat ve dakika arasına (10.30)","Virgül (,): eş görevli sözcükleri ayırır (elma, armut ve muz)","Soru işareti (?): soru cümlelerinin sonuna","Ünlem işareti (!): sevinç, korku, şaşkınlık bildiren cümle ve ünlemlerden sonra","İki nokta (:): açıklama ve örnekten önce, konuşma çizgisi/tırnaktan önce"],"t":["Nokta, tamamlanmış cümlelerin sonuna konur. Kısaltmalardan sonra (Dr., Prof.) ve saat ile dakika arasında da kullanılır: 'Saat 10.30'da buluşalım.'","Virgül, eş görevli sözcükleri ve söz öbeklerini birbirinden ayırır: 'Pazardan elma, armut ve muz aldım.' Hitap sözlerinden sonra da kullanılır: 'Arkadaşlar, yarın gezi var.'","Soru işareti soru bildiren cümlelerin sonuna konur: 'Yarın gelecek misin?' Ünlem işareti ise sevinç, korku, şaşkınlık gibi duyguları anlatan cümlelerden ve ünlemlerden sonra konur: 'Eyvah! Geç kaldık.'","İki nokta, kendisinden sonra açıklama ya da örnek gelecek cümlelerin sonuna konur: 'Çantama şunları koydum: kalem, defter, silgi.' Kesme işareti ise özel isimlere gelen ekleri ayırır: 'İstanbul'a gittik.'"],"e":["\"Bahçede kediler( ) köpekler ve kuşlar vardı.\" cümlesinde ayraç içine hangi noktalama işareti gelmelidir?   A) İki nokta (:)   B) Virgül (,)   C) Nokta (.)   D) Soru işareti (?)","Doğru cevap: B) Virgül (,). Ayraç içine Virgül (,) gelmelidir."]},"9:ede4k1":{"a":"Kök, Ek, Yapım ve Çekim Ekleri","o":["Kök: sözcüğün anlamlı en küçük parçası (isim kökü / fiil kökü)","Yapım eki: yeni sözcük türetir (göz-lük, yaz-ı)","Çekim eki: sözcüğü cümleye bağlar, anlamı değiştirmez (göz-ler-i)","Yapı: basit (ev), türemiş (evcil), birleşik (hanımeli)","Gövde: kök + yapım eki"],"t":["Sözcükler kök ve eklerden oluşur. Kök sözcüğün parçalanamayan, anlamlı en küçük parçasıdır. Yapım ekleri köke gelerek yeni anlamlı sözcükler (gövde) türetir: 'bil-gi', 'göz-lük-çü'. Çekim ekleri ise sözcüğün anlamını değiştirmez, onu cümleye bağlar: çoğul, iyelik, hâl ve fiil çekim ekleri gibi.","Yapılarına göre sözcükler üçe ayrılır: yalnızca kökten oluşan ya da yalnızca çekim eki alan sözcükler basit (kitaplar), yapım eki alanlar türemiş (kitaplık), iki ya da daha fazla sözcüğün birleşmesiyle oluşanlar birleşik (kahverengi, ayakkabı) sözcüklerdir."],"e":["Bir sözcüğün parçalanamayan ve anlamlı en küçük bölümüne ne denir?   A) Kök   B) Ek   C) Gövde   D) Hece","Doğru cevap: A) Kök. Örnek: \"göz-lük\"te kök \"göz\"dür."]},"6:tr2k1":{"a":"İsimler (Adlar)","o":["İsim: varlıkları ve kavramları karşılayan sözcük","Özel isim: tek olan varlığın adı, büyük harfle başlar (Ankara, Elif)","Cins (tür) isim: aynı türden varlıkların ortak adı (şehir, kız)","Somut isim: beş duyuyla algılanır (masa, ses, koku)","Soyut isim: duyularla algılanamaz (sevgi, korku, umut)"],"t":["Varlıkları, kavramları ve durumları karşılayan sözcüklere isim (ad) denir.","Varlıklara verilişine göre isimler ikiye ayrılır. Tek olan varlıklara verilen isimlere özel isim denir ve büyük harfle başlar: Ankara, Karadeniz, Elif, Türkçe. Aynı türden varlıkların ortak adına cins (tür) isim denir: şehir, deniz, kız, dil.","Varlıkların algılanışına göre isimler somut ya da soyut olabilir. Beş duyumuzdan en az biriyle algılanabilen varlıkların adı somut isimdir: masa, su, ses, koku. Duyularla algılanamayan, sadece zihinde var olan kavramların adı soyut isimdir: sevgi, korku, umut, düşünce.","Birden fazla varlığı anlatan ama tekil olan isimlere topluluk ismi denir: ordu, sürü, takım, aile, koro, millet. Sayılarına göre isimler tekil (kalem) ve çoğul (kalemler) olabilir."],"e":["Hangisi özel isimdir?   A) Nehir   B) Kız   C) Göl   D) Ankara","Doğru cevap: D) Ankara. Ankara tek olan bir varlığın adıdır; özel isimdir."]},"6:tr2k2":{"a":"Sıfatlar (Ön Adlar)","o":["Sıfat: ismin önüne gelip onu niteleyen ya da belirten sözcük","Niteleme sıfatı: nasıl? → kırmızı elbise, uzun yol","İşaret sıfatı: hangi? → bu kitap, şu ağaç, o ev","Sayı sıfatı: kaç? → üç kalem, birinci sıra, ikişer elma, yarım ekmek","Belgisiz sıfat: kesin sayı vermez → bazı, birkaç, her, hiçbir, çok"],"t":["İsimlerin önüne gelerek onların renk, biçim, durum, sayı gibi özelliklerini bildiren sözcüklere sıfat denir. Sıfat ile nitelediği isim birlikte sıfat tamlaması oluşturur: kırmızı elbise, üç kalem.","Varlığın nasıl olduğunu bildiren sıfatlara niteleme sıfatı denir: kırmızı elbise, uzun yol, akıllı çocuk. İsme sorulan 'nasıl?' sorusunun cevabını verir.","Varlığı işaret ederek belirten sıfatlara işaret sıfatı denir: bu kitap, şu ağaç, o ev. Varlığın sayısını, sırasını, bölümünü bildirenler sayı sıfatıdır: üç kalem, birinci sıra, ikişer elma, yarım ekmek. Kesin sayı bildirmeyenler belgisiz sıfattır: bazı öğrenciler, birkaç gün, her sabah, hiçbir soru.","Varlığı soru yoluyla belirtenler soru sıfatıdır: Hangi kitabı okudun? Kaç soru çözdün? Dikkat: 'Bu kitap güzel.' cümlesindeki 'bu' sıfattır çünkü ismin önündedir. 'Bu güzel.' cümlesinde ise 'bu' ismin yerini tuttuğu için zamirdir."],"e":["\"O ev yıllardır boş duruyor.\" cümlesindeki \"o\" sözcüğü hangi tür sıfattır?   A) Belgisiz sıfat   B) Soru sıfatı   C) İşaret sıfatı   D) Niteleme sıfatı","Doğru cevap: C) İşaret sıfatı. \"o\" işaret sıfatıdır."]},"6:tr2k3":{"a":"Zamirler (Adıllar)","o":["Zamir: ismin yerini tutan sözcük","Kişi zamiri: ben, sen, o, biz, siz, onlar","İşaret zamiri: bu, şu, o, bunlar, burası, orası (tek başına kullanılır)","Belgisiz zamir: herkes, kimse, bazıları, birisi, hepsi","Soru zamiri: kim, ne, hangisi, kaçı"],"t":["İsimlerin yerini tutan sözcüklere zamir (adıl) denir. Zamirler sayesinde aynı ismi tekrar tekrar söylemekten kurtuluruz.","Kişilerin adı yerine kullanılan zamirlere kişi zamiri denir: ben, sen, o, biz, siz, onlar. Varlıkları işaret yoluyla karşılayan zamirlere işaret zamiri denir: bu, şu, o, bunlar, şunlar, burası, orası.","Varlıkları belirsiz olarak karşılayan zamirlere belgisiz zamir denir: herkes, kimse, bazıları, birisi, hepsi, biri. Varlıkları soru yoluyla karşılayanlar ise soru zamiridir: kim, ne, hangisi, kaçı.","En çok karıştırılan nokta şudur: 'bu, şu, o' sözcükleri bir ismin önünde kullanılırsa sıfat, ismin yerine tek başına kullanılırsa zamirdir. 'Bu ev çok büyük.' → sıfat. 'Bu çok büyük.' → zamir."],"e":["Hangi cümlede kişi zamiri vardır?   A) Onlar parkta oyun oynuyor.   B) Hangisini seçtin?   C) Bunlar bahçeden toplandı.   D) Kim kapıyı çaldı?","Doğru cevap: A) Onlar parkta oyun oynuyor.. \"Onlar parkta oyun oynuyor.\" cümlesinde kişi zamiri kullanılmıştır."]},"7:t7d":{"a":"Zarflar (Belirteçler)","o":["Zarf: fiillerin, sıfatların ya da başka zarfların anlamını belirten sözcük.","Durum zarfı: nasıl? (hızlı koştu, yavaş yavaş yürüdü)","Zaman zarfı: ne zaman? (dün geldi, akşam gidecek)","Yer-yön zarfı: nereye? (yalın hâlde: içeri girdi, yukarı çıktı)","Miktar (azlık-çokluk) zarfı: ne kadar? (çok yorgun, en güzel, daha hızlı)"],"t":["Fiillerin, fiilimsilerin, sıfatların ya da kendi türünden sözcüklerin anlamını durum, zaman, yer-yön, miktar ve soru bakımından belirten sözcüklere zarf (belirteç) denir.","Durum zarfları fiile 'nasıl?' sorusunu sorunca bulunur: 'Çocuklar sessizce oturdu.' 'Hızlı koşma!' Zaman zarfları 'ne zaman?' sorusuna cevap verir: 'Dün sinemaya gittik.' 'Akşam ders çalışacağım.'","Yer-yön zarfları ek almadan fiilin yönünü belirtir: 'Dışarı çıktı.' 'İleri bak.' Dikkat: 'Dışarıya çıktı.' derken sözcük ek aldığı için zarf değil isimdir. Miktar zarfları 'ne kadar?' sorusuna cevap verir ve sıfatların, fiillerin derecesini belirtir: 'Çok güzel bir gün.' 'En sevdiğim kitap.' 'Biraz dinlen.'","Soru zarfları ise fiile durum, zaman, miktar sorusu sorar: 'Nasıl geldin?' 'Ne zaman döneceksin?' 'Niçin ağlıyorsun?'"],"e":["\"Çocuklar sessizce oturdu.\" cümlesindeki \"sessizce\" sözcüğü hangi tür zarftır?   A) Miktar zarfı   B) Zaman zarfı   C) Durum zarfı   D) Yer-yön zarfı","Doğru cevap: C) Durum zarfı. sessizce: durum zarfı."]},"6:tr2k4":{"a":"Edat, Bağlaç ve Ünlem","o":["Edat (ilgeç): tek başına anlamı yok, cümlede anlam ilişkisi kurar → gibi, için, kadar, göre, beri","Bağlaç: sözcükleri ve cümleleri birbirine bağlar → ve, ama, fakat, çünkü, veya, ya da","Ünlem: sevinç, korku, şaşkınlık gibi duyguları anlatır → Eyvah! Yaşasın! Of!","Bağlaç olan \"de/da\" ayrı yazılır: Ben de geldim."],"t":["Tek başına anlamı olmayan ama cümlede kullanıldığında sözcükler arasında anlam ilişkisi kuran sözcüklere edat (ilgeç) denir. 'Aslan gibi güçlü', 'Senin için geldim', 'Akşama kadar çalıştı', 'Sabahtan beri yağmur yağıyor' cümlelerindeki 'gibi, için, kadar, beri' birer edattır.","Sözcükleri, söz öbeklerini ya da cümleleri birbirine bağlayan sözcüklere bağlaç denir: ve, ama, fakat, çünkü, veya, ya da, ancak, de. 'Elma ve armut aldım.' 'Çok çalıştı ama kazanamadı.'","Sevinç, acı, korku, şaşkınlık gibi duyguları ya da seslenmeleri anlatan sözcüklere ünlem denir: Eyvah, Yaşasın, Ah, Of, Hey. Ünlemlerden sonra genellikle ünlem işareti konur: 'Eyvah! Otobüsü kaçırdık.'"],"e":["Hangi cümlede ünlem kullanılmıştır?   A) Sabahtan beri yağmur yağıyor.   B) Senin için çiçek aldım.   C) Yaşasın, tatil başladı!   D) Çay veya kahve içebilirsin.","Doğru cevap: C) Yaşasın, tatil başladı!. \"Yaşasın, tatil başladı!\" cümlesinde ünlem vardır."]},"7:t7a":{"a":"Fiiller: Anlam Özellikleri","o":["Fiil: iş, oluş, hareket bildiren sözcük; -mek/-mak eki alabilir.","İş fiili: nesne alabilir, 'onu' sorusuna cevap verir (okumak → kitabı okumak).","Durum fiili: nesne almaz, öznenin durumunu anlatır (uyumak, oturmak, gülmek).","Oluş fiili: zamanla kendiliğinden olan değişim (büyümek, sararmak, acıkmak).","Kontrol: 'Onu ...-mak' denebiliyorsa iş fiilidir."],"t":["Varlıkların yaptığı işleri, hareketleri, içinde bulundukları durumları ya da geçirdikleri değişimleri anlatan sözcüklere fiil denir. Fiiller -mek/-mak mastar ekini alabilir: koşmak, yazmak, solmak.","Fiiller anlam bakımından üçe ayrılır. İş (kılış) fiilleri bir nesneyi etkiler ve 'onu' sorusuna cevap veren bir nesne alabilir: 'Kitabı okudu.' (onu okudu), 'Mektubu yazdı.' (onu yazdı). Yıkamak, kesmek, atmak, boyamak birer iş fiilidir.","Durum fiilleri öznenin durumunu anlatır, nesne almaz: uyumak, oturmak, gülmek, ağlamak, koşmak, durmak. 'Onu uyumak' diyemeyiz. Oluş fiilleri ise zaman içinde kendiliğinden gerçekleşen değişimleri anlatır: büyümek, sararmak, kızarmak, acıkmak, yaşlanmak, kararmak.","Bir fiilin türünü bulmak için önce 'onu ...-mak' kalıbını deneriz. Uyuyorsa iş fiilidir. Uymuyorsa, değişim bir süreçte kendiliğinden oluyorsa oluş, değilse durum fiilidir."],"e":["\"Ağaçların yaprakları sarardı.\" cümlesindeki \"sarardı\" fiili anlam bakımından hangisidir?   A) Durum fiili   B) Oluş fiili   C) İş fiili   D) Ek fiil","Doğru cevap: B) Oluş fiili. Zamanla kendiliğinden gerçekleşen bir değişimdir."]},"7:t7c":{"a":"Ek Fiil","o":["Ek fiil (i- fiili): isimleri yüklem yapar ya da çekimli fiillerin zamanını birleştirir.","Görevi 1 – İsim soylu sözcükleri yüklem yapar: Öğrenci-y-im. Hava güzel-di. Kapı açık-mış.","Görevi 2 – Birleşik zamanlı fiil yapar: geliyor-du (şimdiki zamanın hikâyesi), gelecek-miş (rivayet), gelse-ydi.","Ek fiilin kipleri: geniş zaman (-dir), hikâye (-di), rivayet (-miş), şart (-se).","Olumsuzu 'değil' ile yapılır: Hasta değilim."],"t":["Ek fiil, kendi başına kullanılmayan, eklendiği sözcüğe yüklem olma özelliği kazandıran ya da fiilin zamanını birleştiren 'i-' fiilidir. Ek fiilin dört kipi vardır: geniş zaman (-dir: Bu kitap güzel-dir), hikâye (-di: Hava soğuk-tu), rivayet (-miş: Çok yorgun-muş) ve şart (-se: Hasta-y-sa).","Ek fiilin birinci görevi isim soylu sözcükleri (isim, sıfat, zamir, zarf) yüklem yapmaktır: 'Ben öğrenci-y-im.' 'Annem öğretmen-di.' 'Hava çok güzel-miş.' Bu cümlelerde yüklem isimdir; ek fiil onu çekimlemiştir. Bu tür cümlelere isim cümlesi denir.","İkinci görevi çekimli fiillere gelerek birleşik zamanlı fiil oluşturmaktır: geliyor-du (şimdiki zamanın hikâyesi), gelmiş-ti (duyulan geçmiş zamanın hikâyesi), gelecek-miş (gelecek zamanın rivayeti), gelir-se (geniş zamanın şartı).","İsim cümlelerinin olumsuzu 'değil' sözcüğüyle yapılır: 'Ben yorgun değilim.' Ek fiil bazen yazıda görünmez: 'Ben öğrenciyim.' cümlesinde -(y)im ek fiildir."],"e":["Ek fiil ile ilgili hangisi yanlıştır?   A) 'koşuyordu' sözcüğünde ek fiil vardır.   B) Ek fiilin dört kipi vardır: geniş zaman, hikâye, rivayet ve şart.   C) 'geldi' sözcüğünde ek fiil vardır.   D) Ek fiil birleşik zamanlı fiil oluşturabilir.","Doğru cevap: C) 'geldi' sözcüğünde ek fiil vardır.. \"'geldi' sözcüğünde ek fiil vardır.\" ifadesi yanlıştır."]},"8:tur1k1":{"a":"İsim-Fiil, Sıfat-Fiil, Zarf-Fiil","o":["Fiilimsi: fiil kök/gövdesine gelen eklerle isim, sıfat ya da zarf görevinde kullanılan sözcük.","İsim-fiil ekleri: -ma, -ış, -mak → okumak, gülüş, yazma","Sıfat-fiil ekleri: -an, -ası, -mez, -ar, -dik, -ecek, -miş → koşan çocuk, gelecek yıl","Zarf-fiil ekleri: -ip, -arak, -ınca, -dıkça, -ken, -madan, -esiye, -alı, -r...-maz → gülerek geldi","Fiilimsiler olumsuzluk eki (-ma) alabilir; kip ve kişi eki almaz."],"t":["Fiilimsiler fiillerden türemiş ama cümlede isim, sıfat ya da zarf görevinde kullanılan sözcüklerdir. Fiil özelliklerini tam kaybetmezler: olumsuz yapılabilirler ve nesne, tümleç alabilirler; ancak çekimli fiil gibi kip ve şahıs eki almazlar. Bu yüzden yargı bildirmezler, cümleye yan anlam katarlar.","İsim-fiiller (-ma, -ış, -mak) işin adını bildirir: 'Kitap okumak beni dinlendirir.' Sıfat-fiiller (-an, -ası, -mez, -ar, -dık, -acak, -mış) bir ismi niteler: 'Okunacak kitaplar masada.' Zarf-fiiller (-ıp, -arak, -ınca, -dıkça, -ken, -madan, -alı, -ır...-maz) fiili zaman ya da durum yönünden niteler: 'Eve gelince haber ver.' Sıfat-fiilin nitelediği isim düşerse sıfat-fiil adlaşır: 'Gelenler oturdu.'"],"e":["\"Okumak insanı geliştirir.\" cümlesindeki fiilimsinin türü nedir?   A) İsim-fiil   B) Çekimli fiil   C) Sıfat-fiil   D) Zarf-fiil","Doğru cevap: A) İsim-fiil. \"-mak\" eki isim-fiil ekidir."]},"8:tur4k1":{"a":"Fiilde Çatı (Etken-Edilgen, Geçişli-Geçişsiz)","o":["Öznesine göre: Etken (özne belli) – Edilgen (özne belli değil, -l/-n eki): \"Cam kırıldı.\"","Nesnesine göre: Geçişli (nesne alabilir: okumak) – Geçişsiz (nesne alamaz: uyumak)","Edilgen fiillerde \"sözde özne\" bulunur.","Ettirgen ekleri (-dır, -t) fiili geçişli yapar: uyumak → uyutmak"],"t":["Fiilin çatısı öznesine ve nesnesine göre belirlenir. Öznesi belli olan fiiller etken, öznesi belli olmayan ve -l ya da -n eki alan fiiller edilgendir: 'Mektup yazıldı.' (Kim yazdı? Belli değil). Edilgen cümlede işten etkilenen öge sözde özne olur.","Nesne alabilen fiiller geçişli, nesne alamayanlar geçişsizdir. Bunu anlamak için fiile 'neyi, kimi?' sorusu sorulur: 'kitabı okudu' geçişli, 'erken uyudu' geçişsiz. Geçişsiz fiiller ettirgenlik ekleriyle geçişli hâle gelebilir: güldü → güldürdü."],"e":["Hangisinde fiil edilgen çatılıdır?   A) Duvarlar dün boyandı.   B) Ali duvarı boyadı.   C) Kardeşim koştu.   D) Çocuk erken uyudu.","Doğru cevap: A) Duvarlar dün boyandı.. İşi yapan belli değil; \"boyandı\" edilgendir."]},"8:tur2k1":{"a":"Temel ve Yardımcı Ögeler","o":["Yüklem: işi, oluşu, durumu bildiren temel öge (çekimli fiil ya da ek-fiil almış isim).","Özne: yüklemdeki işi yapan → \"kim/ne?\"","Nesne: işten etkilenen → belirtili \"neyi/kimi?\", belirtisiz \"ne?\"","Dolaylı tümleç: -e, -de, -den hâl ekli → \"nereye, nerede, nereden, kime?\"","Zarf tümleci: zaman, durum, yön, miktar → \"ne zaman, nasıl, ne kadar?\""],"t":["Ögeler bulunurken önce yüklem bulunur, sonra soruları yükleme sorarak özne ve diğer ögeler belirlenir. Söz grupları tek öge sayılır ve bölünmez: 'Bahçedeki yaşlı ağaç | dün akşamki fırtınada | devrildi.'","Özne, yükleme 'kim, ne' sorusu sorularak bulunur; edilgen cümlelerde sözde özne bulunur ('Kapı açıldı.'). Nesne yalnızca geçişli fiillerde bulunur. Dolaylı tümleç ismin -e, -de, -den hâllerini alır. Zarf tümleci yüklemi zaman, yer-yön, durum, miktar bakımından tamamlar."],"e":["\"Çocuklar parkta neşeyle oynadılar.\" cümlesinde zarf tümleci hangisidir?   A) Çocuklar   B) parkta   C) oynadılar   D) neşeyle","Doğru cevap: D) neşeyle. \"Nasıl oynadılar?\" sorusunun cevabıdır."]},"8:tur4k2":{"a":"Cümle Türleri","o":["Yüklemin türüne göre: isim cümlesi (yüklem isim) – fiil cümlesi (yüklem çekimli fiil)","Yüklemin yerine göre: kurallı (yüklem sonda) – devrik (yüklem sonda değil)","Anlamına göre: olumlu, olumsuz, soru, ünlem","Yapısına göre: basit (tek yargı), birleşik (fiilimsi/şart/ki/iç içe), sıralı (virgül/noktalı virgülle bağlı), bağlı (bağlaçla bağlı)"],"t":["Cümleler yüklemin türüne, yerine, anlamına ve yapısına göre sınıflandırılır. 'Hava çok güzel.' isim cümlesi, 'Hava ısındı.' fiil cümlesidir. Yüklemi sonda olan cümle kurallı, başta ya da ortada olan devrik cümledir.","Yapısına göre: tek yargı bildiren cümle basit; içinde fiilimsi ya da şart ekiyle kurulmuş yan cümle bulunan cümle birleşik; birden fazla bağımsız cümlenin virgül veya noktalı virgülle bağlandığı cümle sıralı; 've, ama, fakat' gibi bağlaçlarla bağlandığı cümle bağlı cümledir."],"e":["\"Kitabını okuyunca bana getir.\" cümlesi yapısına göre hangisidir?   A) Basit   B) Bağlı   C) Sıralı   D) Birleşik","Doğru cevap: D) Birleşik. \"okuyunca\" zarf-fiil → birleşik cümle."]},"8:tur4k3":{"a":"Anlatım Bozuklukları","o":["Gereksiz sözcük: aynı anlamı veren iki sözcük → \"kesinlikle doğru olan gerçek\"","Yanlış anlamda sözcük: \"Fiyatlar ucuzladı\" (fiyat düşer, mal ucuzlar)","Özne-yüklem uyumsuzluğu, ek eksikliği, öge eksikliği","Anlamca çelişen sözcükler: \"kesinlikle gelebilir\""],"t":["Anlatım bozukluğu, cümlenin söyleniş ya da yapı yönünden kusurlu olmasıdır. Anlama dayalı bozukluklarda gereksiz sözcük ('geri iade'), yanlış anlamda sözcük kullanımı ('Bu konuda tartışmasız haklısın' gibi çelişkiler) ya da sözcüklerin yanlış sıralanması görülür.","Yapıya dayalı bozukluklarda özne-yüklem uyumsuzluğu ('Siz bu işi bitirdi'), ortak öge kullanımı hatası ('Bu konuya inanıyor ve destekliyorum' — inanmak -e, desteklemek -i ister) ve ek eksikliği görülür. Ortak kullanılan ögenin her iki yükleme de uyup uymadığı kontrol edilmelidir."],"e":["\"Çocuklar parkta oynuyor ve ağaçlara zarar verildi.\" cümlesindeki bozukluğun nedeni nedir?   A) Sözcüğün yanlış anlamda kullanılması   B) Çatı uyumsuzluğu   C) Gereksiz sözcük   D) Yazım hatası","Doğru cevap: B) Çatı uyumsuzluğu. Etken ve edilgen yüklemler aynı özneye bağlanmış."]},"9:mat1k3":{"a":"Sayı Kümeleri ve İşlem Özellikleri","o":["ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ · İrrasyonel sayılar (𝕀): √2, π, e","ℚ ∪ 𝕀 = ℝ ve ℚ ∩ 𝕀 = ∅","Kapalılık: bir kümede işlemin sonucu yine o kümede mi? (ℕ çıkarmaya göre kapalı değil: 2 − 5 = −3)","Değişme, birleşme, dağılma özellikleri; etkisiz eleman (toplamada 0, çarpmada 1); ters eleman","İki irrasyonelin toplamı/çarpımı rasyonel olabilir: √2 · √2 = 2"],"t":["Sayı kümeleri iç içe genişler: doğal sayılar, tam sayılar, rasyonel sayılar ve gerçek sayılar. a/b (b ≠ 0) biçiminde yazılamayan sayılar irrasyoneldir; rasyonel ve irrasyonel sayılar birlikte gerçek sayıları oluşturur.","Bir kümenin bir işleme göre kapalı olması, o kümeden alınan her iki elemanın işlem sonucunun yine o kümede olmasıdır. Doğal sayılar toplamaya göre kapalıdır ama çıkarmaya göre değildir; tam sayılar bölmeye göre kapalı değildir (1 ÷ 2 ∉ ℤ). Bir iddianın yanlış olduğunu göstermek için tek bir karşı örnek yeterlidir; doğru olduğunu göstermek için ise genel bir gerekçe gerekir."],"e":["s(A) = 9, s(B) = 20 ve s(A ∩ B) = 6 ise s(A ∪ B) kaçtır?   A) 35   B) 23   C) 3   D) 29","Doğru cevap: B) 23. s(A ∪ B) = s(A) + s(B) − s(A ∩ B)."]},"6:t3k1":{"a":"Ondalık Gösterimde Basamak Değeri","o":["Virgülün solu tam kısım, sağı ondalık kısım.","Onda birler (0,1) · Yüzde birler (0,01) · Binde birler (0,001)","34,256 → 5'in basamak değeri 0,05","Sona eklenen sıfır değeri değiştirmez: 3,6 = 3,60"],"t":["Ondalık gösterimde virgülün solu tam kısım, sağı ondalık kısımdır. 34,256 → 34 tam 256 binde.","Virgülün sağındaki basamaklar sırasıyla: onda birler, yüzde birler, binde birler.","34,256 sayısında 2'nin basamak değeri 0,2; 5'in 0,05; 6'nın 0,006'dır.","Ondalık gösterimler çözümlenerek de yazılabilir: 4,37 = 4 + 0,3 + 0,07."],"e":["50,237 sayısında 7 rakamının basamak değeri kaçtır?   A) 0,007   B) 7   C) 0,07   D) 0,7","Doğru cevap: A) 0,007. 7 rakamı binde birler basamağında. Basamak değeri 0,007."],"h":"Basamak sayısı çok olan ondalık sayıyı daha büyük sanmak (3,405 < 3,45)."},"10:mat1k1":{"a":"Bölünebilme, Asal Sayılar, EBOB ve EKOK","o":["Asal sayı: 1'den büyük, yalnızca 1'e ve kendisine bölünen sayı (2, 3, 5, 7, 11, 13 …). 2 tek çift asaldır.","Asal çarpanlara ayırma: 360 = 2³ · 3² · 5 → pozitif bölen sayısı (3+1)(2+1)(1+1) = 24","Bölünebilme: 3 → rakamlar toplamı 3'ün katı · 4 → son iki basamak · 9 → rakamlar toplamı · 11 → (birler − onlar + yüzler …) 11'in katı","EBOB: ortak asal çarpanların en küçük üslüleri · EKOK: bütün asal çarpanların en büyük üslüleri","a · b = EBOB(a, b) · EKOK(a, b)"],"t":["Her doğal sayı asal çarpanlarına tek biçimde ayrılır (aritmetiğin temel teoremi). Bu ayrılış, bölen sayısını, EBOB'u ve EKOK'u bulmanın en güvenli yoludur. Örneğin 84 = 2² · 3 · 7 ve 90 = 2 · 3² · 5 için EBOB = 2 · 3 = 6, EKOK = 2² · 3² · 5 · 7 = 1260'tır.","EBOB problemleri genellikle 'en büyük eş parça', 'en az sayıda eş kutu' gibi bölme durumlarında; EKOK problemleri ise 'aynı anda tekrar', 'en az kaç' gibi tekrar eden olaylarda kullanılır."],"e":["1200 sayısının pozitif bölen sayısı kaçtır?   A) 30   B) 10   C) 8   D) 32","Doğru cevap: A) 30. 1200 = 2^4·3^1·5^2 → 30"]},"8:mat1k2":{"a":"EBOB, EKOK ve Aralarında Asal Sayılar","o":["EBOB: sayıların ortak bölenlerinin en büyüğü (ortak asal çarpanların en küçük üslüleri).","EKOK: sayıların ortak katlarının en küçüğü (bütün asal çarpanların en büyük üslüleri).","a · b = EBOB(a,b) · EKOK(a,b)","EBOB'u 1 olan sayılara aralarında asal denir: 8 ve 15 gibi.","Parçalara ayırma, en büyük kare → EBOB; tekrar karşılaşma, en küçük ortak süre → EKOK."],"t":["İki ya da daha fazla doğal sayının ortak bölenlerinin en büyüğüne EBOB, ortak katlarının en küçüğüne EKOK denir. 12 = 2²·3 ve 18 = 2·3² için EBOB = 2·3 = 6, EKOK = 2²·3² = 36'dır.","Problemlerde bir bütünü eşit ve en büyük parçalara bölmek EBOB, farklı aralıklarla tekrarlanan olayların yeniden aynı anda gerçekleşmesi EKOK ile çözülür. Ortak böleni yalnızca 1 olan sayılara aralarında asal sayılar denir; aralarında asal iki sayının EKOK'u çarpımlarına eşittir."],"e":["Bir lamba 15 saniyede, diğeri 4 saniyede bir yanıyor. Birlikte yandıktan en az kaç saniye sonra yine birlikte yanarlar?   A) 19   B) 75   C) 60   D) 1","Doğru cevap: C) 60. EKOK(15, 4) = 60"]},"7:m1k3":{"a":"Rasyonel Sayılar ve Ondalık Gösterim","o":["Rasyonel sayı: a/b şeklinde yazılabilen sayı (a, b tam sayı, b ≠ 0).","Tam sayılar da rasyoneldir: −4 = −4/1","Kesri ondalığa çevirmek için pay paydaya bölünür: 3/8 = 0,375","Devirli ondalık: 1/3 = 0,333... = 0,3̅","Sıralama: önce işarete, sonra değere bakılır. Negatiflerde mutlak değeri büyük olan küçüktür."],"t":["a ve b tam sayı, b sıfırdan farklı olmak üzere a/b şeklinde yazılabilen sayılara rasyonel sayılar denir. 3/4, −2/5, 0,7 ve −6 birer rasyonel sayıdır. Doğal sayılar tam sayıların, tam sayılar rasyonel sayıların içindedir.","Bir rasyonel sayıyı ondalık gösterimle yazmak için pay paydaya bölünür: 7/20 = 0,35; −5/8 = −0,625. Bazı bölmeler bitmez ve rakamlar tekrar eder: 2/3 = 0,666...; tekrar eden kısmın üstüne çizgi çekilir: 0,6̅. Bunlara devirli ondalık gösterim denir.","Rasyonel sayılar sayı doğrusunda gösterilebilir. Pozitifler sıfırın sağında, negatifler solundadır. Negatif sayılarda mutlak değeri büyük olan daha küçüktür: −3/4 < −1/2.","Karşılaştırma yaparken paydaları eşitlemek ya da ondalık gösterime çevirmek işi kolaylaştırır: 2/5 = 0,4 ve 3/8 = 0,375 olduğundan 2/5 > 3/8."],"e":["3/8, 1/4, −1/2, −3/4 sayılarından en küçüğü hangisidir?   A) 3/8   B) −3/4   C) 1/4   D) −1/2","Doğru cevap: B) −3/4. Negatif sayılarda mutlak değeri büyük olan daha küçüktür."]},"9:mat1k2":{"a":"Gerçek Sayı Aralıkları","o":["Kapalı aralık [a, b]: a ≤ x ≤ b (uçlar dahil) · Açık aralık (a, b): a < x < b","Yarı açık: [a, b) → a ≤ x < b · (a, b] → a < x ≤ b","Sonsuz aralık: [a, ∞) → x ≥ a · (−∞, b) → x < b (∞ her zaman açık parantez)","Kesişim (∩): iki aralığın ortak kısmı · Birleşim (∪): en az birinde olanlar","Sayı doğrusunda dahil olan uç: dolu nokta · dahil olmayan: boş nokta"],"t":["Gerçek sayılar sayı doğrusundaki tüm noktalara karşılık gelir; iki gerçek sayı arasında sonsuz tane gerçek sayı vardır. Bu yüzden belirli bir sınır arasındaki sayılar aralık gösterimiyle yazılır. Köşeli parantez ucun dahil olduğunu, normal parantez dahil olmadığını gösterir.","Aralıklarla kesişim, birleşim ve fark işlemleri sayı doğrusu üzerinde gösterilerek yapılır. Örneğin A = [−2, 5) ve B = (1, 8] için A ∩ B = (1, 5), A ∪ B = [−2, 8], A \\ B = [−2, 1] olur. Sonsuzluk bir sayı olmadığı için her zaman açık uçla yazılır."],"e":["−3 < x < 2 eşitsizliğinin aralık gösterimi hangisidir?   A) [−3, 2)   B) (−3, 2)   C) [−3, 2]   D) (−3, 2]","Doğru cevap: B) (−3, 2). Dahil olmayan uç normal parantez."]},"9:mat1k1":{"a":"Üslü ve Köklü Gösterimlerle İşlemler","o":["aⁿ · aᵐ = aⁿ⁺ᵐ · aⁿ ÷ aᵐ = aⁿ⁻ᵐ · (aⁿ)ᵐ = aⁿ·ᵐ · a⁰ = 1 (a ≠ 0) · a⁻ⁿ = 1/aⁿ","Köklü ↔ üslü: ⁿ√(aᵐ) = a^(m/n) → √a = a^(1/2), ∛8 = 8^(1/3) = 2","√a · √b = √(ab) · √a ÷ √b = √(a/b) (a, b ≥ 0)","Toplamada kök içleri aynı olmalı: 2√3 + 5√3 = 7√3","Paydayı kökten kurtarma: 1/√2 = √2/2 · 1/(√3 − 1) = (√3 + 1)/2 (eşleniğiyle çarp)"],"t":["Üslü gösterim aynı çarpanın tekrarını, köklü gösterim ise bu işlemin tersini ifade eder. Bir sayının n'inci kuvvetten kökü, üssü 1/n olan kuvvetine eşittir: ⁿ√a = a^(1/n). Böylece köklü ifadelerdeki işlemler üslü ifadelerin kurallarıyla yapılabilir: ∛(2⁶) = 2^(6/3) = 2².","Bu konuda yalnızca işlem yapmak değil, kuralların neden doğru olduğunu gerekçelendirmek de beklenir. Örneğin aⁿ · aᵐ = aⁿ⁺ᵐ kuralı, n tane a ile m tane a'nın çarpımında toplam n + m tane a bulunmasından gelir. a⁰ = 1 olması ise aⁿ ÷ aⁿ = 1 = aⁿ⁻ⁿ eşitliğinden çıkar. Ortak sınavda 'Bir öğrencinin iddiasını değerlendiriniz' türünde, örnek ya da karşı örnekle gerekçe isteyen sorular gelir.","Paydada köklü ifade bulunduğunda pay ve payda paydanın eşleniğiyle çarpılır: (√a − √b)(√a + √b) = a − b olduğundan payda rasyonel olur."],"e":["√150 + √6 − √24 işleminin sonucu hangisidir?   A) 5√6   B) 8√6   C) √132   D) 4√6","Doğru cevap: D) 4√6. 5√6 + 1√6 − 2√6"]},"8:mat3k1":{"a":"Tam Kareler ve Karekök","o":["Tam kare: bir doğal sayının karesi: 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, 121, 144...","√a, karesi a olan negatif olmayan sayıdır: √49 = 7","Tam kare olmayan sayının karekökü iki ardışık doğal sayı arasındadır: 6 < √40 < 7","Karekök dışına çıkarma: √72 = √(36·2) = 6√2"],"t":["Karesi alındığında a sayısını veren negatif olmayan sayıya a'nın karekökü denir ve √a ile gösterilir. Kenar uzunluğu √a olan karenin alanı a'dır. Tam kare sayıların karekökleri doğal sayıdır.","Tam kare olmayan bir sayının karekökü irrasyoneldir ve en yakın tam karelere bakarak tahmin edilir: 25 < 30 < 36 olduğundan 5 < √30 < 6; 30, 25'e daha yakın olduğundan √30 ≈ 5,5. Karekök içindeki sayı, çarpanlarından biri tam kare olacak şekilde yazılarak a√b biçimine getirilir: √50 = 5√2."],"e":["√178 sayısı hangi iki ardışık doğal sayı arasındadır?   A) 89 ile 90   B) 14 ile 15   C) 13 ile 14   D) 12 ile 13","Doğru cevap: C) 13 ile 14. 169 < 178 < 196"]},"9:mat1k4":{"a":"Özdeşlikler: Tam Kare ve İki Kare Farkı","o":["(a + b)² = a² + 2ab + b² · (a − b)² = a² − 2ab + b²","a² − b² = (a − b)(a + b)","Alan modeli: kenarı (a + b) olan kare = a² + b² + iki tane ab dikdörtgeni","Sayılarla ilişki: 47 · 53 = (50 − 3)(50 + 3) = 2500 − 9 = 2491","a + b ve ab biliniyorsa: a² + b² = (a + b)² − 2ab"],"t":["Özdeşlikler, değişkenlerin aldığı her değer için doğru olan eşitliklerdir. (a + b)² özdeşliği geometrik olarak kenarı a + b olan karenin alanının; kenarı a olan kare, kenarı b olan kare ve iki tane a·b dikdörtgeninin alanları toplamına eşit olmasıyla gösterilir.","İki kare farkı özdeşliği, kenarı a olan kareden kenarı b olan kare çıkarıldığında kalan parçanın kesilip (a − b) ve (a + b) kenarlı bir dikdörtgene dönüştürülmesiyle modellenir. Bu özdeşlikler hem hesaplamayı kolaylaştırır hem de sayı örüntülerindeki genellemelerin kanıtlanmasında kullanılır: ardışık iki tam sayının kareleri farkı bu sayıların toplamına eşittir, çünkü (n + 1)² − n² = 2n + 1."],"e":["34 · 26 işleminin sonucu kaçtır?   A) 916   B) 900   C) 892   D) 884","Doğru cevap: D) 884. (30 + 4)(30 − 4) = 900 − 16 = 884."]},"7:m2k1":{"a":"Oran ve Birim Oran","o":["Oran: iki çokluğun bölme yoluyla karşılaştırılması. a/b ya da a : b","Aynı birimdeki çokluklar → birimsiz oran (3 kg / 5 kg = 3/5)","Farklı birimdeki çokluklar → birimli oran (120 km / 2 sa = 60 km/sa)","Birim oran: paydası 1 olan oran (1 kg'ın fiyatı, 1 saatte gidilen yol)","Oranın terimleri 0 hariç aynı sayıyla çarpılıp bölünebilir."],"t":["İki çokluğun bölme işlemiyle karşılaştırılmasına oran denir ve a/b ya da a : b şeklinde gösterilir. Bir sınıftaki 12 kız ve 15 erkek öğrencinin oranı 12/15 = 4/5'tir.","Aynı birimle ölçülen çoklukların oranı birimsizdir: 6 m'nin 9 m'ye oranı 2/3. Farklı birimlerle ölçülen çoklukların oranı ise birimlidir: 300 TL / 5 kg = 60 TL/kg.","Paydası 1 olacak şekilde yazılan orana birim oran denir. Birim oran karşılaştırma yapmayı kolaylaştırır: 4 kg'ı 100 TL olan elma ile 3 kg'ı 81 TL olan elmanın 1 kg fiyatları 25 TL ve 27 TL'dir; ilki daha ucuzdur.","Oranlar sadeleştirilebilir ya da genişletilebilir. Eşit oranlara denk oranlar denir: 2/3 = 8/12."],"e":["6 saatte 600 km yol giden bir aracın 1 saatte aldığı yol kaç km'dir?   A) 200   B) 100   C) 110   D) 594","Doğru cevap: B) 100. 600 ÷ 6 = 100 km/sa"]},"8:mat7k1":{"a":"Birinci Dereceden Bir Bilinmeyenli Denklemler","o":["Eşitliğin iki tarafına aynı işlem yapılır, eşitlik bozulmaz.","Bilinmeyenler bir tarafa, sayılar diğer tarafa toplanır.","Parantez varsa önce dağılma: 3(x − 2) = 3x − 6","Problem → değişkeni tanımla, denklemi kur, çöz, kontrol et."],"t":["İçinde bilinmeyen bulunan ve bilinmeyenin üssü 1 olan eşitliklere birinci dereceden bir bilinmeyenli denklemler denir. 3x + 5 = 20 denkleminde her iki taraftan 5 çıkarılır (3x = 15), sonra her iki taraf 3'e bölünür (x = 5).","Kesirli denklemlerde paydalar eşitlenir ya da her iki taraf paydaların EKOK'u ile çarpılır: x/2 + x/3 = 10 → 3x + 2x = 60 → x = 12. Bulunan değer denklemde yerine yazılarak kontrol edilir."],"e":["5x + 8 = 3x + 8 denkleminin çözümü kaçtır?   A) 0   B) 8   C) 2   D) 1","Doğru cevap: A) 0. 2x = 0 → x = 0"]},"7:m1k4":{"a":"Rasyonel Sayılarla İşlemler ve Problemler","o":["Toplama-çıkarma: paydalar eşitlenir, işaret kuralları uygulanır.","Çarpma: paylar çarpılıp paya, paydalar çarpılıp paydaya yazılır.","Bölme: birinci ile ikincinin çarpmaya göre tersi çarpılır: a/b ÷ c/d = a/b · d/c","İşlem önceliği: parantez → üs → çarpma-bölme → toplama-çıkarma"],"t":["Rasyonel sayılarla toplama ve çıkarma yaparken paydalar eşitlenir, paylar işaret kurallarına göre toplanır ya da çıkarılır: −1/2 + 3/4 = −2/4 + 3/4 = 1/4.","Çarpmada paylar kendi arasında, paydalar kendi arasında çarpılır; mümkünse önce sadeleştirme yapılır: (−2/3) · (9/4) = −18/12 = −3/2.","Bölmede ikinci sayının çarpmaya göre tersi (payı ile paydasının yer değiştirmiş hâli) alınarak çarpma yapılır: 3/5 ÷ (−6/10) = 3/5 · (−10/6) = −1.","Problemlerde 'bir bütünün kesri' ifadesine dikkat ederiz: 'Bir su deposunun 3/5'i dolu, depodan 1/4'ü kadar su kullanıldı' gibi. Ondalık gösterimle de işlem yapılabilir: 2,5 − (−1,25) = 3,75."],"e":["5,5 − (−7,75) işleminin sonucu kaçtır?   A) 13,25   B) −13,25   C) 14,25   D) −2,25","Doğru cevap: A) 13,25. 5,5 − −7,75 = 13,25"]},"7:m2k3":{"a":"Doğru Orantı Problemleri ve Yüzdeler","o":["Doğru orantı problemlerinde birim orana ya da orantı kurmaya başvurulur.","Ölçek (harita): 1/100 000 → haritada 1 cm = gerçekte 100 000 cm = 1 km","Yüzde: paydası 100 olan oran. %20 = 20/100","Yüzde artış/azalış: yeni = eski × (100 ± yüzde)/100","Tarif: 4 kişilik tarif 6 kişiye uyarlanırken her malzeme 6/4 ile çarpılır."],"t":["Doğru orantı problemlerini birim oranı bularak ya da orantı kurarak çözeriz. Örnek: 3 kg elma 72 TL ise 7 kg elma kaç TL? Birim oran: 72 ÷ 3 = 24 TL; 7 × 24 = 168 TL. Ya da 3/72 = 7/x → x = 168.","Haritalarda ölçek bir doğru orantıdır. 1/200 000 ölçekli haritada 3 cm, gerçekte 600 000 cm = 6 km'dir.","Yüzdeler de birer orandır. Bir ürünün fiyatına %25 zam yapılırsa yeni fiyat eski fiyatın 125/100'üdür; %20 indirim yapılırsa yeni fiyat eski fiyatın 80/100'üdür.","Yemek tariflerini kişi sayısına göre uyarlamak, kur hesapları ve yakıt tüketimi gibi pek çok günlük hayat durumu doğru orantıyla çözülür."],"e":["Bir araç 100 km'de 6 L benzin harcıyor. 200 km yolda kaç L benzin harcar?   A) 120   B) 8   C) 33   D) 12","Doğru cevap: D) 12. 6 × 200/100 = 12 L"]},"10:mat3k1":{"a":"Veri Toplama, Grafikler ve Merkezî Eğilim","o":["Araştırma süreci: soru oluşturma → veri toplama → verileri düzenleme/gösterme → yorumlama","Nitel veri (renk, tür) · nicel veri (boy, puan): kesikli ya da sürekli","Aritmetik ortalama = toplam / veri sayısı · Medyan: sıralı verinin ortası · Mod: en çok tekrar eden","Açıklık = en büyük − en küçük · Çeyrekler açıklığı = Q3 − Q1","Kutu grafiği uç değerleri ve yayılımı gösterir; histogram sürekli veride sıklığı gösterir"],"t":["İyi bir istatistiksel soru, cevabı verilerde değişkenlik beklenen sorudur ('Sınıfımızdaki öğrenciler günde kaç saat uyuyor?'). Örneklem, evreni temsil edecek biçimde seçilmelidir; yanlı örneklem yanlış sonuç verir.","Uç değerler aritmetik ortalamayı çok etkiler, medyanı az etkiler. Bu yüzden gelir gibi uç değer içeren verilerde medyan daha temsilî olabilir."],"e":["5, 7, 7, 5, 10 veri grubunun medyanı kaçtır?   A) 8   B) 5   C) 10   D) 7","Doğru cevap: D) 7. Sıralı: 5, 5, 7, 7, 10 → ortadaki 7"]},"12:lm2a":{"a":"Bağlaçlar ve Doğruluk Tabloları","o":["Değil (¬p): önermenin doğruluk değerini tersine çevirir","Ve (p ∧ q): yalnızca ikisi de doğruysa doğru","Veya (p ∨ q): yalnızca ikisi de yanlışsa yanlış","İse (p → q): yalnızca p doğru, q yanlışken yanlış","Ancak ve ancak (p ↔ q): ikisi aynı değerdeyse doğru"],"t":["Sembolik (modern) mantık, önermeleri p, q, r gibi harflerle, aralarındaki bağlantıları da sembollerle gösterir. Bir önermenin doğruluk değeri doğru (D ya da 1) veya yanlış (Y ya da 0) olabilir. 'Değil' (¬) bağlacı değeri tersine çevirir: p doğruysa ¬p yanlıştır.","'Ve' bağlacıyla (p ∧ q) kurulan bileşik önerme yalnızca iki önerme de doğruysa doğrudur. 'Veya' bağlacıyla (p ∨ q) kurulan önerme ise önermelerden en az biri doğruysa doğrudur; yalnızca ikisi de yanlışken yanlış olur. 'Bugün cumartesi ve hava güneşli' cümlesinin doğru olması için iki durumun da gerçekleşmesi gerekir.","'İse' bağlacı (p → q) koşul bildirir: 'Ödevini bitirirsen maça gidersin.' Bu önerme yalnızca p doğru ve q yanlış olduğunda, yani ödev bitirildiği hâlde maça gidilemediğinde yanlıştır; ödev bitmemişse söz bozulmuş sayılmaz. 'Ancak ve ancak' bağlacı (p ↔ q) ise iki önermenin değeri aynı olduğunda doğrudur."],"e":["p: '2 + 2 = 4' (D), q: '5 bir çift sayıdır' (Y). p ∧ q, p ∨ q ve p → q'nun doğruluk değerleri nedir?","p ∧ q = Y (ikisi birden doğru değil); p ∨ q = D (en az biri doğru); p → q = Y (p doğru, q yanlış)."],"h":"'İse' bağlacında p yanlışken önermeyi yanlış saymak: p yanlışsa p → q her zaman doğrudur."},"9:mat2k1":{"a":"Fonksiyon Kavramı ve Gösterimleri","o":["Fonksiyon: tanım kümesindeki her elemanı değer kümesinde yalnız bir elemanla eşleyen kural","Gösterimler: sözel, tablo, cebirsel (f(x) = 2x + 1), grafik","Düşey doğru testi: her düşey doğru grafiği en fazla bir noktada kesiyorsa fonksiyondur.","Görüntü kümesi: f(A), değer kümesinin alt kümesidir.","f(a) değeri: x yerine a yazılarak bulunur."],"t":["Bir niceliğin başka bir niceliğe bağlı olarak değişimi fonksiyonlarla modellenir. Örneğin bir taksinin ücreti gidilen yola bağlıdır. A kümesinin her elemanı B kümesinden yalnız bir elemanla eşleniyorsa bu bağıntı A'dan B'ye bir fonksiyondur; A tanım, B değer kümesidir. Tanım kümesinde açıkta kalan eleman olmamalı, bir eleman iki farklı elemanla eşlenmemelidir.","Fonksiyonlar tablo, grafik, cebirsel ifade ya da sözel olarak gösterilebilir ve bu gösterimler birbirine dönüştürülebilir. Grafik bir fonksiyon belirtiyorsa x eksenine dik çizilen her doğru grafiği en fazla bir noktada keser."],"e":["f(x) = −1x + 2 ise f(−2) kaçtır?   A) −3   B) 0   C) −1   D) 4","Doğru cevap: D) 4. −1·(−2) + 2 = 4"]},"10:mat4k1":{"a":"İkinci Dereceden, Karekök ve Rasyonel Fonksiyonlar","o":["f(x) = ax² + bx + c → parabol; tepe noktası r = −b/2a, k = f(r)","a > 0 kollar yukarı (en küçük değer k) · a < 0 kollar aşağı (en büyük değer k)","Δ = b² − 4ac: Δ > 0 iki kök, Δ = 0 tek (çakışık) kök, Δ < 0 gerçek kök yok","f(x) = √x → tanım kümesi x ≥ 0 · f(x) = 1/x → x ≠ 0, asimptotlar x = 0 ve y = 0","Fonksiyon dönüşümleri: f(x − a) sağa a, f(x) + b yukarı b birim öteleme"],"t":["İkinci dereceden fonksiyonlar sabit ivmeli hareket, alan ve kâr problemlerinde değişimi modeller. Grafiğin simetri ekseni x = r doğrusudur; köklerin aritmetik ortalaması da r'dir.","Rasyonel fonksiyonlarda paydayı sıfır yapan değerler tanım kümesinden çıkarılır. f(x) = 1/x grafiği eksenlere yaklaşır ama onları kesmez; ters orantılı nicelikler bu biçimde değişir."],"e":["x² + x − 2 = 0 denkleminin kökler toplamı kaçtır?   A) 1   B) −2   C) −1   D) 2","Doğru cevap: C) −1. x₁ + x₂ = −b/a"]},"10:mat5k1":{"a":"Sayma Yöntemleri ve Algoritma","o":["Toplama yoluyla sayma: ayrık durumlar toplanır · Çarpma yoluyla sayma: ardışık seçimler çarpılır","n! = n · (n − 1) · … · 1 · n farklı nesnenin sıralanışı n!","Permütasyon P(n, r) = n! / (n − r)! (sıra önemli) · Kombinasyon C(n, r) = n! / (r!(n − r)!) (sıra önemsiz)","Algoritma: bir problemi çözen sonlu, açık ve sıralı adımlar; akış şemasıyla gösterilebilir"],"t":["Saymada önce 'sıra önemli mi?' sorusu sorulur. Bir sınıftan başkan ve yardımcı seçmek sıra önemli (permütasyon), 3 kişilik komisyon seçmek sıra önemsiz (kombinasyon) bir seçimdir.","Algoritmalar, adımları belirsizlik bırakmadan yazmayı gerektirir: girdiler, işlemler, karar adımları (eğer … ise) ve çıktı açıkça belirtilir."],"e":["10 kişiden 2 kişilik bir grup kaç farklı biçimde seçilir?   A) 10   B) 90   C) 45   D) 20","Doğru cevap: C) 45. C(10, 2) = 45"]},"10:mat5k2":{"a":"Veriden Olasılığa","o":["Deneysel olasılık = olayın gözlenme sayısı / deneme sayısı","Teorik olasılık P(A) = istenen durum sayısı / tüm (eş olası) durum sayısı","0 ≤ P(A) ≤ 1 · P(A') = 1 − P(A)","Deneme sayısı arttıkça deneysel olasılık teorik olasılığa yaklaşır (büyük sayılar yasası)"],"t":["Bir zar 60 kez atılıp 12 kez 6 gelirse 6 gelmenin deneysel olasılığı 12/60 = 1/5'tir; teorik olasılığı ise 1/6'dır. Deneme sayısı arttıkça deneysel değerin 1/6'ya yaklaşması beklenir.","Olasılık hesaplarken örnek uzayın eş olası çıktılardan oluştuğundan emin olunmalıdır. İki zar atıldığında toplamların olasılıkları eşit değildir: toplam 7, 36 çıktıdan 6'sında gelir."],"e":["İki zar atıldığında üst yüzlerdeki sayıların toplamının 9 olma olasılığı kaçtır?   A) 5/36   B) 1/9   C) 1/6   D) 1/12","Doğru cevap: B) 1/9. 36 durumdan 4 tanesi"]},"6:t5k1":{"a":"Paralel Doğrular ve Kesenle Oluşan Açılar","o":["Yöndeş açılar eşittir.","İç ters açılar eşittir. Dış ters açılar eşittir.","Bir doğru üzerinde yan yana açılar: toplam 180°","Kesenin aynı tarafında, paralellerin arasındaki iki açı: toplam 180°","8 açıda yalnızca 2 farklı ölçü olur: a ve 180° − a"],"t":["İki paralel doğruyu kesen bir doğruya kesen denir. Kesenle birlikte 8 açı oluşur.","Yöndeş açılar: Aynı yöne bakan açılardır, ölçüleri eşittir.","İç ters açılar ve dış ters açılar: Kesenin farklı taraflarında, paralellerin içinde (veya dışında) kalan açılardır, ölçüleri eşittir.","Yan yana duran ve bir doğru üzerinde olan açıların toplamı 180°'dir. Kesenin aynı tarafında, paralellerin arasında kalan iki açının toplamı da 180°'dir."],"e":["İki paralel doğruyu bir kesen kesiyor. Yöndeş açılardan biri 125° ise diğeri kaç derecedir?   A) 35°   B) 55°   C) 125°   D) 250°","Doğru cevap: C) 125°. Yöndeş açıların ölçüleri eşittir."]},"9:mat3k1":{"a":"Üçgenlerde Açı ve Kenar Bağıntıları","o":["İç açılar toplamı 180° · Bir dış açı, kendisine komşu olmayan iki iç açının toplamına eşittir.","Üçgen eşitsizliği: |b − c| < a < b + c","Büyük kenar karşısında büyük açı bulunur.","İkizkenar üçgende taban açıları eşittir; eşkenar üçgende tüm açılar 60°.","Pisagor: dik üçgende a² + b² = c²"],"t":["Üçgenin iç açılarının toplamının 180° olduğu, bir köşeden karşı kenara paralel çizilerek ve iç ters açılar kullanılarak gösterilir. Bir dış açı, komşu olmayan iki iç açının toplamına eşittir; çünkü dış açı ile komşu iç açı 180°'yi tamamlar.","Üçgen eşitsizliği, bir kenarın diğer iki kenarın toplamından küçük, farkından büyük olmasıdır; aksi hâlde kenarlar birleşip üçgen oluşturamaz. Kenar ve açı arasındaki ilişkiye göre en uzun kenarın karşısında en büyük açı bulunur."],"e":["Tepe açısı 124° olan ikizkenar üçgenin bir taban açısı kaç derecedir?   A) 38   B) 56   C) 28   D) 124","Doğru cevap: C) 28. (180 − 124) ÷ 2 = 28."]},"10:mat2k1":{"a":"Dik Üçgende Trigonometrik Oranlar","o":["sin α = karşı dik kenar / hipotenüs · cos α = komşu dik kenar / hipotenüs","tan α = karşı / komşu · cot α = komşu / karşı","Tümler açılar: sin α = cos(90° − α), tan α = cot(90° − α)","Özel üçgenler: 30-60-90 → kenarlar 1 : √3 : 2 · 45-45-90 → 1 : 1 : √2","sin²α + cos²α = 1"],"t":["Trigonometrik oranlar, dik üçgende bir dar açıya göre kenarların oranıdır; üçgenin büyüklüğüne değil, yalnızca açıya bağlıdır. Bu yüzden benzer dik üçgenlerde aynı açının oranları eşittir.","Özel değerler: sin 30° = 1/2, sin 45° = √2/2, sin 60° = √3/2; cos 30° = √3/2, cos 60° = 1/2; tan 45° = 1, tan 60° = √3. Yükseklik, gölge ve eğim problemleri bu oranlarla çözülür."],"e":["Hipotenüsü 14 olan dik üçgende 60°'lik açıya komşu dik kenar kaçtır?   A) 21   B) 9   C) 14   D) 7","Doğru cevap: D) 7. cos 60° = 1/2"]},"8:mat9k1":{"a":"Üçgende Kenarortay, Açıortay, Yükseklik ve Üçgen Eşitsizliği","o":["Kenarortay: köşeyi karşı kenarın orta noktasına birleştirir.","Açıortay: açıyı iki eş parçaya böler · Yükseklik: köşeden karşı kenara dik.","Üçgen eşitsizliği: |a − b| < c < a + b","Büyük kenarın karşısında büyük açı bulunur."],"t":["Üçgenin bir köşesini karşı kenarın orta noktasına birleştiren doğru parçasına kenarortay, bir açıyı iki eş açıya ayıran ışına açıortay, bir köşeden karşı kenara çizilen dik doğru parçasına yükseklik denir. Her üçgende üçer tane kenarortay, açıortay ve yükseklik vardır.","Bir üçgenin herhangi bir kenarı, diğer iki kenarın toplamından küçük, farkından büyüktür. Örneğin kenarları 5 ve 8 olan bir üçgende üçüncü kenar 3 ile 13 arasındadır. Üçgende büyük kenar karşısında büyük açı bulunur."],"e":["Dik kenarları 5 ve 12 birim olan dik üçgenin hipotenüsü kaç birimdir?   A) 17   B) 13   C) 14   D) 12","Doğru cevap: B) 13. 5² + 12² = 169 → 13."]},"9:mat3k2":{"a":"Eşlik ve Benzerlik","o":["Eşlik kuralları: KKK, KAK, AKA","Benzerlik kuralları: AA, KAK (oranlı), KKK (oranlı)","Benzerlik oranı k ise çevreler oranı k, alanlar oranı k²","Temel orantı teoremi: üçgende bir kenara paralel doğru diğer kenarları orantılı böler."],"t":["İki üçgenin eş olduğunu göstermek için tüm kenar ve açıları karşılaştırmak gerekmez; KKK, KAK ve AKA kurallarından biri yeterlidir. Eş üçgenlerin karşılıklı tüm elemanları eşittir.","İki üçgenin karşılıklı açıları eşit ise üçgenler benzerdir (AA). Benzer üçgenlerde karşılıklı kenarlar orantılıdır; benzerlik oranı k ise çevreler oranı da k, alanlar oranı k²'dir. Benzerlik; gölge boyu, harita ölçeği ve ulaşılamayan uzunlukların hesaplanmasında kullanılır."],"e":["1/200000 ölçekli haritada 8 cm olan uzaklık gerçekte kaç km'dir?   A) 16 km   B) 160 km   C) 1600 km   D) 8 km","Doğru cevap: A) 16 km. 8·200000 cm = 16 km."]},"10:mat2k2":{"a":"Sinüs ve Kosinüs Teoremleri, Üçgende Alan","o":["Sinüs teoremi: a / sin A = b / sin B = c / sin C = 2R","Kosinüs teoremi: a² = b² + c² − 2bc · cos A","Alan = (1/2) · b · c · sin A","İki kenar ve arasındaki açı → kosinüs teoremi · iki açı ve bir kenar → sinüs teoremi"],"t":["Kosinüs teoremi Pisagor bağıntısının genellemesidir: A = 90° iken cos A = 0 olduğundan a² = b² + c² olur. A geniş açıysa cos A negatif olur ve a² > b² + c² çıkar.","Sinüs teoremi, bir kenarın karşısındaki açının sinüsüyle orantılı olduğunu söyler; büyük açının karşısında büyük kenar bulunur."],"e":["Dik kenarları 5 ve 12 birim olan dik üçgenin hipotenüsü kaç birimdir?   A) 12   B) 17   C) 14   D) 13","Doğru cevap: D) 13. 5² + 12² = 169 → 13."]},"11:mat11g2":{"a":"Çokgenler: İçbükey–Dışbükey, Açılar ve Köşegenler","o":["Dışbükey çokgen: tüm iç açıları 180°'den küçüktür; herhangi iki iç noktayı birleştiren doğru parçası çokgenin içinde kalır. İçbükey çokgen: en az bir iç açısı 180°'den büyüktür.","n kenarlı çokgende iç açılar toplamı (n − 2) · 180°'dir. Dışbükey çokgenin dış açılar toplamı 360°'dir.","Düzgün çokgen: tüm kenarları ve tüm açıları eşittir. Bir iç açı = (n − 2) · 180° / n, bir dış açı = 360° / n.","Bir köşeden çizilebilen köşegen sayısı n − 3; bu köşegenler çokgeni n − 2 üçgene ayırır. Toplam köşegen sayısı n(n − 3) / 2.","Düzgün altıgen 6 eşkenar üçgene ayrılır: Alan = 6 · a²√3 / 4."],"t":["Çokgenlerin bağıntıları, çokgeni üçgenlere parçalayarak elde edilir. Bir köşeden tüm köşegenler çizildiğinde n − 2 üçgen oluşur; her üçgenin açıları toplamı 180° olduğundan iç açılar toplamı (n − 2) · 180°'dir.","Dış açılar: Dışbükey çokgende her köşedeki iç açı ile dış açı bütünlerdir. n köşenin toplamı n · 180°; iç açılar (n − 2) · 180° olduğundan dış açılar toplamı 2 · 180° = 360° çıkar. Bu, kenar sayısından bağımsızdır.","Düzgün çokgenin kenar sayısı bir dış açıdan kolayca bulunur: dış açı 40° ise n = 360 / 40 = 9 (düzgün dokuzgen).","İçbükey çokgende 180°'den büyük (yansıma) açı bulunur; bu yüzden dış açılar toplamı kuralı dışbükey çokgenler için ifade edilir."],"e":["İç açıları toplamı 1260° olan çokgenin kenar sayısını ve toplam köşegen sayısını bulunuz.","(n − 2) · 180 = 1260 → n − 2 = 7 → n = 9. Köşegen sayısı 9 · 6 / 2 = 27."],"h":"İç açılar toplamında n · 180° yazmak; doğrusu (n − 2) · 180°."},"11:mat11g1":{"a":"Dörtgenler ve Özel Dörtgenler","o":["Dörtgenin iç açıları toplamı 360°'dir (bir köşegen dörtgeni iki üçgene ayırır: 2 · 180°).","Paralelkenar: karşılıklı kenarlar paralel ve eşit; karşılıklı açılar eşit; ardışık açılar toplamı 180°; köşegenler birbirini ortalar. Alan = taban · yükseklik.","Dikdörtgen: tüm açıları 90° olan paralelkenar; köşegenleri eşittir. Eşkenar dörtgen: tüm kenarları eşit paralelkenar; köşegenleri dik kesişir ve açıortaydır. Alan = e · f / 2.","Kare: hem dikdörtgen hem eşkenar dörtgendir; köşegenleri eşit, dik ve birbirini ortalar.","Yamuk: en az bir çift karşılıklı kenarı paralel dörtgen. Alan = (a + c) · h / 2; orta taban = (a + c) / 2. İkizkenar yamukta taban açıları ve köşegenler eşittir."],"t":["Maarif programında dörtgenlerin özellikleri ezberlenmez; üçgenlerdeki açı, benzerlik ve alan bilgisiyle varsayım kurulur, genellenir ve ispatlanır. Örneğin paralelkenarda bir köşegen çizilince oluşan iki üçgen eştir (A.K.A.); buradan karşılıklı kenarların eşitliği çıkar.","Özel dörtgenler arasında hiyerarşi vardır: Her kare bir dikdörtgendir ve her kare bir eşkenar dörtgendir; her dikdörtgen ve her eşkenar dörtgen bir paralelkenardır. Tersi her zaman doğru değildir: her dikdörtgen kare değildir.","Köşegen özellikleri ayırt edicidir: köşegenleri birbirini ortalayan dörtgen paralelkenardır; ayrıca köşegenleri eşitse dikdörtgen, dikse eşkenar dörtgen, hem eşit hem dikse karedir.","Simetri: dikdörtgenin 2, eşkenar dörtgenin 2, karenin 4 simetri ekseni vardır; ikizkenar yamuğun ve deltoidin 1 simetri ekseni vardır; genel paralelkenarın simetri ekseni yoktur."],"e":["ABCD paralelkenarında m(Â) = 3x + 10° ve m(B̂) = 2x + 20° ise m(Â) kaç derecedir?","Ardışık açılar bütünlerdir: (3x + 10) + (2x + 20) = 180 → 5x = 150 → x = 30. m(Â) = 3 · 30 + 10 = 100°. Kontrol: m(B̂) = 80°, toplam 180° ✓"],"h":"Her paralelkenarın köşegenlerinin eşit olduğunu sanmak (bu yalnızca dikdörtgende geçerlidir)."},"7:m6k1":{"a":"Çember ve Dairenin Alanı","o":["Çemberin uzunluğu: Ç = 2πr (π ≈ 3,14 ya da 3)","Dairenin alanı: A = πr²","Daire dilimi alanı = πr² · (merkez açı / 360°)","Yay uzunluğu = 2πr · (merkez açı / 360°)","Çap = 2 × yarıçap"],"t":["Bir çemberin uzunluğunun çapına oranı her çemberde aynıdır ve π (pi) sayısı ile gösterilir; π ≈ 3,14'tür. Bu yüzden çemberin uzunluğu Ç = 2πr formülüyle bulunur.","Çemberin iç bölgesiyle birlikte oluşturduğu şekle daire denir. Daireyi çok sayıda dilime ayırıp yan yana dizdiğimizde yaklaşık bir dikdörtgen oluşur; kenarları πr ve r olduğundan dairenin alanı A = πr²'dir.","Köşesi çemberin merkezinde olan açıya merkez açı denir. Merkez açının daire içinde ayırdığı bölgeye daire dilimi denir. Daire diliminin alanı, dairenin alanının merkez açı/360° kadarıdır: 90°'lik dilim dairenin dörtte biridir.","Örnek: Yarıçapı 10 cm olan dairenin alanı π · 100 ≈ 314 cm²; 72°'lik dilimin alanı 314 · 72/360 = 62,8 cm²'dir."],"e":["Yarıçapı 2 cm olan dairede 90°'lik merkez açılı dilimin alanı kaç cm²'dir? (π = 3)   A) −2   B) 3   C) 12   D) 6","Doğru cevap: B) 3. 3 × 2² × 90/360 = 3"]},"8:mat7k2":{"a":"Koordinat Sistemi, Doğrusal İlişkiler ve Eğim","o":["Doğrusal denklem: y = mx + n → grafiği bir doğrudur.","Eğim (m) = dikey değişim / yatay değişim = (y₂ − y₁)/(x₂ − x₁)","Pozitif eğim: doğru sağa doğru yükselir · Negatif eğim: alçalır · Yatay doğru: eğim 0","x = 0 için y eksenini, y = 0 için x eksenini kestiği nokta bulunur."],"t":["Aralarında doğrusal ilişki olan iki değişkenin tablosu, denklemi ve grafiği vardır. Örneğin bir taksi açılış ücreti 30 TL ve km başına 20 TL ise ücret y = 20x + 30 denklemiyle gösterilir; grafiği bir doğrudur. Grafik çizmek için iki nokta yeterlidir.","Doğrunun dikliğine eğim denir. Doğru üzerindeki iki noktadan eğim, dikey uzaklığın yatay uzaklığa oranıdır. y = mx + n denkleminde x'in katsayısı m eğimi verir. y = 3 gibi doğrular x eksenine paralel (eğim 0), x = 2 gibi doğrular y eksenine paraleldir."],"e":["Bir taksinin açılış ücreti 20 TL, km başına ücreti 29 TL'dir. 13 km yol giden yolcu kaç TL öder?   A) 397   B) 637   C) 377   D) 289","Doğru cevap: A) 397. y = 29x + 20 → 397 TL"]},"8:mat11k1":{"a":"Prizmalar ve Silindir","o":["Dik prizma: tabanları eş ve paralel çokgen, yan yüzleri dikdörtgen.","Hacim = taban alanı × yükseklik","Silindir: taban alanı πr², yanal alan 2πr·h, hacim πr²h","Silindirin yüzey alanı = 2πr² + 2πrh"],"t":["Tabanları birbirine paralel ve eş çokgen, yan yüzleri dikdörtgen olan cisimlere dik prizma denir; tabanın biçimine göre adlandırılır (üçgen prizma, kare prizma...). Bütün prizmaların ve silindirin hacmi taban alanı ile yüksekliğin çarpımıdır.","Silindirin açınımı iki daire ve bir dikdörtgenden oluşur. Dikdörtgenin bir kenarı tabanın çevresi (2πr), diğer kenarı silindirin yüksekliğidir. Bu yüzden yanal alan 2πrh, toplam yüzey alanı 2πr² + 2πrh olur."],"e":["Yarıçapı 4 cm, yüksekliği 7 cm olan dik dairesel silindirin hacmi kaç cm³'tür? (π = 3)   A) 672   B) 168   C) 336   D) 84","Doğru cevap: C) 336. Hacim = π · r² · h = 3 · 16 · 7 = 336 cm³."]},"9:tar1k1":{"a":"Tarih Biliminin Yöntemi ve Kaynakları","o":["Tarih: geçmişteki insan topluluklarının faaliyetlerini yer ve zaman göstererek, sebep-sonuç ilişkisiyle, belgelere dayanarak inceler.","Birinci el kaynak: dönemin tanıklığı (kitabe, ferman, arşiv belgesi) · İkinci el: sonradan yazılmış eserler","Yöntem: kaynak tarama → tasnif → tahlil → tenkit → terkip","Yardımcı bilimler: arkeoloji, epigrafi (yazıt), nümizmatik (para), paleografya (eski yazı), kronoloji","Tarihte olgu (kanıtlanabilir) ile yorum (görüş) ayrılmalıdır."],"t":["Tarih bilimi, geçmişteki olayları yer ve zaman belirterek, belgelere dayanarak ve sebep-sonuç ilişkisi içinde inceler. Tarihçi deney yapamaz; bu yüzden kaynaklara dayanır. Olayın yaşandığı döneme ait belgeler birinci el kaynaktır ve daha güvenilirdir; bu kaynaklardan yararlanılarak sonradan yazılan eserler ikinci el kaynaktır.","Tarih araştırmasında kaynaklar bulunur (tarama), sınıflandırılır (tasnif), çözümlenir (tahlil), eleştirilir (tenkit) ve sonuçlar bir araya getirilerek yazılır (terkip). Tarihçinin tarafsız olması, olgu ile yorumu birbirinden ayırması gerekir."],"e":["Zamanı ölçen ve takvimleri inceleyen bilim dalı hangisidir?   A) Arkeoloji   B) Kartografya   C) Etnografya   D) Kronoloji","Doğru cevap: D) Kronoloji. Olayların tarihlerini belirler."]},"9:tar2k1":{"a":"İlk İnsanlar ve İlk Medeniyetler","o":["Tarih öncesi: Paleolitik (avcı-toplayıcı) → Neolitik (yerleşik hayat, tarım: Çatalhöyük, Göbeklitepe) → Maden Çağları","Yazının icadı (Sümerler, MÖ 3200) tarih çağlarını başlatır.","Mezopotamya: Sümer (çivi yazısı, ziggurat), Babil (Hammurabi Kanunları)","Mısır: hiyeroglif, piramitler, güneş takvimi · Anadolu: Hititler (Kadeş Antlaşması), Lidyalılar (para)","Fenikeliler: alfabe · Persler: Kral Yolu"],"t":["İnsanlık, yazının bulunmasından önceki dönemde taş ve maden kullanarak yaşamını sürdürdü. Neolitik dönemde tarımın başlamasıyla yerleşik hayata geçildi; Çatalhöyük ve Göbeklitepe bu döneme ait önemli merkezlerdir. Göbeklitepe, tapınma alanlarının yerleşik hayattan önce de var olabileceğini göstermiştir.","Sümerlerin yazıyı bulmasıyla tarih çağları başladı. Mezopotamya'da yazılı hukuk (Hammurabi Kanunları), Mısır'da güneş takvimi ve tıp, Anadolu'da Hititlerin bilinen ilk yazılı antlaşması (Kadeş) ve Lidyalıların parayı kullanması medeniyete önemli katkılardır."],"e":["Tarihteki bilinen ilk yazılı antlaşma hangisidir?   A) Mondros   B) Lozan   C) Westfalya   D) Kadeş Antlaşması","Doğru cevap: D) Kadeş Antlaşması. Hititler ile Mısır arasında imzalandı."]},"9:tar3k1":{"a":"İlk Türk Devletleri ve İslamiyet'in Doğuşu","o":["Asya Hun: Mete Han, onlu sistem · Göktürkler: Türk adını devlet adı olarak ilk kullanan, Orhun Yazıtları","Uygurlar: yerleşik hayat, matbaa, Maniheizm","Kut anlayışı: yönetme yetkisinin Gök Tanrı tarafından verildiği inancı · Kurultay","İslamiyet'in doğuşu (610), Hicret (622), Dört Halife, Emeviler, Abbasiler","Talas Savaşı (751): Türklerin İslamiyet'e geçişi hızlandı; kâğıt İslam dünyasına geçti."],"t":["İlk Türk devletlerinde hükümdar yönetme yetkisini (kut) Gök Tanrı'dan aldığına inanırdı; devlet işleri kurultayda görüşülürdü. Asya Hun Devleti'nde Mete Han ordu düzenini onlu sisteme göre kurdu. Göktürkler 'Türk' adını devlet adı olarak kullanan ilk devlettir ve Orhun Yazıtları Türk tarihinin ilk yazılı belgelerindendir.","İslamiyet 610'da Mekke'de doğdu; 622'de Hicret ile Medine'de İslam devleti kuruldu. Talas Savaşı'nda Abbasilerin Çinlilere karşı Türklerle birlikte savaşması Türklerin İslamiyet'e geçişini hızlandırdı; Karahanlılar İslamiyet'i resmî din olarak kabul eden ilk Türk devletidir."],"e":["\"Türk\" adının ilk kez resmî devlet adı olarak kullanıldığı devlet hangisidir?   A) Hunlar   B) Uygurlar   C) Göktürkler   D) Hazarlar","Doğru cevap: C) Göktürkler. I. Göktürk Devleti 552'de kuruldu."]},"10:tar1k1":{"a":"Büyük Selçuklu Devleti ve Malazgirt","o":["1040 Dandanakan Savaşı: Selçuklular Gaznelileri yendi, Büyük Selçuklu Devleti kuruldu","Tuğrul Bey: 1055'te Bağdat'a girerek Abbasi halifesini Büveyhoğullarından kurtardı","1071 Malazgirt Zaferi (Sultan Alparslan – Romen Diyojen): Anadolu'nun kapıları Türklere açıldı","Melikşah döneminde devlet en geniş sınırlarına ulaştı; Nizamülmülk ve Nizamiye medreseleri","Yıkılış: taht kavgaları, Haçlı Seferleri öncesi bölünmeler, Katvan (1141) yenilgisi, 1157 Sencer'in ölümü"],"t":["Malazgirt Zaferi'nden sonra Türkmen boyları kitleler hâlinde Anadolu'ya yerleşti ve Anadolu'da ilk Türk beylikleri (Danişmentliler, Saltuklular, Mengücekliler, Artuklular) kuruldu. Bu nedenle Malazgirt, Anadolu'nun Türk yurdu olma sürecinin başlangıcı kabul edilir.","Nizamülmülk'ün kurduğu Nizamiye medreseleri, devlete yetişmiş memur ve âlim kazandıran düzenli eğitim kurumlarıydı. Selçuklularda ikta sistemi hem ordu beslemeyi hem de toprağın işlenmesini sağladı."],"e":["Tuğrul Bey'in Bağdat'a girmesinin önemi nedir?   A) Haçlıları durdurması   B) İstanbul'u alması   C) Bizans'ı yenmesi   D) Abbasi halifesini Büveyhoğulları baskısından kurtarması","Doğru cevap: D) Abbasi halifesini Büveyhoğulları baskısından kurtarması. Selçuklular İslam dünyasının koruyucusu oldu."]},"10:tar1k2":{"a":"Türkiye Selçuklu Devleti ve Anadolu'nun Türkleşmesi","o":["Kuruluş: 1075, Kutalmışoğlu Süleyman Şah; ilk başkent İznik, sonra Konya","1176 Miryokefalon: Bizans'ın Türkleri Anadolu'dan atma umudu sona erdi","Ticaret: kervansaraylar, Antalya-Sinop-Sudak limanları, devlet güvenceli ticaret sigortası","1243 Kösedağ Savaşı: Moğollara yenilgi, Anadolu Moğol (İlhanlı) etkisine girdi; II. Beylikler Dönemi","Kültür: Mevlana, Yunus Emre, Hacı Bektaş-ı Veli; Ahilik teşkilatı (Ahi Evran)"],"t":["Türkiye Selçukluları kervansaraylar inşa ederek ve kaybı devletçe karşılanan bir sigorta sistemi uygulayarak Anadolu'yu uluslararası ticaretin kavşağı yaptı. Bu ticaret şehirlerin gelişmesini ve Türk nüfusunun yerleşik hayata geçmesini hızlandırdı.","Ahilik, esnaf ve sanatkârları dayanışma, dürüstlük ve meslek ahlakı çevresinde örgütleyen bir teşkilattı; kaliteyi denetler, usta-çırak ilişkisiyle meslek eğitimini sağlardı."],"e":["Kösedağ Savaşı kime karşı yapıldı?   A) Memlükler   B) Bizans   C) Haçlılar   D) Moğollar","Doğru cevap: D) Moğollar. 1243'te Selçuklular yenildi."]},"10:tar2k1":{"a":"Osmanlı Beyliğinin Kuruluşu ve Yükselişi","o":["Kuruluş: Söğüt ve çevresi, Osman Bey; Bizans sınırında uç beyliği","1302 Koyunhisar (Bafeus): Bizans'a karşı ilk önemli zafer","Orhan Bey: Bursa'nın alınması (1326), ilk düzenli ordu (yaya-müsellem), Rumeli'ye geçiş (Çimpe 1353)","I. Murat: Edirne, Sırpsındığı (1364), I. Kosova (1389), Kapıkulu ocakları ve pençik sistemi","Yıldırım Bayezid: Niğbolu (1396), Ankara Savaşı (1402) yenilgisi → Fetret Devri; Çelebi Mehmet birliği yeniden sağladı"],"t":["Osmanlıların hızla büyümesinin nedenleri arasında Bizans sınırında bulunmaları, gaza ve cihat anlayışı, fethedilen yerlerde adil yönetim (istimalet politikası) ve Balkanlardaki siyasi dağınıklık sayılır.","Ankara Savaşı'nda Timur'a yenilen Yıldırım Bayezid esir düştü; şehzadeler arasındaki taht kavgası 11 yıl süren Fetret Devri'ni başlattı. Çelebi Mehmet devleti yeniden birleştirdi."],"e":["Fetret Devri'ne son veren padişah kimdir?   A) Yıldırım Bayezid   B) II. Murat   C) Fatih   D) Çelebi Mehmet","Doğru cevap: D) Çelebi Mehmet. Osmanlı birliğini yeniden sağladı."]},"10:tar2k2":{"a":"İstanbul'un Fethi (1453)","o":["II. Mehmet (Fatih) 1453'te İstanbul'u fethetti; Bizans İmparatorluğu sona erdi","Hazırlıklar: Rumeli Hisarı, büyük toplar (Macar Urban), donanma, gemilerin karadan Haliç'e indirilmesi","Sonuçlar: Osmanlı imparatorluk hâline geldi, İstanbul başkent oldu, Karadeniz ticareti Osmanlıya geçti","Bazı tarihçilere göre Orta Çağ'ın sonu, Yeni Çağ'ın başlangıcı kabul edilir","Fatih, Ortodoks Patrikliğine dokunmayarak hoşgörü politikası izledi"],"t":["İstanbul'un fethinde top teknolojisinin kullanılması, kalın surların aşılabildiğini gösterdi ve Avrupa'da feodal beylerin şatolara dayanan gücünü sarstı.","Fethin ardından İstanbul'un nüfusu çeşitli bölgelerden getirilen halkla artırıldı; şehir bir bilim, kültür ve ticaret merkezi hâline getirildi."],"e":["Fetihten sonra Osmanlı'nın başkenti neresi oldu?   A) Edirne   B) Ankara   C) İstanbul   D) Bursa","Doğru cevap: C) İstanbul. 1453'ten 1922'ye kadar başkentti."]},"11:tar3k1":{"a":"Avrupa Devletleri ve Osmanlı Diplomasisi (Şark Meselesi)","o":["Şark Meselesi: Avrupa devletlerinin Osmanlı topraklarını paylaşma politikası","Denge politikası: Avrupa devletlerinin rekabetinden yararlanma","Mısır Sorunu: Kavalalı Mehmet Ali Paşa isyanı, Hünkâr İskelesi (1833)","Kırım Savaşı ve Paris Antlaşması (1856): Osmanlı Avrupa devleti sayıldı.","93 Harbi ve Berlin Antlaşması (1878): Balkanlarda büyük kayıplar"],"t":["XIX. yüzyılda Avrupalı devletler Osmanlı topraklarını paylaşma hesapları yaptı; bu soruna Şark Meselesi denir. Osmanlı Devleti varlığını korumak için Avrupa devletleri arasındaki rekabetten yararlanan bir denge politikası izledi.","Mısır Valisi Mehmet Ali Paşa'nın isyanında Rusya'dan yardım alınması (Hünkâr İskelesi) Avrupa'yı rahatsız etti. Kırım Savaşı'nda İngiltere ve Fransa'nın desteğiyle Rusya'ya karşı savaşıldı; Paris Antlaşması ile Osmanlı toprak bütünlüğü Avrupa'nın güvencesine alındı. 93 Harbi'nden sonra Berlin Antlaşması ile Balkanlarda büyük topraklar kaybedildi."],"e":["Osmanlı'yı \"Hasta Adam\" olarak niteleyen devlet hangisidir?   A) İngiltere   B) Fransa   C) Almanya   D) Rusya","Doğru cevap: D) Rusya. Çar I. Nikola bu ifadeyi kullandı."]},"12:ink1k1":{"a":"Trablusgarp, Balkan Savaşları ve I. Dünya Savaşı","o":["Trablusgarp Savaşı (1911-1912): İtalya'ya karşı; Uşi Antlaşması ile Trablusgarp ve Bingazi kaybedildi, Mustafa Kemal Tobruk ve Derne'de görev yaptı","Balkan Savaşları (1912-1913): Rumeli'nin büyük kısmı kaybedildi; Edirne geri alındı","I. Dünya Savaşı (1914-1918): İtilaf ve İttifak blokları; Osmanlı İttifak Bloku'nda","Cepheler: Çanakkale (Mustafa Kemal'in ün kazandığı zafer), Kafkas, Kanal, Irak, Suriye-Filistin","Mondros Ateşkes Antlaşması (30 Ekim 1918): 7. madde ile İtilaf devletlerine işgal yolu açıldı"],"t":["Çanakkale Zaferi, İtilaf devletlerinin Boğazları geçip İstanbul'u alma ve Rusya'ya yardım ulaştırma planını engelledi; savaşın uzamasına, Rusya'da Bolşevik İhtilali'ne zemin hazırlanmasına ve Mustafa Kemal'in bir lider olarak tanınmasına yol açtı.","Mondros Ateşkes Antlaşması'nın 7. maddesi ('İtilaf devletleri güvenliklerini tehdit eden bir durum olursa herhangi bir stratejik noktayı işgal edebilecek') Anadolu'nun işgaline hukuki kılıf oluşturdu."],"e":["Osmanlı Devleti'nin I. Dünya Savaşı'na girmesinde etkili olan gelişme hangisidir?","Almanya'dan alınan Goeben ve Breslau gemilerinin (Yavuz ve Midilli) Karadeniz'de Rus limanlarını bombalaması Osmanlı'yı fiilen savaşa soktu (1914). Arka planda kaybedilen toprakları geri alma ve yalnızlıktan kurtulma isteği vardı."],"h":"Balkan Savaşları ile I. Dünya Savaşı'nın sırasını karıştırmak: Trablusgarp (1911) → Balkan (1912-13) → I. Dünya Savaşı (1914-18)."},"12:ink2k1":{"a":"Hazırlık Dönemi ve Kongreler","o":["19 Mayıs 1919: Mustafa Kemal Samsun'a çıktı","Amasya Genelgesi (22 Haziran 1919): 'Milletin istiklalini yine milletin azim ve kararı kurtaracaktır' — millî egemenlik","Erzurum Kongresi (23 Temmuz – 7 Ağustos 1919): bölgesel toplandı, millî kararlar aldı; manda ve himaye reddedildi","Sivas Kongresi (4-11 Eylül 1919): ulusal; cemiyetler Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adıyla birleşti","Misak-ı Millî (28 Ocak 1920): son Osmanlı Mebusan Meclisi; millî sınırlar ve tam bağımsızlık"],"t":["Amasya Genelgesi, Millî Mücadele'nin amacını, gerekçesini ve yöntemini ilk kez açıkça ortaya koyan belgedir; milletin kaderini kendisinin belirleyeceğini ilan ederek millî egemenliği öne çıkarır.","Misak-ı Millî, Türk milletinin bağımsızlık ve sınır konusundaki kesin kararlarını içerir; kapitülasyonları reddeder ve Lozan'a kadar Türk dış politikasının temel belgesi olur."],"e":["Amasya Genelgesi'nde yer alan 'Milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır.' maddesi neyi ifade eder?","Millî egemenlik ve tam bağımsızlık ilkesini, yani kurtuluşun İstanbul hükûmetinden ya da yabancı devletlerden değil, milletin kendi iradesinden geleceğini ifade eder. Kurtuluş Savaşı'nın gerekçesi, amacı ve yöntemi ilk kez bu genelgede belirtilmiştir."],"h":"Manda ve himayenin ilk kez Sivas'ta reddedildiğini sanmak: ilk kez Erzurum Kongresi'nde reddedilmiş, Sivas'ta kesinleşmiştir."},"12:ink3k1":{"a":"İnkılaplar ve Atatürk İlkeleri","o":["Siyasi: saltanatın kaldırılması (1 Kasım 1922), Cumhuriyet'in ilanı (29 Ekim 1923), halifeliğin kaldırılması (3 Mart 1924)","Hukuk: Türk Medeni Kanunu (1926) — kadın-erkek eşitliği, tek eşlilik","Eğitim-kültür: Tevhid-i Tedrisat (1924), Harf İnkılabı (1928), Türk Tarih (1931) ve Türk Dil (1932) Kurumu","Toplumsal: Şapka Kanunu (1925), tekke-zaviyelerin kapatılması, Soyadı Kanunu (1934), kadınlara seçme-seçilme hakkı (1930 belediye, 1934 milletvekili)","İlkeler: Cumhuriyetçilik, Milliyetçilik, Halkçılık, Devletçilik, Laiklik, İnkılapçılık"],"t":["Atatürk ilkeleri birbirini tamamlar: Cumhuriyetçilik millî egemenliği, Halkçılık eşitliği, Laiklik din ve devlet işlerinin ayrılmasını, İnkılapçılık yapılan yeniliklerin korunmasını ve çağın gereklerine göre yeni yeniliklerin yapılmasını esas alır.","Tevhid-i Tedrisat Kanunu ile bütün eğitim kurumları Millî Eğitim Bakanlığına bağlanarak eğitimde birlik sağlandı; bu, laik ve millî eğitimin temelini oluşturdu."],"e":["Saltanatın kaldırılması (1922) ve Cumhuriyetin ilanı (1923) hangi Atatürk ilkesiyle doğrudan ilgilidir?","Cumhuriyetçilik ilkesiyle ilgilidir: egemenlik kayıtsız şartsız millete verilmiş, devlet başkanının seçimle belirlendiği yönetim kurulmuştur. Saltanatın kaldırılması aynı zamanda millî egemenliğin önündeki engeli ortadan kaldırmıştır."],"h":"Kadınlara seçme-seçilme hakkının Medeni Kanunla verildiğini sanmak: belediye seçimlerinde 1930, milletvekili seçimlerinde 1934'te verilmiştir."},"9:cog1k1":{"a":"Doğa-İnsan Etkileşimi ve Haritalar","o":["Coğrafya: doğal ortam ile insan arasındaki karşılıklı etkileşimi inceler.","Doğal sistemler: atmosfer, hidrosfer, litosfer, biyosfer","Ölçek = harita uzunluğu / gerçek uzunluk · Büyük ölçek → ayrıntı fazla, alan küçük","Kesir ölçek 1/100.000 → haritada 1 cm = gerçekte 1 km","İzohips: eş yükselti eğrisi; sık ise eğim fazla"],"t":["Coğrafya, insanın doğal ortamı nasıl etkilediğini ve doğal ortamdan nasıl etkilendiğini inceler. Barajlar, terasla tarım ya da kentleşme insanın doğaya etkisine; yerleşmelerin akarsu kenarlarında kurulması ise doğanın insana etkisine örnektir.","Haritalar dünyanın tamamının ya da bir bölümünün belli bir ölçekle küçültülmüş çizimleridir. Ölçeğin paydası küçüldükçe ölçek büyür ve harita daha ayrıntılı olur. Yer şekilleri izohips (eş yükselti) eğrileriyle gösterilir; eğrilerin sıklaştığı yerlerde eğim fazladır."],"e":["Haritada kullanılan işaretlerin anlamlarını gösteren bölüme ne denir?   A) Pusula   B) Başlık   C) Lejant (açıklama)   D) Ölçek","Doğru cevap: C) Lejant (açıklama). Lejant sembolleri açıklar."]},"9:cog2k1":{"a":"Enlem, Boylam, Dünya'nın Hareketleri ve İklim Elemanları","o":["Enlem: Ekvator'a uzaklık → sıcaklık, gün süresi, iklim kuşakları","Boylam: başlangıç meridyenine uzaklık → yerel saat (1° = 4 dakika)","Günlük hareket: gece-gündüz · Yıllık hareket: mevsimler","İklim elemanları: sıcaklık, basınç, rüzgâr, nem, yağış","Sıcaklığı etkileyenler: enlem, yükselti, karasallık, bakı, okyanus akıntıları"],"t":["Enlem bir yerin Ekvator'a olan açısal uzaklığıdır; Ekvator'dan kutuplara gidildikçe Güneş ışınlarının geliş açısı küçülür ve sıcaklık azalır. Boylam ise başlangıç meridyenine olan açısal uzaklıktır; iki meridyen arasında 4 dakikalık zaman farkı vardır ve doğudaki yerlerde yerel saat ileridir.","İklim, bir yerde uzun yıllar boyunca görülen hava olaylarının ortalamasıdır. Sıcaklık; enlem, yükselti (her 100 m'de yaklaşık 0,5 °C düşer), denize uzaklık ve bakı gibi etkenlere göre değişir."],"e":["Ekvator'a paralel olarak çizildiği varsayılan hayali çemberlere ne denir?   A) Boylam   B) Paralel (enlem çemberi)   C) Meridyen   D) Ekliptik","Doğru cevap: B) Paralel (enlem çemberi). Toplam 180 paralel vardır."]},"10:cog1k1":{"a":"Harita Bilgisi ve Mekânsal Bilgi Teknolojileri","o":["Ölçek = haritadaki uzunluk / gerçek uzunluk · 1/100 000'de 1 cm = 1 km","Küçük ölçek (paydası büyük) → geniş alan, az ayrıntı · Büyük ölçek → dar alan, çok ayrıntı","İzohips (eş yükselti eğrisi): sık → eğim fazla, seyrek → eğim az","Coğrafi Bilgi Sistemleri (CBS): mekânsal verileri toplama, depolama, analiz ve gösterme","Uzaktan algılama (uydu görüntüleri) ve GNSS/GPS konum belirleme"],"t":["Ölçek, haritadaki uzaklıkların gerçekte ne kadara karşılık geldiğini gösterir. 1/500 000 ölçekli haritada 4 cm, gerçekte 4 · 5 km = 20 km'dir.","CBS katman mantığıyla çalışır: yollar, akarsular, nüfus, yükselti gibi veriler üst üste konularak afet risk haritaları, ulaşım planlaması ya da yatırım yeri seçimi gibi analizler yapılır."],"e":["Uzaktan algılama yöntemlerine örnek hangisidir?   A) Arazi gözlemi   B) Anket   C) Nüfus sayımı   D) Uydu görüntüleri","Doğru cevap: D) Uydu görüntüleri. Yeryüzü uzaktan incelenir."]},"12:cog1k1":{"a":"Ekstrem Doğa Olayları ve Küresel İklim Değişikliği","o":["Ekstrem doğa olayları: kasırga (tropikal siklon), hortum, aşırı sıcak dalgaları, kuraklık, sel, aşırı yağış","Tropikal siklonlar sıcak okyanus sularında (26 °C üzeri) oluşur; ekvatorda oluşmaz (Coriolis etkisi yetersiz)","Küresel iklim değişikliği: sera gazlarının artışıyla ortalama sıcaklığın yükselmesi","Sonuçlar: buzulların erimesi, deniz seviyesinin yükselmesi, kuraklık, tür kayıpları, iklim göçleri","Uluslararası çabalar: Kyoto Protokolü, Paris İklim Anlaşması"],"t":["İklim değişikliği tüm dünyayı etkilese de etkileri bölgeden bölgeye farklıdır: alçak kıyı ve ada ülkeleri deniz seviyesinin yükselmesinden, kurak bölgeler su sıkıntısından, kutup bölgeleri buzul erimesinden en çok etkilenir.","Akdeniz havzası, iklim modellerine göre sıcaklık artışı ve yağış azalmasından en çok etkilenecek bölgeler arasındadır; Türkiye'de kuraklık ve orman yangını riskinin artması beklenir."],"e":["Küresel iklim değişikliğinin Türkiye üzerindeki olası etkilerinden ikisini yazınız.","Kuraklık ve su kaynaklarının azalması (tarımsal verim düşer), ani sel ve aşırı yağış olaylarının artması, orman yangınlarının sıklaşması, kıyı alanlarında deniz seviyesinin yükselmesiyle oluşan riskler."],"h":"Hava durumu ile iklimi karıştırmak: hava durumu kısa süreli, iklim uzun yıllar ortalamasıdır."},"10:cog2k1":{"a":"Yer'in Yapısı, İç ve Dış Kuvvetler","o":["Yer'in katmanları: yer kabuğu (litosfer), manto, çekirdek","İç kuvvetler: levha hareketleri, orojenez (dağ oluşumu), epirojenez, deprem, volkanizma","Dış kuvvetler: akarsu, rüzgâr, buzul, dalga, karstik aşınma (çözünme)","Akarsu yer şekilleri: V vadi, menderes, delta, birikinti konisi, kanyon","Türkiye Alp-Himalaya kuşağındadır; KAF ve DAF önemli fay hatlarıdır"],"t":["İç kuvvetler yer şekillerini oluşturur ve yükseltir, dış kuvvetler aşındırıp taşıyarak alçaltır ve düzleştirir. Bugünkü yer şekilleri bu iki kuvvetin uzun süreli etkileşiminin sonucudur.","Karstik şekiller kalker, jips gibi kolay çözünen kayaçların suyla çözünmesiyle oluşur: lapya, dolin, polye, mağara, sarkıt-dikit ve traverten (Pamukkale) örnek verilebilir."],"e":["Yer'in en dış katmanına ne denir?   A) Dış çekirdek   B) Manto   C) Yer kabuğu (litosfer)   D) İç çekirdek","Doğru cevap: C) Yer kabuğu (litosfer). Kıtasal ve okyanusal kabuk olmak üzere ikiye ayrılır."]},"9:cog3k1":{"a":"İç ve Dış Kuvvetler","o":["İç kuvvetler: orojenez (dağ oluşumu), epirojenez, deprem, volkanizma","Dış kuvvetler: akarsu, rüzgâr, buzul, dalga, karstik aşınma","Akarsu: vadi, menderes, delta · Rüzgâr: mantarkaya, kumul · Buzul: sirk, moren","Türkiye deprem kuşağındadır (Alp-Himalaya)."],"t":["Yer şekillerini iç ve dış kuvvetler oluşturur. İç kuvvetler enerjisini yerin derinliklerindeki magmadan alır; dağ oluşumu, depremler ve volkanizma yer kabuğunda yükseltiler oluşturur. Dış kuvvetler ise Güneş enerjisi ve yer çekimi etkisiyle bu yükseltileri aşındırır ve çukur alanlara biriktirir.","Akarsular vadiler açar, ağız kısımlarında delta oluşturur; rüzgâr kurak bölgelerde mantarkaya ve kumullar; buzullar ise sirk gölleri ve morenler oluşturur. Türkiye Alp-Himalaya deprem kuşağında yer aldığından depreme hazırlık hayati önemdedir."],"e":["Peri bacaları hangi bölgemizdedir?   A) Marmara   B) İç Anadolu (Kapadokya)   C) Ege   D) Karadeniz","Doğru cevap: B) İç Anadolu (Kapadokya). Volkanik tüflerin aşınmasıyla oluşmuştur."]},"10:cog3k1":{"a":"Nüfus, Yerleşme ve Göç","o":["Nüfus dağılışını etkileyenler: iklim, yer şekilleri, su kaynakları, ekonomik faaliyetler, ulaşım","Aritmetik nüfus yoğunluğu = nüfus / alan (km²)","Nüfus piramidi: geniş taban → genç nüfus, dar taban → yaşlanan nüfus","Göç nedenleri: itici (işsizlik, afet) ve çekici (iş, eğitim, sağlık) faktörler","Türkiye'de nüfus en çok Marmara'da, en seyrek Doğu Anadolu'nun yüksek kesimlerinde"],"t":["Kırsaldan kente göç, Türkiye'de özellikle 1950'lerden sonra sanayileşme ve tarımda makineleşmeyle hızlandı. Bu süreç şehirlerde hızlı büyüme, çarpık kentleşme ve altyapı sorunları; kırsalda ise yaşlanan nüfus doğurdu.","Nüfus piramitleri bir ülkenin doğum oranı, ortalama ömür ve bağımlı nüfus gibi özelliklerini gösterir; eğitim, sağlık ve emeklilik planlamasında kullanılır."],"e":["Toplu yerleşmelerin görüldüğü bölgemiz hangisidir?   A) Sarp kıyılar   B) Doğu Karadeniz   C) Yüksek dağlar   D) İç Anadolu","Doğru cevap: D) İç Anadolu. Su kaynaklarının az olması toplu yerleşmeye yol açar."]},"10:cog4k1":{"a":"Ekonomik Faaliyetler ve Doğal Afetler","o":["Birincil (tarım, hayvancılık, madencilik, ormancılık), ikincil (sanayi), üçüncül (hizmet: ticaret, turizm, ulaşım) faaliyetler","Gelişmiş ülkelerde hizmet sektöründe çalışanların oranı yüksektir","Afet: olağanüstü doğa olayının can ve mal kaybına yol açması (deprem, sel, heyelan, çığ, orman yangını)","Afet yönetimi: zarar azaltma → hazırlık → müdahale → iyileştirme","Sürdürülebilirlik: kaynakların gelecek kuşakların ihtiyaçlarını tehlikeye atmadan kullanılması"],"t":["Bir doğa olayının afete dönüşüp dönüşmemesi, insanların o olaya ne kadar hazırlıklı olduğuna bağlıdır. Depreme dayanıklı yapılaşma, fay hattı ve dere yataklarından uzak yerleşme, afet eğitimi kayıpları büyük ölçüde azaltır.","Türkiye'de heyelan en çok Karadeniz'de (eğimli ve yağışlı arazi), çığ Doğu Anadolu ve Doğu Karadeniz'in yüksek kesimlerinde, orman yangınları yazın sıcak ve kurak geçen Akdeniz ve Ege kıyılarında görülür."],"e":["Doğrudan doğadan yararlanılan ekonomik faaliyetlere ne denir?   A) İkincil   B) Üçüncül   C) Dördüncül   D) Birincil ekonomik faaliyetler","Doğru cevap: D) Birincil ekonomik faaliyetler. Tarım, hayvancılık, madencilik, ormancılık."]},"10:fel1k1":{"a":"Felsefenin Anlamı, Özellikleri ve Felsefi Düşünme","o":["Felsefe (philosophia): bilgelik sevgisi; varlık, bilgi ve değerler üzerine sistemli, eleştirel düşünme","Özellikleri: eleştirel, sorgulayıcı, refleksif (düşünce üzerine düşünme), tutarlı, sistemli, evrensel","Felsefi sorular kesin ve tek bir cevaba bağlanamaz; her cevap yeni sorular doğurur","Felsefenin alanları: bilgi (epistemoloji), varlık (ontoloji), ahlak (etik), sanat (estetik), siyaset, din, bilim felsefesi","Felsefede argüman: öncüller ve sonuçtan oluşan, gerekçeye dayalı akıl yürütme"],"t":["Felsefe, gündelik hayatta sorgusuzca kabul ettiğimiz kavramları ('Doğru nedir?', 'Adalet nedir?') akıl yoluyla sorgular. Bilimden farkı, deney yerine akıl yürütmeye dayanması ve olgulardan çok kavramların anlamını, temellerini araştırmasıdır.","Felsefi tutum, kesin yargılardan önce şüphe etmeyi, gerekçe istemeyi ve karşıt görüşleri adil biçimde değerlendirmeyi gerektirir. Sokrates'in 'Bildiğim tek şey hiçbir şey bilmediğimdir' sözü bu tutumu yansıtır."],"e":["İlk filozof kabul edilen düşünür kimdir?   A) Aristoteles   B) Platon   C) Sokrates   D) Thales","Doğru cevap: D) Thales. \"Her şeyin ana maddesi sudur.\" demiştir."]},"10:fel2k1":{"a":"Bilginin Kaynağı ve Doğru Bilginin İmkânı","o":["Bilgi: süje (bilen) ile obje (bilinen) arasındaki ilişkinin ürünü","Doğru bilgi mümkün mü? Septisizm (şüphecilik: hayır), dogmatizm (evet, sorgusuz)","Rasyonalizm (Descartes): bilginin kaynağı akıldır · Empirizm (Locke): deney ve duyulardır","Kritisizm (Kant): bilgi akıl ve deneyin birlikteliğiyle oluşur","Sezgicilik (Bergson): gerçek bilgiye sezgiyle ulaşılır"],"t":["Descartes her şeyden şüphe ederek şüphe edemeyeceği tek bir şeye ulaştı: şüphe eden, yani düşünen bir 'ben' vardır ('Düşünüyorum, öyleyse varım'). Bu, aklı bilginin temeli yapan rasyonalizmin simgesidir.","Locke'a göre zihin doğuşta boş bir levhadır (tabula rasa); bütün bilgiler deneyimle yazılır. Kant ise 'Kavramsız algılar kör, algısız kavramlar boştur' diyerek akıl ve deneyi birleştirdi."],"e":["Bilginin kaynağını akıl olarak gören görüş hangisidir?   A) Empirizm   B) Pragmatizm   C) Rasyonalizm (akılcılık)   D) Septisizm","Doğru cevap: C) Rasyonalizm (akılcılık). Descartes ve Leibniz temsilcilerdir."]},"10:fel3k1":{"a":"Varlığın Var Olup Olmadığı ve Varlığın Mahiyeti","o":["Nihilizm (Gorgias): hiçbir şey yoktur, olsa bile bilinemez, bilinse bile aktarılamaz","İdealizm (Platon): asıl varlık idealar dünyasıdır; duyular dünyası onun gölgesidir","Materyalizm (Demokritos): varlığın özü maddedir (atom)","Düalizm (Descartes): varlık hem madde hem ruh (düşünce) olmak üzere iki tözden oluşur","İlk filozoflar arkhe'yi (ana madde) aradı: Thales su, Anaksimenes hava, Herakleitos ateş (değişim)"],"t":["Platon mağara alegorisinde, duvardaki gölgeleri gerçek sanan mahkûmlarla duyular dünyasına bağlı insanları anlatır; gerçek bilgi, aklın idealar dünyasına yönelmesiyle elde edilir.","Herakleitos'a göre her şey sürekli değişir ('Aynı ırmakta iki kez yıkanılmaz'); Parmenides ise değişimin bir yanılsama, varlığın tek ve değişmez olduğunu savundu."],"e":["Varlığın özünü düşünce ya da idea olarak gören görüş hangisidir?   A) Pozitivizm   B) Materyalizm   C) İdealizm   D) Nihilizm","Doğru cevap: C) İdealizm. Platon idealizmin temsilcisidir."]},"10:fel4k1":{"a":"Ahlak Felsefesi ve Siyaset Felsefesi","o":["Ahlak felsefesi (etik): iyi-kötü, özgürlük, sorumluluk, erdem kavramlarını sorgular","Ödev etiği (Kant): eylemin değeri sonucunda değil, iyi niyet ve ödevden yapılmasında","Faydacılık (Bentham, Mill): en çok sayıda insana en çok mutluluğu sağlayan eylem iyidir","Hazcılık (Epikuros): iyi olan hazdır; ama ölçülü ve kalıcı hazlar","Siyaset felsefesi: devlet, iktidar, meşruiyet, özgürlük, adalet; ideal düzen arayışı (Platon, Farabi, Hobbes, Locke)"],"t":["Kant'a göre bir eylem, herkes için yasa olabilecek bir ilkeye göre yapılmışsa ahlakidir (kategorik buyruk). Yalan söylemek, herkes yalan söylediğinde güven ortadan kalkacağı için evrenselleştirilemez.","Hobbes doğa durumunu 'herkesin herkese karşı savaşı' olarak görür ve güçlü bir devleti zorunlu sayar; Locke ise devletin görevini yaşam, özgürlük ve mülkiyet haklarını korumak olarak tanımlar."],"e":["\"İnsan insanın kurdudur.\" görüşüyle güçlü devleti savunan filozof kimdir?   A) Montesquieu   B) John Locke   C) Rousseau   D) Thomas Hobbes","Doğru cevap: D) Thomas Hobbes. Leviathan eserinde anlatır."]},"9:din1k1":{"a":"İslam'da Bilgi Kaynakları ve İman","o":["Bilgi kaynakları: duyular, akıl, vahiy","İman: kalp ile tasdik; amentü esasları (Allah, melekler, kitaplar, peygamberler, ahiret, kader)","Tevhid: Allah'ın birliği; İhlas suresi","Akıl ve vahiy birbirini tamamlar; İslam düşünmeyi ve araştırmayı teşvik eder."],"t":["İslam düşüncesinde bilgiye duyular, akıl ve vahiy yoluyla ulaşılır. Duyular fiziksel dünyayı tanımamızı, akıl yorum yapmamızı sağlar; akıl ve duyuların ulaşamadığı alanlarda ise vahiy yol göstericidir. Kur'an pek çok ayette insanı düşünmeye ve evreni incelemeye çağırır.","İman, Allah'ın Hz. Muhammed aracılığıyla bildirdiği esaslara kalp ile inanmak ve bunu dil ile ikrar etmektir. İslam inancının temeli tevhiddir: Allah birdir, eşi ve benzeri yoktur. İhlas suresi tevhidi özlü biçimde anlatır."],"e":["Taklidî iman ne demektir?   A) İnancı terk etmek   B) Araştırmadan başkalarını taklit ederek inanmak   C) Bilerek inanmak   D) Hiç inanmamak","Doğru cevap: B) Araştırmadan başkalarını taklit ederek inanmak. Tahkikî iman ise araştırarak inanmaktır."]},"9:din2k1":{"a":"İbadetin Anlamı ve Ahlaki Değerler","o":["İbadet: Allah'a saygı ve bağlılığın davranışlarla gösterilmesi (namaz, oruç, zekât, hac)","İbadetler bireyi disipline eder, toplumsal dayanışmayı güçlendirir.","Ahlaki değerler: doğruluk, adalet, merhamet, sabır, emanete riayet","Kul hakkı: başkasının hakkını yememek"],"t":["İbadet, kulun Allah'a olan bağlılığını, sevgisini ve saygısını göstermesidir. Namaz Allah'ı anmayı ve düzenli olmayı, oruç sabrı ve yoksulun hâlini anlamayı, zekât paylaşmayı öğretir. İbadetler kişinin ahlakını güzelleştirmeyi amaçlar.","İslam ahlakının temelinde doğruluk, adalet, merhamet ve kul hakkına saygı vardır. Peygamberimiz 'Ben güzel ahlakı tamamlamak için gönderildim.' buyurmuştur."],"e":["Riya ne demektir?   A) İbadeti terk   B) Gösteriş için ibadet etmek   C) Samimi ibadet   D) Yardımlaşma","Doğru cevap: B) Gösteriş için ibadet etmek. Riya ibadetin değerini düşürür."]},"9:din3k1":{"a":"Peygamberimizin Gençlere Yaklaşımı","o":["Hz. Muhammed gençlere sorumluluk verdi: Üsame b. Zeyd ordu komutanı oldu.","Mus'ab b. Umeyr Medine'ye öğretmen olarak gönderildi.","Gençlik: enerji, idealizm, sorumluluk dönemi","Hilfu'l-Fudul: haksızlığa uğrayanları koruma birliği (genç yaşta katıldı)"],"t":["Hz. Muhammed gençlere güvenmiş, onlara önemli görevler vermiştir. Üsame b. Zeyd'i genç yaşında orduya komutan atamış, Mus'ab b. Umeyr'i Medinelilere İslam'ı öğretmek üzere göndermiştir. Kendisi de gençliğinde haksızlığa uğrayanları korumak için kurulan Hilfu'l-Fudul'a katılmıştır.","Gençlik, kişinin değerlerini oluşturduğu, ideallerinin şekillendiği önemli bir dönemdir. Gençlerin bilgiyle donanması, iyi arkadaş seçmesi ve topluma faydalı olması teşvik edilir."],"e":["Mus'ab bin Umeyr'in Medine'ye gönderilme amacı neydi?   A) Savaşmak   B) Ticaret yapmak   C) Sürgün edilmek   D) İslam'ı öğretmek","Doğru cevap: D) İslam'ı öğretmek. Genç yaşta öğretmen olarak görevlendirildi."]},"10:din1k1":{"a":"Allah'ı Tanımak: Allah'ın İnsana Yakınlığı, Dua ve Tövbe","o":["Kur'an'a göre Allah insana şah damarından daha yakındır (Kaf, 16)","Dua: insanın Allah'a yönelip yardım istemesi, şükretmesi; sözlü ve fiilî dua","Tövbe: yapılan hatadan pişmanlık duyup bir daha yapmamaya karar vermek","Allah'ın isimleri (Esmaü'l-Hüsna): Rahman, Rahim, Tevvab, Gaffar …","Kul hakkı: tövbe ile birlikte hak sahibiyle helalleşmeyi gerektirir"],"t":["Dua yalnızca istemek değildir; insanın acizliğini ve Allah'ın kudretini kabul etmesi, sıkıntıda umut, nimette şükür hâlidir. Çalışmadan yalnızca söz ile dua etmek yeterli görülmez; fiilî dua, sebeplere sarılmaktır.","Tövbe kapısının her zaman açık olduğu inancı, insanı ümitsizlikten korur ve hatalarını düzeltmeye teşvik eder."],"e":["Duada aracı (vasıta) gerekli midir?   A) Dua yasaktır   B) Evet, sadece din adamı dua edebilir   C) Hayır, kul doğrudan Allah'a dua eder   D) Evet, mutlaka bir aracı gerekir","Doğru cevap: C) Hayır, kul doğrudan Allah'a dua eder. İslam'da kul ile Allah arasında aracı yoktur."]},"10:din4k1":{"a":"Hz. Muhammed'in Hayatından Örnekler","o":["Gençliğinde 'el-Emin' (güvenilir) olarak tanındı","Hilfü'l-Fudûl: haksızlığa uğrayanlara yardım için kurulan cemiyete katıldı","Hacerü'l-Esved olayında hakemlik: kabileleri barıştıran adil çözüm","Medine Sözleşmesi: farklı inançtan topluluklarla birlikte yaşama esasları","Merhamet, istişare (danışma), tevazu ve sabır örnekleri"],"t":["Hz. Muhammed, Kâbe'nin onarımında Hacerü'l-Esved'i yerine koyma konusunda anlaşamayan kabilelere taşı bir örtüye koydurup her kabileden birinin ucundan tutmasını sağlayarak çatışmayı önledi. Bu olay adalet ve barışçı çözüm anlayışını gösterir.","Uhud Savaşı öncesinde ashabıyla istişare ederek çoğunluğun görüşüne uyması, danışmanın önemini gösteren bir örnektir."],"e":["Hz. Muhammed'in eğitime verdiği önemi gösteren olay hangisidir?   A) Bedir esirlerinin Müslümanlara okuma yazma öğretmesi karşılığında serbest bırakılması   B) Kitapları yakması   C) Okulları kapatması   D) Esirleri cezalandırması","Doğru cevap: A) Bedir esirlerinin Müslümanlara okuma yazma öğretmesi karşılığında serbest bırakılması. Eğitim fidye sayılmıştır."]},"9:din4k1":{"a":"Din, Kültür ve Birlikte Yaşam","o":["Din kültürü etkiler: mimari (cami, külliye), sanat (hat, tezhip), gelenekler","Vakıf: toplum yararına mal bağışlama kurumu","Farklı inançlara saygı: \"Dinde zorlama yoktur.\"","Toplumsal değerler: yardımlaşma, komşuluk, misafirperverlik"],"t":["Din, toplumun kültürünü, sanatını ve geleneklerini derinden etkiler. Camiler, külliyeler, hat ve tezhip sanatı bunun örnekleridir. Vakıflar; aşevi, çeşme, kütüphane ve okul gibi hizmetlerle tarih boyunca toplumsal dayanışmayı güçlendirmiştir.","İslam, farklı inançlardan insanların bir arada yaşamasına önem verir; inanç özgürlüğünü tanır. Komşuluk, yardımlaşma ve misafirperverlik toplumu bir arada tutan değerlerdir."],"e":["Mevlana'nın \"Gel, ne olursan ol yine gel.\" sözü neyi ifade eder?   A) Öfkeyi   B) Hoşgörüyü   C) Dışlayıcılığı   D) Kibri","Doğru cevap: B) Hoşgörüyü. Mevlana hoşgörünün simgesidir."]},"10:din3k1":{"a":"İslam Ahlakının Temel İlkeleri ve Evrensel Mesajları","o":["Güzel ahlak: doğruluk, adalet, emanete riayet, merhamet, sabır, tevazu, cömertlik","Kötü huylar: yalan, kibir, haset, gıybet, israf","Hz. Muhammed: 'Ben güzel ahlakı tamamlamak için gönderildim.'","Ahlaki sorumluluk aklı ve iradesi olan insana yüklenir","Ahlak bireysel olduğu kadar toplumsal hayatın da temelidir"],"t":["İslam ahlakında niyet ve davranış birlikte değerlendirilir. Doğruluk yalnızca sözde değil, alışverişte ölçüyü tam tutmak ve emanete hıyanet etmemek gibi davranışlarda da gösterilmelidir.","Gıybet (bir kimseyi arkasından hoşlanmayacağı biçimde anmak) ve haset (başkasının nimetinin yok olmasını istemek), toplumsal güveni ve kardeşliği zedeleyen kötü huylardır."],"e":["İsraf ne demektir?   A) Biriktirmek   B) Nimetleri gereksiz yere harcamak   C) Tasarruf   D) Paylaşmak","Doğru cevap: B) Nimetleri gereksiz yere harcamak. İsraf dinimizde yasaklanmıştır."]},"12:din3k1":{"a":"Tasavvuf ve Tarikatlar","o":["Tasavvuf: nefsi arındırarak Allah'a yakınlaşmayı ve güzel ahlakı kazanmayı amaçlayan anlayış","Temel kavramlar: tövbe, zühd, takva, tevekkül, ihlas, mürşit, mürit","Tarikat: tasavvufi eğitimin yapıldığı yol ve kurum (Yesevilik, Mevlevilik, Nakşibendilik, Kadirilik)","Tasavvuf edebiyatı ve musikisi kültürü zenginleştirmiştir","Ölçüt: Kur'an ve sünnete uygunluk; din istismarına karşı dikkatli olmak"],"t":["Tasavvufi yorumlar, İslam'ın ibadet ve ahlak boyutunu derinleştirerek kişinin iç dünyasını eğitmeyi hedefler. Mevlevilikteki sema, Allah'a yöneliş ve teslimiyetin sembolik bir ifadesidir.","Dinî yorumların değerlendirilmesinde temel ölçüt Kur'an ve Hz. Peygamber'in sünnetidir; dini kişisel çıkar için kullanan yapılara karşı akıl ve bilgiyle hareket edilmelidir."],"e":["Tasavvuf ile tarikat kavramları arasındaki fark nedir?","Tasavvuf, kalbi arındırarak Allah'a yakınlaşmayı amaçlayan manevi yaşayış ve düşünce biçimidir. Tarikat ise bu yolda bir mürşidin rehberliğinde izlenen, belirli usul ve kuralları olan yapılanmadır (Mevlevîlik, Nakşibendîlik gibi)."],"h":"Tasavvufu İslam'dan ayrı bir din sanmak: tasavvuf İslam'ın manevi boyutunu esas alan bir yorumdur."},"12:din4k1":{"a":"Güncel Meseleler, Hinduizm, Budizm ve Çin Dinleri","o":["Güncel meseleler: bilim-teknoloji ve din (organ bağışı, sosyal medya etiği), çevre, din istismarı","Hinduizm: kutsal metinler Vedalar; reenkarnasyon (samsara), karma, kast sistemi","Budizm: Buda (Siddhartha Gautama); dört yüce gerçek, sekiz dilimli yol, nirvana","Konfüçyüsçülük: ahlak ve toplumsal düzen; aile ve atalara saygı","Taoizm: Lao Tzu; doğayla uyum (Tao)"],"t":["Budizm'e göre acının kaynağı arzulardır; arzulardan kurtulmanın yolu sekiz dilimli yoldur ve sonunda nirvanaya, yani acıdan kurtuluşa ulaşılır.","Konfüçyüsçülük daha çok bir ahlak ve toplum öğretisidir; yöneten-yönetilen, ebeveyn-çocuk gibi ilişkilerde karşılıklı sorumlulukları vurgular."],"e":["Hinduizm ve Budizm arasındaki temel farklardan birini yazınız.","Hinduizm kast sistemini kabul eder ve tanrı inancı (Brahman) merkezîdir; Budizm ise kast sistemini reddeder, acıdan kurtuluşu (nirvana) Buda'nın öğrettiği Sekiz Aşamalı Yol ile arar ve tanrı kavramına merkezî yer vermez."],"h":"Konfüçyüsçülüğü yalnızca bir din sanmak: aynı zamanda ahlak ve toplum düzeni öğretisidir."},"9:fiz1k1":{"a":"Fiziğin Alt Dalları, Büyüklükler ve Birimler","o":["Alt dallar: mekanik, termodinamik, elektromanyetizma, optik, katı hâl, atom, nükleer, yüksek enerji fiziği","Temel büyüklükler (SI): uzunluk (m), kütle (kg), zaman (s), sıcaklık (K), akım (A), madde miktarı (mol), ışık şiddeti (cd)","Türetilmiş büyüklükler: hız, kuvvet (N), enerji (J), basınç (Pa)","Skaler: yalnız büyüklük (kütle, zaman, enerji) · Vektörel: büyüklük + yön (kuvvet, hız, yer değiştirme)"],"t":["Fizik, madde ve enerji arasındaki etkileşimi inceleyen bilimdir ve teknolojiyle iç içedir: optik gözlük ve kameraların, elektromanyetizma motorların, nükleer fizik enerji santrallerinin temelidir. Fizikte bilgi gözlem, hipotez, deney ve modelleme yoluyla üretilir.","Fiziksel büyüklükler temel ve türetilmiş olarak ikiye ayrılır. Temel büyüklükler SI'da yedi tanedir; diğerleri bunlardan türetilir. Yalnızca sayı ve birimle ifade edilen büyüklükler skaler, yön de belirtilmesi gerekenler vektörel büyüklüklerdir."],"e":["Isı ve sıcaklık olaylarını inceleyen fizik alt dalı hangisidir?   A) Mekanik   B) Termodinamik   C) Nükleer fizik   D) Optik","Doğru cevap: B) Termodinamik. Isı alışverişi termodinamiğin konusudur."]},"6:f5k3":{"a":"Yoğunluk","o":["Yoğunluk = kütle ÷ hacim (d = m ÷ V)","Birimi: g/cm³","Kütle = yoğunluk × hacim · Hacim = kütle ÷ yoğunluk","Suyun yoğunluğu 1 g/cm³","Yoğunluğu sudan küçük olan yüzer, büyük olan batar."],"t":["Bir maddenin birim hacminin kütlesine yoğunluk denir. Yoğunluk = kütle ÷ hacim formülüyle hesaplanır. Kütle gram (g), hacim santimetreküp (cm³) ise yoğunluk birimi g/cm³ olur.","Örneğin kütlesi 60 g, hacmi 20 cm³ olan bir taşın yoğunluğu 60 ÷ 20 = 3 g/cm³'tür.","Yoğunluk ayırt edici bir özelliktir. Aynı sıcaklıkta bir maddenin büyük ya da küçük parçasının yoğunluğu aynıdır. Bir demir çivi ile demir bir köprünün yoğunluğu eşittir.","Suyun yoğunluğu 1 g/cm³'tür. Yoğunluğu sudan küçük olan maddeler (tahta, yağ, buz) suda yüzer; büyük olanlar (demir, taş) batar. Birbirine karışmayan sıvılarda yoğunluğu büyük olan altta kalır."],"e":["Yoğunluğu 6 g/cm³ olan bir maddenin 14 cm³'ünün kütlesi kaç gramdır?   A) 84   B) 78   C) 90   D) 20","Doğru cevap: A) 84. Kütle = yoğunluk × hacim = 6 × 14 = 84 g."]},"10:fiz1k1":{"a":"Bir Boyutta Hareket: Konum, Hız ve İvme","o":["Yer değiştirme = son konum − ilk konum (vektörel) · Alınan yol skalerdir","Ortalama hız = yer değiştirme / süre · Ortalama sürat = alınan yol / süre","İvme a = Δv / Δt · Düzgün doğrusal harekette a = 0, x = v · t","Sabit ivmeli hareket: v = v₀ + a·t · x = v₀·t + (1/2)·a·t² · v² = v₀² + 2·a·x","Konum-zaman grafiğinin eğimi hızı, hız-zaman grafiğinin eğimi ivmeyi, altındaki alan yer değiştirmeyi verir"],"t":["Hareketi anlatmak için bir başlangıç noktası ve yön seçilir. Doğu yönü pozitif seçilirse batıya giden cismin hızı negatif yazılır. Bu nedenle yer değiştirme ile alınan yol farklı olabilir: 5 m doğuya gidip 5 m geri dönen cismin yer değiştirmesi sıfırdır.","Grafik yorumlama fizikte en çok kullanılan beceridir. Hız-zaman grafiğinde yatay doğru sabit hızı, eğik doğru sabit ivmeyi gösterir; grafikle zaman ekseni arasındaki alan, o aralıktaki yer değiştirmedir."],"e":["144 km/h kaç m/s'dir?   A) 4 m/s   B) 45 m/s   C) 518,4 m/s   D) 40 m/s","Doğru cevap: D) 40 m/s. km/h ÷ 3,6 = m/s."]},"10:fiz1k2":{"a":"Newton'un Hareket Yasaları","o":["1. yasa (eylemsizlik): net kuvvet sıfırsa cisim durur ya da sabit hızla gider","2. yasa: F_net = m · a (N = kg · m/s²)","3. yasa (etki-tepki): kuvvetler çift hâlinde, eşit büyüklükte ve zıt yönde, farklı cisimlere etki eder","Ağırlık G = m · g (g ≈ 10 m/s²) · Sürtünme kuvveti harekete zıt yönlüdür","Net kuvvet hareket yönündeyse cisim hızlanır, zıt yöndeyse yavaşlar"],"t":["Eylemsizlik, cismin hareket durumunu koruma eğilimidir. Fren yapan otobüste yolcuların öne doğru gitmesi, emniyet kemerinin önemi bu yasayla açıklanır.","Etki ile tepki aynı cisme uygulanmadığı için birbirini dengelemez. Masanın üzerindeki kitapta ağırlık ile masanın tepki kuvveti dengelenir; ama bunlar etki-tepki çifti değildir. Kitabın ağırlığının tepkisi, kitabın Dünya'yı çekmesidir."],"e":["54 km/h kaç m/s'dir?   A) 20 m/s   B) 1,5 m/s   C) 15 m/s   D) 194,4 m/s","Doğru cevap: C) 15 m/s. km/h ÷ 3,6 = m/s."]},"10:fiz2k1":{"a":"İş, Güç ve Enerjinin Korunumu","o":["İş W = F · x (kuvvet yönündeki yer değiştirme) · birimi joule (J)","Kinetik enerji Ek = (1/2) · m · v² · Yer çekimi potansiyel enerjisi Ep = m · g · h","Güç P = W / t (watt) · Verim = yararlı enerji / harcanan enerji","Sürtünmesiz ortamda mekanik enerji (Ek + Ep) korunur","Sürtünme varsa mekanik enerjinin bir kısmı ısıya dönüşür; toplam enerji yine korunur"],"t":["Enerji yoktan var edilemez, vardan yok edilemez; yalnızca bir türden başka bir türe dönüşür. Serbest bırakılan bir cisim düşerken potansiyel enerjisi azalır, kinetik enerjisi aynı miktarda artar.","Kuvvet hareket yönüne dik ise iş yapılmaz: çantayı yatay yolda taşıyan kişi, çantaya yer çekimine karşı fizik anlamında iş yapmaz."],"e":["18 kg kütleli, 10 m/s hızlı cismin kinetik enerjisi kaç J'dür?   A) 90 J   B) 900 J   C) 180 J   D) 1800 J","Doğru cevap: B) 900 J. Ek = ½·m·v²."]},"6:f5k1":{"a":"Genleşme ve Büzülme","o":["Isı alan madde genleşir, ısı veren madde büzülür.","En çok gazlar, en az katılar genleşir.","Tren rayları ve köprülerde genleşme boşluğu bırakılır.","Elektrik telleri yazın sarkar, kışın gerilir.","Su 0–4 °C arasında farklı davranır; buz suda yüzer."],"t":["Maddeler ısı aldığında tanecikleri daha hızlı hareket eder ve birbirinden uzaklaşır; madde genleşir. Isı verdiğinde ise tanecikler yavaşlar ve yaklaşır; madde büzülür.","Aynı miktarda ısı verildiğinde gazlar sıvılardan, sıvılar da katılardan daha çok genleşir. Farklı katılar ve farklı sıvılar da farklı miktarda genleşir; bu yüzden genleşme maddeler için ayırt edici bir özelliktir.","Günlük hayatta genleşmeyi dikkate alırız. Tren raylarının ve köprülerin arasına genleşme boşluğu bırakılır. Elektrik telleri yazın sarkık, kışın gergin görünür. Sıkışan metal kavanoz kapağı sıcak suya tutulunca genleşir ve kolay açılır. Termometrelerdeki sıvı da ısınınca genleşip yükselir.","Su ilginç bir maddedir: 4 °C'den 0 °C'ye soğutulurken büzülmek yerine genleşir. Bu yüzden buz sudan hafiftir ve suyun üstünde yüzer."],"e":["Genleşme ve büzülme ile ilgili hangisi yanlıştır?   A) Elektrik telleri kışın sarkar.   B) Buz suyun üzerinde yüzer.   C) Isı veren maddeler büzülür.   D) Genleşmede maddenin tanecikleri birbirinden uzaklaşır.","Doğru cevap: A) Elektrik telleri kışın sarkar.. \"Elektrik telleri kışın sarkar.\" ifadesi yanlıştır."]},"11:fiz3k2":{"a":"Elektriksel Kuvvet, Elektriksel Alan ve Manyetik Alan","o":["Coulomb: F = k·q₁·q₂ / d²","Elektrik alan E = F / q · alan çizgileri + yükten çıkar, − yüke girer","Akım geçen tel çevresinde manyetik alan oluşur (sağ el kuralı).","Manyetik akı değişimi indüksiyon akımı oluşturur (jeneratör ilkesi).","Transformatör: alternatif akımda gerilimi yükseltir/düşürür."],"t":["İki yük arasındaki elektriksel kuvvet yüklerin çarpımıyla doğru, aralarındaki uzaklığın karesiyle ters orantılıdır. Uzaklık iki katına çıkarsa kuvvet dörtte birine iner. Bir yükün çevresinde elektrik alan oluşur; alan çizgileri pozitif yükten çıkar, negatif yüke girer.","Üzerinden akım geçen telin çevresinde manyetik alan oluşur. Bir bobindeki manyetik akının değişmesi bobinde indüksiyon akımı doğurur; elektrik santrallerindeki jeneratörler bu ilkeyle çalışır. Transformatörler alternatif akımın gerilimini değiştirerek elektriğin uzak mesafelere az kayıpla iletilmesini sağlar."],"e":["Elektrik motorlarında hangi enerji dönüşümü olur?   A) Isı → ışık   B) Elektrik → mekanik (hareket)   C) Kimyasal → ses   D) Mekanik → elektrik","Doğru cevap: B) Elektrik → mekanik (hareket). Akım geçen bobin manyetik alanda döner."]},"10:fiz3k1":{"a":"Elektrik Akımı, Direnç ve Basit Devreler","o":["Akım I = q / t (amper) · Potansiyel fark V (volt) · Direnç R (ohm)","Ohm yasası: V = I · R","Seri bağlama: R_eş = R₁ + R₂ (akım aynı) · Paralel bağlama: 1/R_eş = 1/R₁ + 1/R₂ (gerilim aynı)","Elektriksel güç P = V · I = I² · R · Enerji E = P · t","Bir iletkenin direnci boyuyla doğru, kesit alanıyla ters orantılıdır"],"t":["Devrede akım, üretecin oluşturduğu potansiyel farkla yüklerin iletken boyunca hareket etmesidir. Seri bağlı ampullerden biri bozulursa devre açılır ve diğerleri de söner; evlerde bu yüzden paralel bağlama kullanılır.","Paralel kollarda eşdeğer direnç en küçük dirençten bile küçüktür. Kola eklenen her yeni direnç ana koldan çekilen akımı artırır; prizlere çok sayıda cihaz bağlamak bu nedenle aşırı akım ve ısınmaya yol açabilir."],"e":["8 Ω, 7 Ω ve 8 Ω'luk dirençler seri bağlanırsa eşdeğer direnç kaç Ω olur?   A) 448 Ω   B) 23 Ω   C) 15 Ω   D) 7,667 Ω","Doğru cevap: B) 23 Ω. Seride dirençler toplanır."]},"9:fiz3k1":{"a":"Basınç ve Kaldırma Kuvveti","o":["Katı basıncı P = F / A · Sıvı basıncı P = h · d · g","Kaldırma kuvveti: Fk = V(batan) · d(sıvı) · g","Yüzme: d(cisim) < d(sıvı) · Askıda kalma: eşit · Batma: d(cisim) > d(sıvı)","Bernoulli: akışkanın hızı arttıkça basıncı azalır."],"t":["Sıvılar ağırlıkları nedeniyle bulundukları kabın tabanına ve çeperlerine basınç uygular; bu basınç derinlik ve sıvının yoğunluğuyla doğru orantılıdır. Sıvı içindeki cisimlere yukarı yönlü kaldırma kuvveti etki eder; bu kuvvet cismin batan hacmi kadar sıvının ağırlığına eşittir (Arşimet ilkesi).","Bir cismin yüzmesi, askıda kalması ya da batması, cismin özkütlesinin sıvının özkütlesiyle karşılaştırılmasına bağlıdır. Akışkanların hızı arttıkça basıncının azalması (Bernoulli ilkesi) uçak kanatlarının kaldırma kuvvetini açıklar."],"e":["Hacmi 3 L olan cisim suya tamamen batırılıyor. Kaldırma kuvveti kaç N'dur? (d = 1000 kg/m³, g = 10)   A) 3 N   B) 300 N   C) 30 N   D) 40 N","Doğru cevap: C) 30 N. Fk = V·d·g = 3·10⁻³·1000·10 = 30 N."]},"10:fiz4k1":{"a":"Dalgaların Temel Özellikleri, Ses ve Işık","o":["Dalga enerji taşır, madde taşımaz · Mekanik dalga (ses) ortam ister, elektromanyetik dalga (ışık) boşlukta da yayılır","Enine dalga: titreşim yayılma yönüne dik (ip dalgası, ışık) · Boyuna dalga: paralel (ses)","v = λ · f · Periyot T = 1/f","Dalganın hızı ortama bağlıdır; frekansı kaynağa bağlıdır","Ses katılarda en hızlı, gazlarda en yavaş yayılır; ışığın boşluktaki hızı 3·10⁸ m/s"],"t":["Dalga bir ortamdan diğerine geçerken frekansı değişmez, hızı ve dalga boyu değişir. Ses havadan suya geçince hızlanır, dalga boyu büyür.","Sesin yüksekliği (ince-kalın) frekansla, şiddeti (yüksek-alçak ses) genlikle ilgilidir. Yankı ve sonar, sesin yansımasından yararlanır."],"e":["Bir kişi sesini bir duvardan 8 s sonra yankı olarak duyuyor. Ses hızı 340 m/s ise duvara uzaklık kaç m'dir?   A) 1360 m   B) 42,5 m   C) 2720 m   D) 170 m","Doğru cevap: A) 1360 m. Ses gidip döner: x = v·t/2."]},"11:fiz11o1":{"a":"Aydınlanma, Düzlem Aynalar ve Küresel Aynalar","o":["Işık şiddeti (I): kaynağın birim zamanda yaydığı ışık miktarının ölçüsü, birimi kandela (cd). Işık akısı (Φ): birim zamanda yayılan ışık enerjisi, birimi lümen (lm).","Aydınlanma şiddeti E = I / d² (ışık yüzeye dik gelirse); birimi lüks (lx). Uzaklık 2 katına çıkarsa aydınlanma 1/4'üne düşer.","Yansıma kanunları: gelme açısı yansıma açısına eşittir; gelen ışın, normal ve yansıyan ışın aynı düzlemdedir.","Düzlem aynada görüntü: düz, cisimle aynı boyda, aynaya uzaklığı cisimle aynı, sanal ve sağ–sol ters.","Çukur ayna ışınları odakta toplar (F = r/2); cismin konumuna göre gerçek–ters veya sanal–düz–büyük görüntü verir. Tümsek ayna ışınları dağıtır; görüntü her zaman sanal, düz ve küçüktür."],"t":["Masa lambası kitaba yaklaştırılınca sayfa daha aydınlık görünür: aydınlanma uzaklığın karesiyle ters orantılıdır.","Çukur aynada asal eksene paralel gelen ışın odaktan geçecek şekilde, odaktan gelen ışın asal eksene paralel yansır; merkezden gelen ışın kendi üzerinden geri döner. Bu özel ışınlarla görüntü çizilir.","Cisim çukur aynanın odağı ile ayna arasındaysa görüntü sanal, düz ve büyüktür (makyaj aynası). Cisim merkezin dışındaysa görüntü gerçek, ters ve küçüktür.","Düzlem aynada görüntüyü tam boy görmek için ayna boyunun en az kişinin boyunun yarısı kadar olması gerekir."],"e":["İki lambadan biri 40 cd ve yüzeye 2 m, diğeri 90 cd ve yüzeye 3 m uzaklıktadır. Hangisi yüzeyi daha çok aydınlatır?","E₁ = 40/2² = 10 lx, E₂ = 90/3² = 10 lx. Aydınlanmalar eşittir; daha güçlü lambanın uzakta olması avantajını ortadan kaldırmıştır."],"h":"Aydınlanmanın uzaklıkla doğrusal azaldığını sanmak (uzaklığın karesiyle azalır)."},"9:kim1k1":{"a":"Kimyanın Alanları ve Güvenlik","o":["Simyadan kimyaya: deneysel yöntem; Robert Boyle, Lavoisier (kütlenin korunumu)","Alt dallar: analitik, organik, anorganik, fizikokimya, biyokimya, polimer","Güvenlik sembolleri: yanıcı, aşındırıcı, zehirli, patlayıcı, tahriş edici, çevreye zararlı","Laboratuvarda: önlük, gözlük, eldiven; kimyasallar tadılmaz, koklanmaz."],"t":["Simya, maddeleri dönüştürmeye çalışan ancak sistematik bilgi üretmeyen bir uğraştı. Kimya ise deney ve gözleme dayanan bir bilimdir; Lavoisier kütlenin korunumu yasasıyla kimyayı nicel bir bilim hâline getirmiştir. Cabir bin Hayyan damıtma ve süzme gibi tekniklerde önemli katkılar sağlamıştır.","Kimyasal maddelerin ambalajlarında tehlike sembolleri bulunur. Laboratuvarda koruyucu ekipman kullanılmalı, kimyasallar etiketsiz kaplarda saklanmamalı, asit sulandırılırken asit suya yavaşça eklenmelidir."],"e":["Simya ile kimya arasındaki temel fark nedir?   A) Kimya deney ve bilimsel yönteme dayanır   B) Kimya sadece altın üretir   C) Simya bilimseldir   D) İkisi aynıdır","Doğru cevap: A) Kimya deney ve bilimsel yönteme dayanır. Simya deneme-yanılma ve gizemciliğe dayanır."]},"9:kim2k1":{"a":"Atom Modelleri ve Atomun Yapısı","o":["Dalton (içi dolu küre) → Thomson (üzümlü kek) → Rutherford (çekirdek) → Bohr (katmanlar) → Modern atom modeli","Proton (+) ve nötron çekirdekte, elektron (−) katmanlarda","Atom numarası = proton sayısı · Kütle numarası = proton + nötron","İzotop: proton sayısı aynı, nötron sayısı farklı","İyon: elektron alan (−) anyon, elektron veren (+) katyon"],"t":["Atom hakkındaki düşünceler deneylerle gelişmiştir. Thomson elektronu keşfetti; Rutherford altın levha deneyiyle atomun kütlesinin küçük ve pozitif yüklü bir çekirdekte toplandığını gösterdi; Bohr elektronların belirli enerji düzeylerinde bulunduğunu açıkladı. Modern atom modelinde elektronların yeri olasılıklarla (orbital) ifade edilir.","Bir atomun kimliğini proton sayısı belirler. Nötr atomda proton ve elektron sayıları eşittir; elektron alıp veren atomlar iyon olur. Aynı elementin nötron sayısı farklı atomlarına izotop denir: ¹²C ve ¹⁴C."],"e":["Atom numarası 11 olan Na atomunun 1+ yüklü iyonunda kaç elektron vardır?   A) 1   B) 11   C) 10   D) 12","Doğru cevap: C) 10. Pozitif iyon elektron kaybetmiştir."]},"9:kim3k1":{"a":"İyonik ve Kovalent Bağ","o":["İyonik bağ: metal + ametal, elektron alışverişi (NaCl)","Kovalent bağ: ametal + ametal, elektron ortaklaşması (H₂O, CO₂)","Apolar kovalent: aynı atomlar (H₂, O₂) · Polar: farklı atomlar (HCl)","Metalik bağ: metal katyonları ve serbest elektronlar (elektrik iletkenliği)","Zayıf etkileşimler: hidrojen bağı, van der Waals"],"t":["Atomlar kararlı hâle (soy gaz elektron düzenine) ulaşmak için bağ yapar. Metaller elektron verip katyon, ametaller elektron alıp anyon oluşturur; zıt yüklü iyonlar arasındaki elektrostatik çekime iyonik bağ denir. İki ametal ise elektronlarını ortaklaşa kullanarak kovalent bağ oluşturur.","Moleküller arasında oluşan zayıf etkileşimler maddelerin kaynama noktası ve çözünürlük gibi fiziksel özelliklerini belirler. Su molekülleri arasındaki hidrojen bağları suyun kaynama noktasının beklenenden yüksek olmasını sağlar."],"e":["Kütle numarası 14, atom numarası 7 olan N atomunun nötron sayısı kaçtır?   A) 21   B) 14   C) 7   D) 3,5","Doğru cevap: C) 7. Nötron = kütle no − atom no."]},"9:kim4k1":{"a":"Katı, Sıvı, Gaz ve Hâl Değişimleri","o":["Katı: düzenli, titreşim · Sıvı: akışkan, öteleme · Gaz: düzensiz, tanecikler arası boşluk çok","Erime-donma, buharlaşma-yoğuşma, süblimleşme-kırağılaşma","Kaynama noktası dış basınca bağlıdır; basınç düşükse daha düşük sıcaklıkta kaynar.","Plazma: iyonlaşmış gaz (yıldızlar, şimşek)"],"t":["Maddenin hâlleri taneciklerin düzenine ve hareketine göre belirlenir. Katılarda tanecikler düzenli dizilmiş ve yalnızca titreşir; sıvılarda tanecikler birbiri üzerinden kayar; gazlarda tanecikler arası uzaklık çok büyüktür ve tanecikler serbestçe hareket eder.","Hâl değişimleri ısı alışverişiyle olur: erime, buharlaşma ve süblimleşme ısı alarak; donma, yoğuşma ve kırağılaşma ısı vererek gerçekleşir. Yüksek rakımlarda açık hava basıncı düşük olduğu için su 100 °C'den düşük sıcaklıkta kaynar."],"e":["Sabit basınçta 400 K sıcaklıktaki gazın hacmi 8 L'dir. Sıcaklık 800 K olursa hacim kaç L olur?   A) 10 L   B) 16 L   C) 4 L   D) 8 L","Doğru cevap: B) 16 L. Charles: V/T sabit."]},"10:kim3k1":{"a":"Yeşil Kimya ve Kaynakların Bilinçli Kullanımı","o":["Yeşil kimya: atık oluşmasını önlemek, zararsız madde ve çözücü kullanmak, enerji verimliliği","Atom ekonomisi: girenlerdeki atomların ne kadarının istenen ürüne dönüştüğü","Geri dönüşüm: cam, metal, kâğıt, plastik ayrı toplanır; kaynak ve enerji tasarrufu sağlar","Karbon ayak izi: bir etkinliğin doğrudan ve dolaylı sera gazı salımı","Yenilenebilir kaynaklar (güneş, rüzgâr, biyokütle) fosil yakıtlara göre daha az sera gazı salar"],"t":["Yeşil kimyanın amacı kirliliği oluştuktan sonra temizlemek değil, baştan önlemektir. Daha az adımlı, daha az enerji harcayan ve zehirli olmayan maddelerle yapılan üretim hem çevreyi hem maliyeti korur.","Alüminyumun geri dönüştürülmesi, cevherden yeniden üretmeye göre çok daha az enerji gerektirir. Bu nedenle metallerin geri kazanımı sürdürülebilirlik için önemlidir."],"e":["Yeşil kimyanın temel amacı nedir?   A) Sadece maliyeti artırmak   B) Fosil yakıt kullanımını artırmak   C) Daha çok atık üretmek   D) Çevreye zararsız, atık oluşturmayan kimyasal süreçler geliştirmek","Doğru cevap: D) Çevreye zararsız, atık oluşturmayan kimyasal süreçler geliştirmek. Önleme, tedaviden iyidir."]},"10:kim1k1":{"a":"Mol Kavramı ve Kimyasal Tepkimeler","o":["1 mol = 6,02·10²³ tanecik (Avogadro sayısı)","Mol sayısı n = kütle / mol kütlesi · Normal koşullarda 1 mol gaz 22,4 L","Kütlenin korunumu: tepkimeye girenlerin kütlesi = ürünlerin kütlesi","Denkleştirme: her elementin atom sayısı iki tarafta eşit olmalı","Tepkime türleri: yanma, sentez (birleşme), analiz (ayrışma), asit-baz (nötrleşme), çökelme"],"t":["Kimyasal tepkimelerde atomlar yok olmaz, yeniden düzenlenir; bu yüzden denklemler denkleştirilir. 2H₂ + O₂ → 2H₂O denkleminde katsayılar mol oranlarını verir: 2 mol hidrojen 1 mol oksijenle 2 mol su oluşturur.","Mol, gözle görülemeyecek kadar küçük tanecikleri saymanın birimidir. Örneğin suyun mol kütlesi 18 g/mol'dür; 36 g su 2 moldür ve 2 · 6,02·10²³ molekül içerir."],"e":["2 mol madde kaç tane tanecik içerir?   A) 12,04 · 10²²   B) 12,04 · 10²³   C) 2 · 10²³   D) 44,8 · 10²³","Doğru cevap: B) 12,04 · 10²³. N = n·6,02·10²³."]},"10:kim2k1":{"a":"Çözeltiler ve Derişim","o":["Çözelti: homojen karışım = çözücü + çözünen","Kütlece % = (çözünen kütlesi / çözelti kütlesi) · 100","Molarite M = çözünenin mol sayısı / çözelti hacmi (L)","Seyreltme: M₁ · V₁ = M₂ · V₂","Çözünen eklendikçe kaynama noktası yükselir, donma noktası düşer (koligatif özellik)"],"t":["Çözeltinin derişimi, belli miktardaki çözeltide ne kadar çözünen bulunduğunu gösterir. 200 g çözeltide 30 g tuz varsa çözelti kütlece %15'liktir.","Kışın yollara tuz serpilmesi, donma noktası alçalmasının günlük hayattaki uygulamasıdır; tuzlu su saf sudan daha düşük sıcaklıkta donar."],"e":["35 g tuz 10 g suda çözünüyor. Kütlece yüzde derişim kaçtır?   A) 35 %   B) 350 %   C) 22,2 %   D) 77,8 %","Doğru cevap: D) 77,8 %. %= çözünen/(çözünen+çözücü)·100."]},"11:kim4k3":{"a":"Asit–Baz Dengesi, pH, Nötrleşme ve Titrasyon","o":["Suyun oto-iyonlaşması: H₂O + H₂O ⇌ H₃O⁺ + OH⁻. 25 °C'de Ksu = [H₃O⁺] · [OH⁻] = 1 · 10⁻¹⁴; saf suda [H₃O⁺] = [OH⁻] = 10⁻⁷ M.","pH = −log[H₃O⁺], pOH = −log[OH⁻], 25 °C'de pH + pOH = 14. pH < 7 asidik, pH = 7 nötr, pH > 7 bazik.","Arrhenius: asit suda H⁺ (H₃O⁺), baz OH⁻ verir. Brønsted–Lowry: asit proton (H⁺) veren, baz proton alan türdür; proton alışverişiyle eşlenik asit–baz çiftleri oluşur.","Kuvvetli asit/baz suda tamamen iyonlaşır (HCl, HNO₃, H₂SO₄; NaOH, KOH). Zayıf asit/baz kısmen iyonlaşır (CH₃COOH, HF; NH₃); iyonlaşma yüzdesi küçüktür, Ka ve Kb ile ifade edilir.","Zayıf asitte yaklaşık [H₃O⁺] = √(Ka · Ca) (Ca/Ka > 10² iken geçerli). Aynı derişimde zayıf asidin pH'ı kuvvetli asidinkinden büyüktür."],"t":["0,01 M HCl kuvvetli asit olduğundan tamamen iyonlaşır: [H₃O⁺] = 10⁻² M → pH = 2. Aynı derişimdeki zayıf asit (ör. asetik asit) kısmen iyonlaştığı için [H₃O⁺] daha küçük, pH daha büyüktür.","Titrasyonda derişimi bilinmeyen çözeltiye derişimi bilinen çözelti (büretten) damla damla eklenir. İndikatörün renk değiştirdiği an (dönüm noktası) eşdeğerlik noktasına çok yakındır. İletkenlik ve pH ölçümleri de nötrleşmeyi izlemenin yollarıdır.","Günlük hayatta: mide ekşimesinde mide asidini nötrleştiren bazik antasitler, diş sağlığında florürlü macunlar, cilt için pH'ı ciltle uyumlu (hafif asidik, pH ≈ 5,5) ürünler tercih edilir."],"e":["Ka = 1,8 · 10⁻⁵ olan asetik asidin 0,1 M çözeltisinde yaklaşık [H₃O⁺] ve pH değerini bulunuz. (√1,8 ≈ 1,34; log 1,34 ≈ 0,13)","Ca/Ka = 0,1 / 1,8 · 10⁻⁵ > 10², yaklaşım geçerli. [H₃O⁺] = √(1,8 · 10⁻⁵ · 0,1) = √(1,8 · 10⁻⁶) ≈ 1,34 · 10⁻³ M. pH = 3 − log 1,34 ≈ 3 − 0,13 = 2,87. Karşılaştırma: 0,1 M HCl'nin pH'ı 1'dir."],"h":"pH'ın derişimle doğru orantılı arttığını sanmak (derişim artınca asidik çözeltide pH azalır)."},"9:bio1k1":{"a":"Canlıların Ortak Özellikleri ve Temel Bileşenler","o":["Ortak özellikler: hücresel yapı, beslenme, solunum, boşaltım, üreme, büyüme-gelişme, uyarılara tepki, metabolizma, homeostazi","İnorganik bileşenler: su, mineraller, asitler-bazlar","Organik bileşenler: karbonhidratlar, lipitler, proteinler, nükleik asitler, vitaminler, enzimler","Enzimler: protein yapılı biyolojik katalizörler; sıcaklık ve pH'tan etkilenir."],"t":["Canlıları cansızlardan ayıran ortak özellikler vardır: tüm canlılar hücrelerden oluşur, enerji üretmek için solunum yapar, metabolizma faaliyetleri gösterir, çevresel uyarılara tepki verir ve iç dengesini (homeostazi) korur. Virüsler hücresel yapıda olmadığı için canlı ile cansız arasında kabul edilir.","Canlıların yapısında inorganik ve organik bileşikler bulunur. Karbonhidratlar temel enerji kaynağı, lipitler yedek enerji ve yalıtım, proteinler yapı ve düzenleyici görevler, nükleik asitler (DNA, RNA) kalıtım görevini üstlenir. Enzimler kimyasal tepkimeleri hızlandırır; aşırı sıcaklıkta yapıları bozulur."],"e":["Hangi vitamin yağda çözünür?   A) C vitamini   B) A vitamini   C) B1 vitamini   D) B12 vitamini","Doğru cevap: B) A vitamini. A, D, E, K yağda çözünür."]},"10:bio1k1":{"a":"ATP, Metabolizma ve Enzimler","o":["ATP: hücrenin doğrudan kullandığı enerji molekülü (adenin + riboz + 3 fosfat)","Metabolizma = anabolizma (yapım, enerji harcar) + katabolizma (yıkım, enerji açığa çıkarır)","Enzimler: protein yapılı biyolojik katalizörler; tepkimeyi hızlandırır, tepkimeden değişmeden çıkar","Enzim etkinliğini sıcaklık, pH, substrat ve enzim derişimi etkiler","Enzim-substrat ilişkisi anahtar-kilit modeli ile açıklanır"],"t":["Canlılar besinlerdeki kimyasal enerjiyi doğrudan kullanamaz; bu enerji önce ATP'ye aktarılır. ATP'nin son fosfat bağı koparken açığa çıkan enerji kas kasılması, aktif taşıma ve sentez tepkimelerinde kullanılır.","Her enzimin en iyi çalıştığı bir sıcaklık ve pH vardır. Yüksek sıcaklık enzimin üç boyutlu yapısını bozar (denatürasyon); mide enzimi pepsin asidik, bağırsak enzimleri bazik ortamda çalışır."],"e":["Enzimler tepkimeden sonra ne olur?   A) Tükenir   B) Ürüne dönüşür   C) Parçalanır   D) Değişmeden çıkar, tekrar kullanılabilir","Doğru cevap: D) Değişmeden çıkar, tekrar kullanılabilir. Enzimler yeniden kullanılır."]},"9:bio2k1":{"a":"Hücre Yapısı ve Organeller","o":["Prokaryot: zarla çevrili çekirdek ve organel yok (bakteri) · Ökaryot: çekirdek ve zarlı organeller var","Hücre zarı: seçici geçirgen · Çekirdek: yönetim ve kalıtım","Mitokondri: enerji (ATP) · Kloroplast: fotosentez (bitki) · Ribozom: protein sentezi","Hücre teorisi (Schleiden, Schwann, Virchow): tüm canlılar hücrelerden oluşur, hücre önceki hücreden gelir.","Madde geçişi: difüzyon, osmoz, aktif taşıma, endositoz-ekzositoz"],"t":["Hücre teorisine göre tüm canlılar bir ya da daha çok hücreden oluşur, hücre canlılığın en küçük birimidir ve yeni hücreler var olan hücrelerin bölünmesiyle oluşur. Bakteriler prokaryot, bitki, hayvan ve mantar hücreleri ökaryottur.","Hücre zarı seçici geçirgendir. Difüzyon ve osmoz enerji harcanmadan, maddelerin çok yoğun ortamdan az yoğun ortama geçişidir; aktif taşıma ise ATP harcanarak az yoğundan çok yoğuna gerçekleşir. Bitki hücrelerinde hücre duvarı ve kloroplast, hayvan hücrelerinde sentrozom bulunur."],"e":["Salgı maddelerinin paketlendiği organel hangisidir?   A) Ribozom   B) Lizozom   C) Golgi cisimciği   D) Mitokondri","Doğru cevap: C) Golgi cisimciği. Golgi salgıları paketler ve gönderir."]},"9:bio3k1":{"a":"Sınıflandırma ve Âlemler","o":["Sınıflandırma basamakları: âlem > şube > sınıf > takım > aile > cins > tür","Tür: birbiriyle çiftleşip verimli döl verebilen bireyler","İkili adlandırma (Linnaeus): cins + tür adı → Homo sapiens","Âlemler: bakteriler, arkeler, protistler, bitkiler, mantarlar, hayvanlar","Basamak küçüldükçe ortak özellik artar, birey sayısı azalır."],"t":["Canlılar ortak özelliklerine göre gruplandırılır. Linnaeus'un geliştirdiği ikili adlandırmada her türün iki kelimeden oluşan bilimsel bir adı vardır; ilki cins, ikincisi tür adıdır ve Latince yazılır. Tür, sınıflandırmanın en küçük birimidir.","Sınıflandırma basamaklarında âlemden türe gidildikçe canlı çeşitliliği azalır, ortak özellik sayısı artar. Mantarlar hücre duvarı taşıdığı hâlde fotosentez yapamadığı için bitkilerden ayrı bir âlemde incelenir."],"e":["Canlıları sınıflandırmada en küçük birim hangisidir?   A) Âlem   B) Tür   C) Takım   D) Sınıf","Doğru cevap: B) Tür. Aynı türün bireyleri kendi aralarında verimli döller verir."]},"6:f3k1":{"a":"Eşeyli ve Eşeysiz Üreme","o":["Eşeysiz üreme: tek ata, yavrular atasıyla aynı.","Eşeysiz üreme çeşitleri: bölünme, tomurcuklanma, rejenerasyon, sporla, vejetatif","Eşeyli üreme: iki ata, üreme hücreleri birleşir (döllenme).","Eşeyli üremede yavrular farklı özellikler taşır → çeşitlilik","Dış döllenme: balık, kurbağa · İç döllenme: memeliler, kuşlar, sürüngenler"],"t":["Canlıların kendilerine benzer yeni bireyler oluşturmasına üreme denir. Üreme eşeysiz ve eşeyli olmak üzere ikiye ayrılır.","Eşeysiz üremede tek bir ata vardır ve oluşan yavrular atasıyla aynı özellikleri taşır. Bölünme (bakteri, amip), tomurcuklanma (bira mayası, hidra), rejenerasyon yani kopan parçadan yeni canlı oluşması (deniz yıldızı, planarya), sporla üreme (şapkalı mantar, eğrelti otu) ve vejetatif üreme (patates yumrusu, çilek, çelikle çoğaltılan söğüt) bu çeşitlerdendir.","Eşeyli üremede iki ata vardır. Dişi üreme hücresi (yumurta) ile erkek üreme hücresi (sperm) birleşir; buna döllenme denir. Yavrular iki atadan da özellik aldığı için çeşitlilik oluşur.","Döllenme vücut dışında (balık, kurbağa) ya da vücut içinde (memeliler, kuşlar, sürüngenler) olabilir. Çiçekli bitkilerde çiçek tozları dişi organa taşınır (tozlaşma), döllenme olur ve tohum oluşur. Tozlaşmada rüzgâr, su ve arı gibi böcekler rol oynar."],"e":["Üreme ile ilgili hangisi yanlıştır?   A) Eşeysiz üremede yavrular atasıyla aynı özelliktedir.   B) Eşeyli üreme çeşitliliği sağlar.   C) Döllenmeden sonra çiçekli bitkilerde tohum oluşur.   D) Eşeysiz üremede döllenme olur.","Doğru cevap: D) Eşeysiz üremede döllenme olur.. \"Eşeysiz üremede döllenme olur.\" ifadesi yanlıştır."]},"10:bio2k1":{"a":"Ekosistem, Besin Zinciri ve Madde Döngüleri","o":["Ekosistem: canlı (biyotik) ve cansız (abiyotik) öğelerin etkileşimi","Besin zinciri: üretici → birincil tüketici → ikincil tüketici …; ayrıştırıcılar maddeyi geri kazandırır","Her basamakta enerjinin yaklaşık %10'u bir üst basamağa aktarılır (enerji piramidi)","Karbon, azot ve su döngüleri maddeyi canlılar ile çevre arasında dolaştırır","Biyolojik birikim: zehirli maddeler üst basamaklarda daha yoğun birikir"],"t":["Enerji ekosistemde tek yönlü akar ve her basamakta büyük kısmı ısı olarak kaybolur; madde ise döngüler hâlinde yeniden kullanılır. Bu yüzden besin zincirleri genellikle 4-5 basamaktan uzun olmaz.","Azot döngüsünde bakteriler kilit roldedir: azot bağlayan bakteriler havadaki azotu bitkilerin kullanabileceği hâle getirir, ayrıştırıcılar ölü canlılardaki azotu toprağa geri kazandırır."],"e":["Ekosistemin canlı bileşenlerine ne denir?   A) Toprak   B) Abiyotik faktörler   C) Biyotik faktörler   D) İklim","Doğru cevap: C) Biyotik faktörler. Üreticiler, tüketiciler, ayrıştırıcılar."]},"10:bio2k2":{"a":"Popülasyon, Biyoçeşitlilik ve Sürdürülebilirlik","o":["Popülasyon: belli bir alanda yaşayan aynı türden bireyler · Komünite: farklı türlerin popülasyonları","Popülasyon büyüklüğünü doğum, ölüm, göç (giren-çıkan) belirler","Taşıma kapasitesi: ortamın kaynaklarıyla destekleyebileceği en fazla birey sayısı","Biyoçeşitliliği tehdit edenler: habitat kaybı, kirlilik, istilacı türler, aşırı avlanma, iklim değişikliği","Koruma: millî parklar, gen bankaları, sürdürülebilir tarım ve avcılık"],"t":["Kaynaklar sınırlı olduğundan popülasyonlar sonsuza kadar büyüyemez; taşıma kapasitesine yaklaştıkça büyüme yavaşlar. Besin, su ve barınak için rekabet artar.","Biyoçeşitlilik ekosistemlerin dengesini ve dayanıklılığını sağlar. Bir türün yok olması, ona bağlı başka türleri de etkileyerek zincirleme sonuçlar doğurabilir."],"e":["Biyoçeşitliliğin önemi nedir?   A) Ekosistemleri zayıflatır   B) Hiçbir önemi yoktur   C) Ekosistemlerin dengesini ve dayanıklılığını sağlar   D) Sadece estetik değeri vardır","Doğru cevap: C) Ekosistemlerin dengesini ve dayanıklılığını sağlar. Gıda, ilaç ve ekosistem hizmetleri sağlar."]},"11:mat11f1":{"a":"Fonksiyonlarda Dört İşlem, Bileşke ve Ters Fonksiyon","o":["(f + g)(x) = f(x) + g(x) · (f − g)(x) = f(x) − g(x) · (f · g)(x) = f(x) · g(x) · (f / g)(x) = f(x) / g(x), g(x) ≠ 0","İşlem fonksiyonlarının tanım kümesi, f ve g'nin tanım kümelerinin kesişimidir (bölmede ayrıca g(x) = 0 olan noktalar çıkarılır).","Bileşke: (f ∘ g)(x) = f(g(x)) — önce g, sonra f uygulanır. Genelde f ∘ g ≠ g ∘ f; bileşke birleşmelidir: f ∘ (g ∘ h) = (f ∘ g) ∘ h.","Ters fonksiyon: f bire bir ve örten ise f⁻¹ vardır ve (f ∘ f⁻¹)(x) = (f⁻¹ ∘ f)(x) = x. f(a) = b ⇔ f⁻¹(b) = a.","f(x) = ax + b ise f⁻¹(x) = (x − b) / a. f ile f⁻¹ grafikleri y = x doğrusuna göre simetriktir."],"t":["Bileşke bir 'makine zinciri' gibidir: x önce g makinesine girer, çıkan g(x) bu kez f makinesine girer. Örneğin g(x) = x + 2, f(x) = 3x ise (f ∘ g)(x) = 3(x + 2) = 3x + 6; (g ∘ f)(x) = 3x + 2. Sonuçlar farklıdır, yani bileşkede sıra önemlidir.","Ters fonksiyon bulmak için y = f(x) yazılır, x yalnız bırakılır, sonra x ile y'nin yeri değiştirilir: y = 2x − 5 → x = (y + 5)/2 → f⁻¹(x) = (x + 5)/2.","Nitel özelliklerin korunması: iki artan fonksiyonun toplamı artandır; artan iki fonksiyonun bileşkesi artandır; tek ile tek fonksiyonun bileşkesi tektir."],"e":["f(x) = 2x − 3 ve (f ∘ g)(x) = 6x + 5 ise g(x) nedir?","f(g(x)) = 2 · g(x) − 3 = 6x + 5 → 2 · g(x) = 6x + 8 → g(x) = 3x + 4. Kontrol: f(3x + 4) = 6x + 8 − 3 = 6x + 5 ✓"],"h":"(f ∘ g)(x)'i f(x) · g(x) sanmak; bileşke çarpma değildir."},"12:mattr1":{"a":"Toplam-Fark ve İki Kat Açı Formülleri","o":["sin²x + cos²x = 1 · tan x = sin x / cos x · cot x = cos x / sin x","sin(a ± b) = sin a · cos b ± cos a · sin b","cos(a ± b) = cos a · cos b ∓ sin a · sin b (işaret ters döner)","tan(a ± b) = (tan a ± tan b) / (1 ∓ tan a · tan b)","sin 2a = 2 sin a · cos a · cos 2a = cos²a − sin²a = 2cos²a − 1 = 1 − 2sin²a"],"t":["Toplam-fark formülleri, değerini bildiğimiz açılardan (30°, 45°, 60°, 90°) yeni açıların trigonometrik değerlerini bulmamızı sağlar. Örneğin 75° = 45° + 30° ve 15° = 45° − 30° yazılarak sin 75° ve sin 15° hesaplanır.","Kosinüste toplam formülünde işaret ters döner: cos(a + b) = cos a · cos b − sin a · sin b. En sık yapılan hata cos(a + b)'yi cos a + cos b sanmaktır; trigonometrik fonksiyonlar toplama üzerine dağılmaz.","İki kat açı formülleri toplam formülünde a = b alınarak elde edilir: sin 2a = sin(a + a) = 2 sin a cos a. cos 2a'nın üç farklı yazılışı vardır; soruda sin a verilmişse 1 − 2sin²a, cos a verilmişse 2cos²a − 1 kullanmak işi kısaltır.","Dar açılı bir dik üçgen çizmek değer bulmayı kolaylaştırır: sin x = 3/5 ise karşı kenar 3, hipotenüs 5, komşu kenar 4 olur; buradan cos x = 4/5, tan x = 3/4 okunur."],"e":["cos 105° değerini bulunuz.","105° = 60° + 45° yazılır. cos(60° + 45°) = cos 60° cos 45° − sin 60° sin 45° = (1/2)(√2/2) − (√3/2)(√2/2) = (√2 − √6)/4. Sonuç negatiftir; bu beklenen bir durumdur çünkü 105° ikinci bölgededir ve orada kosinüs negatiftir."],"h":"cos(a + b)'yi cos a + cos b sanmak: trigonometrik fonksiyonlar toplamaya dağılmaz."},"12:mat1k1":{"a":"Üstel Fonksiyon ve Logaritma","o":["f(x) = aˣ (a > 0, a ≠ 1) üstel fonksiyon · a > 1 artan, 0 < a < 1 azalan","logₐ b = c ⇔ aᶜ = b (a > 0, a ≠ 1, b > 0)","log(xy) = log x + log y · log(x/y) = log x − log y · log xⁿ = n · log x","Taban değiştirme: logₐ b = log b / log a · logₐ a = 1 · logₐ 1 = 0","ln x = logₑ x (e ≈ 2,718) · log x = log₁₀ x"],"t":["Logaritma, üs almanın tersidir: '2'nin kaçıncı kuvveti 8 eder?' sorusunun cevabı log₂ 8 = 3'tür. Bu nedenle üstel ve logaritmik fonksiyonlar birbirinin tersidir ve grafikleri y = x doğrusuna göre simetriktir.","Nüfus artışı, radyoaktif bozunma, faiz ve deprem büyüklüğü (Richter ölçeği) gibi olaylar üstel ve logaritmik modellerle açıklanır. Logaritmalı denklemlerde tanım koşulu (logaritmanın içinin pozitif olması) mutlaka kontrol edilir.","Üstel fonksiyon y = aˣ'in grafiği her zaman (0, 1) noktasından geçer ve x eksenine yaklaşır ama değmez (y = 0 yatay asimptot). Logaritma fonksiyonu y = logₐ x ise (1, 0)'dan geçer ve y eksenine yaklaşır (x = 0 düşey asimptot).","Üstel ve logaritmik eşitsizliklerde taban 1'den büyükse eşitsizliğin yönü korunur; taban 0 ile 1 arasındaysa yön değişir. Örneğin (1/2)ˣ > (1/2)³ ise x < 3'tür."],"e":["3ˣ⁺¹ = 81 denklemini çözünüz.","81 = 3⁴ yazılır: 3ˣ⁺¹ = 3⁴. Tabanlar eşit olduğundan üsler eşittir: x + 1 = 4 → x = 3."],"h":"log(x + y)'yi log x + log y sanmak: toplamın değil çarpımın logaritması toplanır."},"12:mat2k1":{"a":"Aritmetik ve Geometrik Diziler","o":["Aritmetik dizi: ardışık terim farkı sabit (d) · aₙ = a₁ + (n − 1)d","Aritmetik dizide ilk n terim toplamı Sₙ = n(a₁ + aₙ) / 2","Geometrik dizi: ardışık terim oranı sabit (r) · aₙ = a₁ · rⁿ⁻¹","Geometrik dizide Sₙ = a₁(rⁿ − 1) / (r − 1) (r ≠ 1)","Ortadaki terim: aritmetik → komşuların ortalaması; geometrik → komşuların çarpımının karekökü"],"t":["Aritmetik diziler eşit artışları (her ay aynı miktar biriktirmek), geometrik diziler yüzdesel artışları (bileşik faiz, nüfus) modeller.","Gauss'un 1'den 100'e kadar sayıları toplama yöntemi aritmetik dizi toplam formülünün temelidir: baştan ve sondan eşit uzaklıktaki terimlerin toplamı sabittir; 50 çift × 101 = 5050.","Dizi, tanım kümesi pozitif doğal sayılar olan bir fonksiyondur; aₙ dizinin genel terimidir. aₙ = 2n + 1 dizisinin terimleri 3, 5, 7, 9, … şeklindedir. Her terim bir öncekinden büyükse dizi artan, küçükse azalandır.","Bazı diziler bir önceki terimlere bağlı olarak tanımlanır (özyinelemeli tanım). Fibonacci dizisinde aₙ = aₙ₋₁ + aₙ₋₂ kuralıyla 1, 1, 2, 3, 5, 8, 13, … terimleri elde edilir."],"e":["5, 9, 13, …, 101 aritmetik dizisi kaç terimlidir?","a₁ = 5, d = 4. aₙ = 5 + (n − 1) · 4 = 101 → (n − 1) · 4 = 96 → n − 1 = 24 → n = 25 terim."],"h":"Genel terim formülünde (n − 1) yerine n kullanmak."},"12:matlm1":{"a":"Limit ve Süreklilik","o":["lim(x→a) f(x) = L: x, a'ya yaklaştıkça f(x) L'ye yaklaşır","Limitin var olması için soldan limit = sağdan limit olmalıdır","0/0 belirsizliğinde ifade çarpanlarına ayrılır ve sadeleştirilir","f, x = a'da süreklidir ⇔ f(a) tanımlı ve lim(x→a) f(x) = f(a)","Polinom fonksiyonlar her yerde süreklidir · rasyonel fonksiyonlar paydayı sıfır yapmayan her yerde süreklidir"],"t":["Limit, bir fonksiyonun bir noktaya yaklaşırken hangi değere yaklaştığını inceler; o noktadaki değerle aynı olmak zorunda değildir. f(x) = (x² − 4)/(x − 2) fonksiyonu x = 2'de tanımsızdır, ama x 2'ye yaklaştıkça değerler 4'e yaklaşır; bu yüzden limiti 4'tür.","Soldan limit, x'in a'ya küçük değerlerden; sağdan limit büyük değerlerden yaklaşmasıdır. Parçalı fonksiyonlarda kırılma noktasında iki taraf ayrı ayrı hesaplanır; eşit değilse limit yoktur.","Doğrudan yerine koyma 0/0 veriyorsa bu bir belirsizliktir, sonuç değildir. Pay ve payda çarpanlarına ayrılır, ortak çarpan sadeleşir, sonra yerine konur. Bu sadeleştirme, türev tanımındaki limitin hesaplanmasının da temelidir.","Süreklilik, grafiğin kalem kaldırmadan çizilebilmesidir. Bir noktada sürekli olmak için üç koşul birlikte gerekir: fonksiyon o noktada tanımlı olmalı, limit var olmalı ve limit fonksiyon değerine eşit olmalıdır."],"e":["lim(x→3) (x² − 9)/(x² − 3x) limitini hesaplayınız.","1) Yerine koyma: (9 − 9)/(9 − 9) = 0/0 → belirsizlik. 2) Çarpanlara ayır: (x − 3)(x + 3) / x(x − 3). 3) Sadeleştir: (x + 3)/x. 4) Yerine koy: 6/3 = 2."],"h":"0/0'ı sonuç sanıp 'limit 0' ya da 'limit yok' demek: 0/0 bir belirsizliktir, sadeleştirme gerekir."},"12:mat3k1":{"a":"Limit ve Türev Kuralları","o":["Türev: anlık değişim oranı · f′(x) = lim(h→0) [f(x + h) − f(x)] / h","(xⁿ)′ = n · xⁿ⁻¹ · (c)′ = 0 · (c · f)′ = c · f′","Çarpım: (f · g)′ = f′g + fg′ · Bölüm: (f/g)′ = (f′g − fg′) / g²","Zincir kuralı: [f(g(x))]′ = f′(g(x)) · g′(x)","Bir noktadaki türev, o noktadaki teğetin eğimidir"],"t":["Türev, bir niceliğin başka bir niceliğe göre ne kadar hızlı değiştiğini gösterir. Konum fonksiyonunun türevi hız, hızın türevi ivmedir.","Teğet doğrusu denklemi: y − f(a) = f′(a)(x − a). Örneğin f(x) = x² için x = 3'teki teğetin eğimi f′(3) = 6'dır."],"e":["f(x) = x³ − 2x + 1 ise f′(2) kaçtır?","f′(x) = 3x² − 2. f′(2) = 3 · 4 − 2 = 10."],"h":"Zincir kuralında içteki fonksiyonun türevini çarpmayı unutmak."},"12:mat4k1":{"a":"Belirsiz ve Belirli İntegral","o":["İntegral türevin tersidir: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1)","∫ c · f(x) dx = c ∫ f(x) dx · ∫ (f + g) dx = ∫ f dx + ∫ g dx","Belirli integral: ∫ₐᵇ f(x) dx = F(b) − F(a)","f(x) ≥ 0 ise ∫ₐᵇ f(x) dx eğri ile x ekseni arasındaki alandır","Riemann toplamı: alan ince dikdörtgenlerin toplamıyla yaklaşık hesaplanır"],"t":["Belirsiz integralde sabit C eklenir çünkü türevi aynı olan sonsuz sayıda fonksiyon vardır. Belirli integralde bu sabit F(b) − F(a) farkında birbirini götürür.","Hız-zaman grafiğinin altındaki alan yer değiştirmeyi verir; bu nedenle hızın integrali konumdur. İntegral, değişim oranından toplam değişimi bulmanın yoludur.","İntegral türevin tersidir: türevi f(x) olan fonksiyonlara f'nin ilkelleri denir ve ∫ f(x) dx = F(x) + C yazılır. Temel kural: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1), ∫ (1/x) dx = ln|x| + C.","Belirli integral ∫ₐᵇ f(x) dx = F(b) − F(a) şeklinde hesaplanır (C sadeleşir). f(x) ≥ 0 ise bu değer, grafik ile x ekseni arasında a ile b arasında kalan alana eşittir; eksenin altında kalan bölgede integral negatif çıkar, alan için mutlak değer alınır."],"e":["∫ (3x² − 4x + 5) dx integralini hesaplayınız.","Her terim ayrı integrallenir: ∫3x² dx = x³, ∫(−4x) dx = −2x², ∫5 dx = 5x. Sonuç: x³ − 2x² + 5x + C."],"h":"Belirsiz integralde + C'yi unutmak."},"12:matdn1":{"a":"Analitik Düzlemde Öteleme, Yansıma ve Dönme","o":["Öteleme: (x, y) → (x + a, y + b) · a > 0 sağa, b > 0 yukarı","x eksenine göre yansıma: (x, y) → (x, −y) · y eksenine göre: (x, y) → (−x, y)","Orijine göre yansıma: (x, y) → (−x, −y) · y = x doğrusuna göre: (x, y) → (y, x) · y = −x'e göre: (−y, −x)","Orijin etrafında pozitif yönde (saat yönünün tersine) dönme: 90° → (−y, x) · 180° → (−x, −y) · 270° → (y, −x)","Fonksiyon grafiği: y = f(x − a) + b → a birim sağa, b birim yukarı · y = −f(x) x eksenine göre · y = f(−x) y eksenine göre yansıma"],"t":["Dönüşüm, düzlemdeki her noktayı belli bir kurala göre başka bir noktaya taşır. Öteleme, yansıma ve dönmede uzunluklar ve açılar korunur; bu yüzden şeklin görüntüsü kendisine eştir, yalnızca yeri ya da yönü değişir.","Yansımada nokta ile görüntüsü, yansıma doğrusuna eşit uzaklıktadır ve onları birleştiren doğru parçası yansıma doğrusuna diktir. y = x doğrusuna göre yansımada koordinatların yer değiştirmesi bu yüzdendir.","Fonksiyon grafiklerinde öteleme yönü sık karıştırılır: y = f(x − 3) grafiği 3 birim SAĞA kayar, çünkü eski grafikte x = 0'daki değer artık x = 3'te elde edilir. y = f(x) + 3 ise grafiği 3 birim yukarı taşır.","Art arda dönüşümlerde sıra önemlidir: önce yansıtıp sonra ötelemek ile önce öteleyip sonra yansıtmak genellikle farklı sonuç verir. İşlemler verilen sırayla, adım adım yapılmalıdır."],"e":["P(−2, 5) noktası önce y eksenine göre yansıtılıyor, sonra orijin etrafında 180° döndürülüyor. Son görüntü nedir?","1) y eksenine göre yansıma: (x, y) → (−x, y) → (2, 5). 2) 180° dönme: (x, y) → (−x, −y) → (−2, −5). Sonuç (−2, −5); bu aslında P'nin x eksenine göre yansımasıdır."],"h":"y = f(x − a) grafiğini sola kaydırmak: x − a SAĞA, x + a SOLA kaydırır."},"12:matcm1":{"a":"Çemberin Analitik İncelenmesi","o":["Merkezi M(a, b), yarıçapı r olan çember: (x − a)² + (y − b)² = r²","Genel denklem: x² + y² + Dx + Ey + F = 0 · merkez (−D/2, −E/2) · r = ½√(D² + E² − 4F)","Noktanın doğruya uzaklığı: d = |Ax₀ + By₀ + C| / √(A² + B²)","Doğru-çember: d < r → iki noktada keser · d = r → teğettir · d > r → kesişmez","Nokta-çember: |PM| < r içinde · |PM| = r üzerinde · |PM| > r dışında"],"t":["Çember, merkeze eşit uzaklıktaki noktaların kümesidir. Bir P(x, y) noktasının merkeze uzaklığı iki nokta arası uzaklık formülüyle yazılıp r'ye eşitlenirse çemberin denklemi elde edilir: √((x − a)² + (y − b)²) = r.","Denklemde (x − a) gören merkezin apsisini +a, (x + a) gören −a almalıdır. Örneğin (x + 2)² + (y − 3)² = 16 çemberinin merkezi (−2, 3), yarıçapı 4'tür (16 değil).","Genel denklemden merkez ve yarıçap bulmak için ya formül kullanılır ya da tam kareye tamamlanır: x² − 6x = (x − 3)² − 9 gibi. D² + E² − 4F < 0 ise denklem bir çember belirtmez.","Bir doğrunun çemberle konumunu bulmak için merkezin doğruya uzaklığı (d) yarıçapla karşılaştırılır. Teğet doğru, çemberi tek noktada keser ve teğet noktasındaki yarıçapa diktir."],"e":["Çapının uç noktaları A(−1, 3) ve B(5, −5) olan çemberin denklemini bulunuz.","1) Merkez, çapın orta noktasıdır: ((−1 + 5)/2, (3 − 5)/2) = (2, −1). 2) |AB| = √(6² + 8²) = 10 → r = 5. 3) Denklem: (x − 2)² + (y + 1)² = 25."],"h":"(x + a) görünce merkezin apsisini +a almak: (x + 2)² → merkezin apsisi −2'dir."},"11:fiz1k2":{"a":"Newton'ın Hareket Yasaları","o":["1. Yasa (eylemsizlik): ΣF = 0 → sabit hız ya da durgunluk","2. Yasa: ΣF = m · a","3. Yasa: etki-tepki kuvvetleri eşit büyüklükte, zıt yönlü, farklı cisimlere etki eder.","Sabit ivmeli hareket: v = v₀ + at · x = v₀t + ½at² · v² = v₀² + 2ax","Serbest düşme: a = g ≈ 10 m/s²"],"t":["Newton'un ikinci yasasına göre bir cisme etki eden net kuvvet, cismin kütlesi ile ivmesinin çarpımına eşittir. Net kuvvet hızın büyüklüğünü ya da yönünü değiştirir. Üçüncü yasaya göre her etkiye eşit ve zıt bir tepki vardır; bu kuvvetler farklı cisimlere etki ettiği için birbirini dengelemez.","İvmesi sabit olan harekette hız zamanla doğrusal değişir. Hız-zaman grafiğinin eğimi ivmeyi, grafiğin altında kalan alan yer değiştirmeyi verir. Hava direnci ihmal edildiğinde serbest düşen tüm cisimler aynı ivmeyle düşer."],"e":["90 km/h kaç m/s'dir?   A) 30 m/s   B) 324 m/s   C) 2,5 m/s   D) 25 m/s","Doğru cevap: D) 25 m/s. km/h ÷ 3,6 = m/s."]},"11:fiz2k1":{"a":"Serbest Düşme ve İki Boyutta Sabit İvmeli Hareket (Atışlar)","o":["Yatay atış: yatayda sabit hız (x = v₀t), düşeyde serbest düşme (h = ½gt²)","Uçuş süresi yalnızca yüksekliğe bağlıdır (yatay atışta).","Eğik atış: tepe noktasında düşey hız 0, yatay hız v₀·cos α","Menzil en büyük: α = 45°"],"t":["Yatay atılan bir cisim yatayda sabit hızlı, düşeyde serbest düşme hareketi yapar; bu iki hareket birbirinden bağımsızdır. Aynı yükseklikten yatay atılan ve serbest bırakılan iki cisim yere aynı anda düşer.","Eğik atışta cismin hızı yatay ve düşey bileşenlere ayrılır. Yatay bileşen sabit kalır, düşey bileşen yer çekimi nedeniyle değişir; tepe noktasında düşey hız sıfırdır. Hava direnci yoksa en büyük menzil 45° atış açısında elde edilir."],"e":["144 km/h kaç m/s'dir?   A) 45 m/s   B) 518,4 m/s   C) 40 m/s   D) 4 m/s","Doğru cevap: C) 40 m/s. km/h ÷ 3,6 = m/s."]},"11:fiz3k3":{"a":"Manyetik Kuvvet, İndüksiyon ve Transformatörler","o":["Akım taşıyan düz telin çevresinde dairesel manyetik alan oluşur (Ørsted); yönü sağ el kuralıyla bulunur. Akım makarasının (bobin) içindeki alan sarım sayısı ve akımla artar; içine demir çekirdek konunca elektromıknatıs …","Manyetik alandaki akım taşıyan tele kuvvet etki eder: F = B · I · L (tel alana dik iken). Elektrik motoru bu kuvvetle dönen bir sarımdır.","Manyetik akı Φ = B · A (alan yüzeye dik iken). Birimi weber (Wb).","İndüksiyon: Bir devreden geçen manyetik akı değişirse devrede indüksiyon gerilimi ve akımı oluşur (Faraday). Akı ne kadar hızlı değişirse indüksiyon gerilimi o kadar büyük olur: ε = −N · ΔΦ / Δt.","Alternatif akım: manyetik alanda dönen bobinde yönü ve büyüklüğü periyodik değişen akım oluşur; jeneratörler ve şebeke elektriği (Türkiye'de 50 Hz) bu ilkeye dayanır."],"t":["Bir mıknatısı bobinin içine sokup çıkardığımızda bobine bağlı ampermetre sapar: akı değiştiği için indüksiyon akımı oluşur. Mıknatıs bobin içinde hareketsiz durursa akı değişmez, akım oluşmaz.","Lenz kuralı: İndüksiyon akımı, kendisini oluşturan akı değişimine karşı koyacak yönde oluşur; enerjinin korunumunun sonucudur.","Elektrik santrallerinde üretilen gerilim, iletim hatlarında yükseltici transformatörlerle çok yükseltilir; böylece aynı güç için akım küçülür ve tellerde ısı olarak kaybolan enerji azalır. Şehre gelince düşürücü transformatörlerle kullanım gerilimine (220 V) indirilir.","Programa göre Coulomb yasası, elektrik alan ve Ørsted modelinde sayısal hesaplama yapılmaz; ilişkiler (yük artarsa kuvvet artar, uzaklık artarsa azalır) nitel olarak yorumlanır."],"e":["220 V şebekeye bağlı ideal transformatör 11 V'luk bir cihazı çalıştırıyor. Primer sarım sayısı 1200 ise sekonder sarım sayısı kaçtır? Sekonder akımı 2 A ise primer akımı kaçtır?","Vp/Vs = Np/Ns → 220/11 = 1200/Ns → Ns = 60 sarım. Güç korunur: Vp · Ip = Vs · Is → 220 · Ip = 11 · 2 → Ip = 0,1 A."],"h":"Mıknatıs bobin içinde dururken de indüksiyon akımı olduğunu sanmak."},"12:fiz1k1":{"a":"Düzgün Çembersel Hareket ve Kütle Çekimi","o":["Periyot T (bir tur süresi) · frekans f = 1/T · çizgisel hız v = 2πr / T","Açısal hız ω = 2π / T · v = ω · r","Merkezcil ivme a = v² / r · Merkezcil kuvvet F = m · v² / r (merkeze doğru)","Newton'un kütle çekim yasası: F = G · m₁ · m₂ / d²","Kepler yasaları: yörüngeler elips, eşit sürede eşit alan, T² ∝ r³"],"t":["Düzgün çembersel harekette hızın büyüklüğü sabit ama yönü sürekli değiştiği için cisim ivmelidir. Bu ivmeyi oluşturan net kuvvet her an merkeze yöneliktir; virajı dönen otomobilde bu kuvveti sürtünme sağlar.","Uyduların Dünya çevresinde dolanmasını sağlayan merkezcil kuvvet kütle çekim kuvvetidir. Yörünge yarıçapı büyüdükçe uydunun hızı azalır, periyodu artar."],"e":["Kütlesi 0,2 kg olan bir taş 0,5 m'lik ipin ucunda saniyede 2 tur atıyor. Taşın hızını ve ipteki merkezcil kuvveti bulunuz.","1) f = 2 Hz → T = 0,5 s. 2) v = 2πr/T = 2 · 3 · 0,5 / 0,5 = 6 m/s (π ≈ 3). 3) F = mv²/r = 0,2 · 36 / 0,5 = 14,4 N."],"h":"Düzgün çembersel harekette ivmenin sıfır olduğunu sanmak: hızın yönü değiştiği için merkezcil ivme vardır."},"12:fiz2k1":{"a":"Basit Harmonik Hareket ve Dalgalar","o":["Basit harmonik hareket: denge noktasına doğru, uzanımla orantılı geri çağırıcı kuvvet (F = −k·x)","Yay sarkacı periyodu T = 2π√(m/k) · Basit sarkaç periyodu T = 2π√(L/g)","Denge noktasında hız en büyük, uç noktalarda ivme en büyük","Su dalgalarında kırınım: dalga engelin kenarından ya da yarıktan geçerken bükülür","Girişim: dalgaların üst üste binmesi; yapıcı (aynı faz) ve yıkıcı (zıt faz)"],"t":["Basit sarkacın periyodu kütleye ve genliğe (küçük açılarda) bağlı değildir; yalnızca ip uzunluğu ve yer çekimi ivmesine bağlıdır. Bu yüzden sarkaçlı saatler zaman ölçmede kullanılmıştır.","Young'ın çift yarık deneyi ışığın girişim yaptığını, yani dalga özelliği gösterdiğini kanıtladı. Yarık aralığı küçüldükçe ya da dalga boyu büyüdükçe saçak aralığı artar."],"e":["Boyu 1 m olan basit sarkacın periyodunu bulunuz. (g = 10 m/s², π ≈ 3)","T = 2π√(L/g) = 2 · 3 · √(1/10) ≈ 6 · 0,316 ≈ 1,9 s."],"h":"Basit sarkacın periyodunun kütleye bağlı olduğunu sanmak."},"12:fizdg2":{"a":"Dalga Mekaniği: Kırınım, Girişim, Doppler ve Elektromanyetik Dalgalar","o":["Kırınım: dalga, boyutu dalga boyuna yakın yarıktan geçerken yayılarak bükülür (yarık daraldıkça kırınım artar)","Çift yarıkta saçak aralığı Δx = λ · L / d (λ: dalga boyu, L: perde uzaklığı, d: yarık aralığı)","Yapıcı girişim: yol farkı nλ (aydınlık) · yıkıcı girişim: yol farkı (n − ½)λ (karanlık)","Doppler olayı: kaynak yaklaşırken algılanan frekans artar, uzaklaşırken azalır","Elektromanyetik dalgalar boşlukta ışık hızıyla (c = 3·10⁸ m/s) yayılır · c = λ · f"],"t":["Girişim, iki dalganın aynı noktada üst üste binmesidir. Tepeler tepelerle buluşursa dalga güçlenir (yapıcı), tepe çukurla buluşursa söner (yıkıcı). Young deneyinde perdede görülen aydınlık-karanlık çizgiler bunun sonucudur.","Saçak aralığı Δx = λL/d bağıntısıyla hesaplanır: dalga boyu ya da perde uzaklığı arttıkça saçaklar genişler, yarıklar birbirine yaklaştıkça yine genişler. Kırmızı ışığın dalga boyu mordan büyük olduğu için kırmızıda saçaklar daha geniştir.","Doppler olayında kaynağın yaydığı frekans değişmez; değişen, gözlemcinin algıladığı frekanstır. Yaklaşan ambulans sireninin ince, uzaklaşanın kalın duyulması buna örnektir. Gökbilimciler uzaklaşan galaksilerin ışığındaki kırmızıya kaymadan evrenin genişlediğini anlamıştır.","Elektromanyetik dalgalar maddesel ortama ihtiyaç duymaz; hepsi boşlukta aynı hızla gider, yalnızca frekans ve dalga boyları farklıdır. Frekans büyüdükçe enerji artar; bu yüzden morötesi, X ve gama ışınları canlı dokuya zarar verebilir."],"e":["Çift yarık deneyi önce kırmızı, sonra mor ışıkla yapılıyor. Hangisinde saçak aralığı daha büyüktür?","Δx = λL/d. Kırmızı ışığın dalga boyu mordan büyük olduğundan (L ve d aynıyken) kırmızıda saçak aralığı daha büyüktür."],"h":"Doppler olayında kaynağın yaydığı frekansın değiştiğini sanmak: değişen, algılanan frekanstır."},"12:fiz3k1":{"a":"Atom Modelleri, Çekirdek ve Radyoaktivite","o":["Modeller: Thomson (üzümlü kek) → Rutherford (çekirdek) → Bohr (enerji düzeyleri) → modern (orbital)","Bohr: elektron üst düzeyden alt düzeye inerken foton yayar; E_foton = h · f","Radyoaktif bozunmalar: alfa (⁴₂He), beta (elektron), gama (yüksek enerjili foton)","Yarılanma süresi: maddenin yarısının bozunması için geçen süre","Fisyon: ağır çekirdeğin bölünmesi (nükleer santral) · Füzyon: hafif çekirdeklerin birleşmesi (Güneş)"],"t":["Rutherford, altın levhaya alfa parçacıkları gönderdiğinde çoğunun geçtiğini, çok azının geri saptığını gözledi; buradan atomun büyük kısmının boşluk olduğu ve pozitif yükün küçük bir çekirdekte toplandığı sonucuna vardı.","Yarılanma süresi 10 gün olan 80 g radyoaktif maddenin 30 gün sonra 80 → 40 → 20 → 10 g'ı kalır. Radyoaktivite tıpta (görüntüleme, tedavi), arkeolojide (karbon-14 ile yaş tayini) ve enerji üretiminde kullanılır."],"e":["²³⁸₉₂U çekirdeği bir alfa bozunması yapıyor. Oluşan çekirdeğin kütle ve atom numarası nedir?","Alfa parçacığı ⁴₂He'dur. Kütle numarası 238 − 4 = 234, atom numarası 92 − 2 = 90 olur: ²³⁴₉₀Th (toryum)."],"h":"Beta bozunmasında kütle numarasının değiştiğini sanmak: beta bozunmasında kütle numarası aynı kalır, atom numarası 1 artar."},"12:fiz4k1":{"a":"Fotoelektrik Olay, Işığın İkili Doğası ve Özel Görelilik","o":["Fotoelektrik olay: yeterli frekansta ışık metal yüzeyden elektron koparır","Foton enerjisi E = h · f · Eₖ(max) = h · f − W₀ (W₀: bağlanma enerjisi/eşik enerjisi)","Eşik frekansının altında ışık şiddeti ne olursa olsun elektron sökülmez","Işık hem dalga (girişim, kırınım) hem tanecik (fotoelektrik, Compton) özelliği gösterir","Özel görelilik: ışık hızı tüm gözlemciler için aynıdır; hızlı hareket eden saat yavaş işler (zaman genişlemesi), E = m·c²"],"t":["Fotoelektrik olayda ışık şiddetini artırmak sökülen elektron sayısını artırır ama elektronların kinetik enerjisini değiştirmez; kinetik enerjiyi frekans belirler. Einstein bu olayı ışığın fotonlardan oluştuğunu kabul ederek açıkladı.","Güneş panelleri, fotosel kapılar ve dijital kameralardaki ışık algılayıcılar fotoelektrik olaydan yararlanır. GPS uyduları, görelilik etkileri düzeltilmezse konumda büyük hatalar oluşturur.","Compton saçılması, fotonun bir parçacık gibi momentum taşıdığını gösterir: elektrona çarpan foton enerjisinin bir kısmını aktarır ve daha büyük dalga boyuyla saçılır. de Broglie ise tersini önerdi: elektron gibi parçacıklar da dalga özelliği gösterir. Elektron mikroskobu, elektronların dalga boyunun ışığınkinden çok küçük olmasından yararlanarak çok küçük ayrıntıları görüntüler."],"e":["Eşik enerjisi 2,5 eV olan metale enerjisi 4 eV olan fotonlar düşürülüyor. Sökülen elektronların maksimum kinetik enerjisi nedir? Foton enerjisi 2 eV olsaydı ne olurdu?","1) Eₖ = E − W₀ = 4 − 2,5 = 1,5 eV. 2) 2 eV < 2,5 eV olduğundan elektron sökülemez; ışık şiddeti artırılsa bile sökülmez."],"h":"Işık şiddeti artınca elektronların kinetik enerjisinin arttığını sanmak: kinetik enerjiyi frekans belirler."},"10:kim1k2":{"a":"Gazların Özellikleri ve Gaz Yasaları","o":["Gazlar sıkıştırılabilir, bulundukları kabı doldurur, tanecikleri arasında boşluk çoktur","Boyle: sabit sıcaklıkta P · V = sabit · Charles: sabit basınçta V / T = sabit","Gay-Lussac: sabit hacimde P / T = sabit (T kelvin: T = °C + 273)","İdeal gaz denklemi: P · V = n · R · T","Avogadro: aynı koşulda eşit hacimdeki gazlar eşit sayıda tanecik içerir"],"t":["Gaz yasalarında sıcaklık mutlaka kelvin cinsinden kullanılır. 27 °C = 300 K'dir. Sabit basınçta 300 K'deki gaz 600 K'e ısıtılırsa hacmi iki katına çıkar.","Şişirilmiş balonun soğukta büzülmesi, araba lastiklerinin yazın basıncının artması, şırınganın sıkıştırılması gaz yasalarının günlük hayattaki örnekleridir."],"e":["Sabit sıcaklıkta 4 atm basınçtaki gazın hacmi 6 L'dir. Basınç 12 atm olursa hacim kaç L olur?   A) 2 L   B) 9 L   C) 6 L   D) 18 L","Doğru cevap: A) 2 L. Boyle: P₁V₁ = P₂V₂."]},"11:kim4k1":{"a":"Tepkimelerde Enerji ve Tepkime Hızı","o":["Ekzotermik: ısı verir, ΔH < 0 (yanma) · Endotermik: ısı alır, ΔH > 0 (erime, buharlaşma)","Hess yasası: tepkime ısıları toplanabilir.","Hızı etkileyenler: derişim, sıcaklık, temas yüzeyi, katalizör, maddenin cinsi","Katalizör aktifleşme enerjisini düşürür, ΔH'yi değiştirmez.","Çarpışma teorisi: uygun yönde ve yeterli enerjili çarpışmalar ürün oluşturur."],"t":["Kimyasal tepkimeler ısı alarak (endotermik) ya da ısı vererek (ekzotermik) gerçekleşir. Tepkime ısısı (entalpi değişimi) ürünlerin ve girenlerin enerjileri farkıdır. Hess yasasına göre bir tepkimenin ısısı izlenen yoldan bağımsızdır; tepkimeler toplanırsa ısıları da toplanır.","Tepkime hızı birim zamanda harcanan ya da oluşan madde miktarıdır. Sıcaklık ve derişim artışı etkin çarpışma sayısını artırarak hızı yükseltir; toz hâlindeki katılar daha büyük temas yüzeyi sağlar. Katalizörler aktifleşme enerjisini düşürerek tepkimeyi hızlandırır ama tepkimede harcanmaz."],"e":["ΔH₁ = 289 kJ ve ΔH₂ = 197 kJ olan iki tepkime toplanırsa toplam tepkimenin ΔH değeri kaç kJ olur?   A) 92 kJ   B) 486 kJ   C) -92 kJ   D) 496 kJ","Doğru cevap: B) 486 kJ. Hess yasası: tepkime ısıları toplanır."]},"11:kim4k2":{"a":"Kimyasal Denge","o":["Denge: ileri ve geri tepkime hızları eşit, derişimler sabit (dinamik denge)","Denge sabiti Kc = [ürünler] / [girenler] (katsayılar üs olarak)","Le Chatelier: dengeye dış etki yapılırsa sistem etkiyi azaltacak yöne kayar.","Isı veren tepkimede sıcaklık artışı dengeyi girenler yönüne kaydırır."],"t":["Tersinir tepkimelerde ileri ve geri tepkime hızları eşitlendiğinde sistem dengeye ulaşır. Denge dinamiktir: tepkimeler durmaz ama derişimler değişmez. Denge sabiti yalnızca sıcaklığa bağlıdır.","Le Chatelier ilkesine göre dengedeki sisteme derişim, basınç ya da sıcaklık değişikliği uygulanırsa sistem bu etkiyi azaltacak yönde tepki verir. Örneğin girenlerden birinin derişimi artırılırsa denge ürünler yönüne kayar."],"e":["Katalizörün dengeye etkisi nedir?   A) Dengeyi ürünlere kaydırır.   B) Dengeye daha çabuk ulaşılmasını sağlar, dengeyi kaydırmaz.   C) Kc'yi artırır.   D) Dengeyi girenlere kaydırır.","Doğru cevap: B) Dengeye daha çabuk ulaşılmasını sağlar, dengeyi kaydırmaz.. Her iki yönü eşit hızlandırır."]},"11:kim4k4":{"a":"Çözünürlük Dengesi ve Çözünürlük Çarpımı (Kçç)","o":["Az çözünen tuzun doygun çözeltisinde katı ile iyonları arasında denge vardır: AgCl(k) ⇌ Ag⁺(suda) + Cl⁻(suda).","Çözünürlük çarpımı: Kçç = [Ag⁺] · [Cl⁻]. Katı maddeler denge ifadesine yazılmaz.","Molar çözünürlük s: AB tipi tuzda Kçç = s²; AB₂ (ya da A₂B) tipi tuzda Kçç = 4s³.","Ortak iyon etkisi: Çözeltiye tuzun iyonlarından biri eklenirse denge sola kayar, çözünürlük azalır (Le Chatelier).","Sıcaklık: Çözünmesi endotermik olan tuzların çözünürlüğü sıcaklıkla artar; Kçç yalnızca sıcaklıkla değişir."],"t":["Kçç küçüldükçe tuz daha az çözünür; ancak farklı tipteki tuzlar (AB ve AB₂) yalnızca Kçç'ye bakılarak karşılaştırılmaz, molar çözünürlük hesaplanmalıdır.","Örneğin AgCl için Kçç = 1,6 · 10⁻¹⁰ ise s = √(1,6 · 10⁻¹⁰) = 1,26 · 10⁻⁵ M'dir. Aynı tuz 0,1 M NaCl içinde çözülürse [Cl⁻] ≈ 0,1 olur ve s = Kçç / 0,1 = 1,6 · 10⁻⁹ M'ye düşer: ortak iyon çözünürlüğü yaklaşık 10 000 kat azaltmıştır.","Böbrek taşı (kalsiyum oksalat), mağara sarkıtları (CaCO₃) ve kazan taşı oluşumu çözünürlük dengesiyle açıklanır."],"e":["Kçç = 4 · 10⁻¹² olan XY₂ tuzunun molar çözünürlüğünü bulunuz.","XY₂ ⇌ X²⁺ + 2Y⁻ → Kçç = s · (2s)² = 4s³. 4s³ = 4 · 10⁻¹² → s³ = 10⁻¹² → s = 10⁻⁴ M."],"h":"AB₂ tipi tuzda Kçç'yi s² sanmak (doğrusu 4s³)."},"12:kim1k1":{"a":"İndirgenme-Yükseltgenme, Piller ve Elektroliz","o":["Yükseltgenme: elektron verme (yükseltgenme basamağı artar) · İndirgenme: elektron alma","Galvanik pil: kendiliğinden gerçekleşen redoks tepkimesiyle elektrik üretir; anotta yükseltgenme, katotta indirgenme","Tuz köprüsü iyon dengesini sağlar; elektronlar dış devrede anottan katoda akar","Pil potansiyeli E°pil = E°katot − E°anot (indirgenme potansiyelleri) > 0 ise kendiliğinden","Elektroliz: elektrik enerjisiyle istemsiz tepkime gerçekleştirme; kaplama, metal saflaştırma, korozyondan korunma"],"t":["Daniell pilinde çinko elektrot (anot) yükseltgenip Zn²⁺ iyonu olarak çözeltiye geçer ve incelir; bakır elektrot (katot) üzerinde Cu²⁺ iyonları indirgenip metal bakır olarak birikir.","Demirin paslanması bir redoks olayıdır. Demiri çinkoyla kaplamak (galvanizleme) ya da daha aktif bir metali kurban elektrot olarak bağlamak korozyonu önler."],"e":["Zn(k) + Cu²⁺(suda) → Zn²⁺(suda) + Cu(k) tepkimesinde yükseltgenen ve indirgenen türleri, pilde anot ve katodu belirleyiniz. (E°: Zn²⁺/Zn = −0,76 V, Cu²⁺/Cu = +0,34 V)","1) Zn elektron verir (0 → +2): yükseltgenir, anottur. 2) Cu²⁺ elektron alır (+2 → 0): indirgenir, katot bakırdır. 3) E°pil = E°katot − E°anot = 0,34 − (−0,76) = 1,10 V; pozitif olduğundan tepkime istemlidir."],"h":"Anotta indirgenme olduğunu sanmak: anotta yükseltgenme, katotta indirgenme olur."},"12:kim2k1":{"a":"Karbonun Bağ Yapısı ve Hidrokarbonlar","o":["Karbon 4 bağ yapar; zincir, dallanmış ve halkalı yapılar oluşturur","Alkanlar CₙH₂ₙ₊₂ (tek bağ) · Alkenler CₙH₂ₙ (çift bağ) · Alkinler CₙH₂ₙ₋₂ (üçlü bağ)","Hibritleşme: tek bağlı C sp³, çift bağlı sp², üçlü bağlı sp","İzomerlik: aynı kapalı formül, farklı yapı ve özellik","Aromatik hidrokarbon: benzen (C₆H₆) halkası"],"t":["Karbonun başka karbon atomlarıyla kararlı bağlar kurabilmesi milyonlarca organik bileşiğin varlığını açıklar. Doğal gazın ana bileşeni metan (CH₄) en basit alkandır.","Bütan (C₄H₁₀) düz zincirli ve dallanmış (izobütan) iki izomere sahiptir; dallanma arttıkça kaynama noktası genellikle düşer."],"e":["C₄H₁₀ formülüne sahip kaç farklı yapı izomeri vardır? Adlandırınız.","Karbonlar düz zincir hâlinde: bütan. Bir karbon dallanmış: 2-metilpropan (izobütan). Toplam 2 yapı izomeri vardır."],"h":"Alken ve alkinlerin genel formüllerini karıştırmak: alkan CₙH₂ₙ₊₂, alken CₙH₂ₙ, alkin CₙH₂ₙ₋₂."},"12:kim3k1":{"a":"Fonksiyonel Gruplar: Alkoller, Karboksilik Asitler, Esterler","o":["Alkol: –OH grubu (etanol C₂H₅OH) · Eter: R–O–R′","Aldehit: –CHO · Keton: R–CO–R′ (aseton)","Karboksilik asit: –COOH (asetik asit, sirke) · Ester: R–COO–R′ (meyve kokuları)","Esterleşme: karboksilik asit + alkol → ester + su","Polimerler: küçük birimlerin (monomer) birleşmesiyle oluşan büyük moleküller (polietilen, PVC)"],"t":["Fonksiyonel grup, organik bileşiğin kimyasal davranışını belirleyen atom grubudur. Aynı fonksiyonel grubu taşıyan bileşikler benzer tepkimeler verir.","Esterler meyve ve çiçeklere özgü kokuları verir; yağlar ise gliserin ile yağ asitlerinin oluşturduğu esterlerdir. Yağların bazla tepkimesinden sabun elde edilir (sabunlaşma)."],"e":["Asetik asit (CH₃COOH) ile etanolün (C₂H₅OH) tepkimesinde ne oluşur? Tepkimenin adı nedir?","CH₃COOH + C₂H₅OH → CH₃COOC₂H₅ + H₂O. Ürün etil asetat (ester) ve sudur; tepkime esterleşmedir. Esterler meyvelere kokusunu veren bileşiklerdir."],"h":"Alkollerin suda bazik özellik gösterdiğini sanmak: –OH grubu iyonlaşmaz, alkoller nötrdür."},"12:kim4k1":{"a":"Fosil Yakıtlar, Alternatif Enerji ve Sürdürülebilirlik","o":["Fosil yakıtlar: kömür, petrol, doğal gaz; yanınca CO₂ (sera gazı) açığa çıkar","Alternatif kaynaklar: güneş, rüzgâr, hidroelektrik, jeotermal, biyokütle, nükleer, hidrojen","Hidrojen yakıt pilinde ürün sudur: 2H₂ + O₂ → 2H₂O","Nanoteknoloji ve yeni malzemeler (grafen, karbon nanotüp)","Sürdürülebilirlik: enerjiyi verimli kullanmak, yenilenebilir kaynaklara geçmek"],"t":["Fosil yakıtlar milyonlarca yılda oluşur ve hızla tükenir; yanmalarıyla açığa çıkan CO₂ küresel ısınmaya katkıda bulunur. Bu yüzden yenilenebilir kaynaklara geçiş ve enerji verimliliği önemlidir.","Yakıt pilleri kimyasal enerjiyi doğrudan elektriğe dönüştürür; hidrojen yakıt pilinin tek atığı sudur. Ancak hidrojenin üretimi ve depolanması enerji gerektirir."],"e":["CH₄ + 2O₂ → CO₂ + 2H₂O tepkimesinde 1 mol metan yandığında 890 kJ ısı açığa çıkıyor. 8 g metan yanarsa kaç kJ ısı açığa çıkar? (CH₄ = 16 g/mol)","8 / 16 = 0,5 mol metan. 0,5 · 890 = 445 kJ ısı açığa çıkar."],"h":"Doğal gazın yanmasının hiç sera gazı üretmediğini sanmak: CO₂ oluşur, ama kömüre göre daha azdır."},"11:bio1k1":{"a":"Sinir Sistemi, Refleks ve Hormonlar","o":["Nöron: dendrit → hücre gövdesi → akson; impuls tek yönlü iletilir.","Merkezî sinir sistemi: beyin ve omurilik · Çevresel: duyu ve motor sinirler","Refleks merkezi omuriliktir (diz refleksi).","Endokrin bezler hormonu kana salgılar: hipofiz (yöneten bez), tiroit, pankreas (insülin-glukagon), böbrek üstü (adrenalin)","Homeostazi: geri bildirim mekanizmalarıyla iç denge"],"t":["Sinir sistemi uyarıları alır, yorumlar ve tepki oluşturur. Sinir hücrelerinde impuls dendritten hücre gövdesine, oradan aksona iletilir; nöronlar arasındaki iletim sinapslarda kimyasal maddelerle (nörotransmitter) sağlanır. Ani tehlikelere karşı beyin devreye girmeden oluşan istemsiz tepkilere refleks denir.","Endokrin sistem hormonlarla daha yavaş ama uzun süreli düzenleme yapar. Pankreastan salgılanan insülin kan şekerini düşürür, glukagon yükseltir; bu zıt etkili hormonlar kan şekerini dengede tutar. Hipofiz bezi diğer bezlerin çalışmasını yönettiği için 'yöneten bez' olarak bilinir."],"e":["Refleks merkezi neresidir?   A) Beyincik   B) Beyin kabuğu   C) Omurilik   D) Hipofiz","Doğru cevap: C) Omurilik. Refleksler istemsiz ve hızlıdır."]},"11:bio3k1":{"a":"Dolaşım, Solunum ve Boşaltım Sistemlerinin Dengedeki Rolü","o":["Kalp: 2 kulakçık, 2 karıncık · Büyük dolaşım: sol karıncık → aort → vücut","Küçük dolaşım: sağ karıncık → akciğer atardamarı → akciğer","Solunum: alveollerde difüzyonla O₂ kana, CO₂ dışarı","Boşaltım: böbrek (nefron) — süzülme, geri emilim, salgılama","Kan grupları: A, B, AB, 0 · Rh faktörü"],"t":["Dolaşım sistemi besin, oksijen ve atık maddelerin taşınmasını sağlar. Kanın kalpten akciğerlere gidip oksijenlenerek kalbe dönmesine küçük dolaşım, kalpten vücuda gidip dönmesine büyük dolaşım denir. Sol karıncığın duvarı kanı tüm vücuda pompaladığı için en kalındır.","Akciğerlerdeki alveollerde gaz alışverişi difüzyonla olur. Böbreklerin yapı ve görev birimi nefrondur: kan önce süzülür, gerekli maddeler geri emilir, bazı atıklar ise salgılanarak idrar oluşturulur."],"e":["Akciğerlerde gaz alışverişinin yapıldığı yapılar hangileridir?   A) Alveoller   B) Gırtlak   C) Soluk borusu   D) Bronşlar","Doğru cevap: A) Alveoller. Alveollerin etrafı kılcal damarlarla sarılıdır."]},"12:bio1k1":{"a":"DNA'nın Yapısı, Replikasyon ve Protein Sentezi","o":["Nükleotit: fosfat + deoksiriboz şekeri + organik baz (A, T, G, C)","DNA çift sarmal; A–T (2 hidrojen bağı), G–C (3 hidrojen bağı) eşleşir","Replikasyon yarı korunumlu: her yeni DNA bir eski bir yeni zincir taşır","Transkripsiyon (çekirdekte): DNA → mRNA · Translasyon (ribozomda): mRNA → protein","Kodon: mRNA'da amino asidi belirleyen üçlü baz dizisi; AUG başlama kodonu"],"t":["Protein sentezinde bilgi DNA'dan RNA'ya, RNA'dan proteine aktarılır. tRNA, antikodonuyla mRNA'daki kodona eşleşerek doğru amino asidi ribozoma taşır; amino asitler peptit bağlarıyla birleşir.","Mutasyon DNA'nın baz dizisindeki kalıcı değişikliktir. Tek bir baz değişikliği bile farklı bir amino asidin eklenmesine ve proteinin işlevinin bozulmasına yol açabilir (orak hücreli anemi gibi)."],"e":["Bir DNA molekülündeki nükleotitlerin %30'u adenin ise guanin oranı yüzde kaçtır?","Chargaff kuralı: A = T ve G = C. A = %30 → T = %30. Kalan %40, G ve C arasında eşit paylaşılır: G = %20."],"h":"RNA'da timin olduğunu sanmak: RNA'da timin yerine urasil bulunur."},"12:bio2k1":{"a":"Fotosentez, Kemosentez ve Hücresel Solunum","o":["Fotosentez: ışığa bağımlı tepkimeler (tilakoit zar: ATP, NADPH, O₂) + ışıktan bağımsız tepkimeler (Calvin döngüsü, stroma: glikoz)","Fotosentezde açığa çıkan O₂ suyun parçalanmasından gelir","Kemosentez: bazı bakterilerin inorganik maddelerin oksidasyon enerjisiyle besin üretmesi","Oksijenli solunum: glikoliz (sitoplazma) → Krebs döngüsü (mitokondri matriksi) → ETS (iç zar)","En çok ATP oksidatif fosforilasyonla (ETS) üretilir; son elektron alıcısı O₂"],"t":["Fotosentez ve solunum, enerji dönüşümlerinin birbirini tamamlayan iki yönüdür: fotosentez ışık enerjisini glikozun kimyasal bağ enerjisine, solunum ise bu enerjiyi ATP'ye dönüştürür.","Kemosentetik bakteriler (nitrit ve nitrat bakterileri gibi) güneş ışığı olmayan ortamlarda da besin üretebilir ve azot döngüsünde önemli rol oynar."],"e":["Fotosentezin ışığa bağımlı ve ışıktan bağımsız tepkimeleri kloroplastın neresinde gerçekleşir? Ürünleri nedir?","Işığa bağımlı tepkimeler tilakoit zarlarında olur; su parçalanır, O₂ açığa çıkar, ATP ve NADPH üretilir. Işıktan bağımsız tepkimeler (Calvin döngüsü) stromada olur; ATP ve NADPH kullanılarak CO₂'den glikoz üretilir."],"h":"Bitkilerin yalnızca fotosentez yapıp solunum yapmadığını sanmak: bitkiler gece ve gündüz solunum yapar."},"12:bio3k1":{"a":"Bitkilerin Yapısı, Taşıma ve Üreme","o":["Doku sistemleri: meristem (bölünür), örtü, temel doku, iletim (ksilem: su-mineral, floem: organik besin)","Su taşınması: kök basıncı, kılcallık, terleme-kohezyon (en etkili: terleme çekimi)","Stomalar gaz alışverişi ve terlemeyi düzenler","Bitki hormonları: oksin (büyüme, fototropizma), giberellin, sitokinin, absisik asit, etilen (meyve olgunlaşması)","Çiçekli bitkilerde çift döllenme: bir sperm yumurtayı (zigot), diğeri polar çekirdekleri (endosperm) döller"],"t":["Yapraklardan su buharlaştıkça ksilemdeki su sütunu, su moleküllerinin birbirine tutunması (kohezyon) sayesinde yukarı çekilir. Bu yüzden terleme, uzun ağaçlarda suyun taşınmasının ana itici gücüdür.","Bitkinin ışığa doğru eğilmesi oksin hormonunun gölge tarafta birikip oradaki hücreleri daha çok uzatmasıyla açıklanır."],"e":["Çiçekli bitkilerde çift döllenme nasıl gerçekleşir? Oluşan yapıların kromozom sayısı nedir?","Polen tüpündeki iki sperm çekirdeğinden biri yumurta hücresiyle birleşerek zigotu (2n) oluşturur. Diğeri iki polar çekirdekle birleşerek besin dokusu olan endospermi (3n) oluşturur."],"h":"Ksilem ve floemin görevlerini karıştırmak: ksilem su ve mineral, floem organik besin taşır."},"12:bio4k1":{"a":"Ekosistemde Enerji Akışı, Madde Döngüleri ve Çevre Sorunları","o":["Enerji akışı tek yönlü; her basamakta yaklaşık %10 aktarılır","Madde döngüleri: su, karbon, azot (azot bağlama → amonifikasyon → nitrifikasyon → denitrifikasyon)","Çevre sorunları: küresel iklim değişikliği, ozon tabakasının incelmesi, asit yağmurları, biyolojik birikim","Biyoçeşitliliğin korunması: koruma alanları, gen bankaları, sürdürülebilir kaynak kullanımı","Ekolojik ayak izi: bir kişinin tükettiği kaynakları karşılamak için gereken alan"],"t":["Azot döngüsünde havadaki serbest azotu bitkiler doğrudan kullanamaz; azot bağlayıcı bakteriler (baklagillerin köklerindeki Rhizobium gibi) onu amonyağa çevirir, nitrifikasyon bakterileri nitrata dönüştürür.","Fosil yakıt kullanımıyla atmosferdeki CO₂ oranı artar, sera etkisi güçlenir ve küresel sıcaklık yükselir. Bu durum buzulların erimesi, deniz seviyesinin yükselmesi ve aşırı hava olaylarıyla sonuçlanır."],"e":["Bir besin zincirinde üreticilerin depoladığı enerji 20 000 kJ ise üçüncül tüketicilere ulaşan enerji yaklaşık kaç kJ'dür? (%10 kuralı)","Her basamakta enerjinin yaklaşık %10'u aktarılır: üretici 20 000 → birincil tüketici 2000 → ikincil 200 → üçüncül 20 kJ."],"h":"Enerjinin ekosistemde döngü hâlinde dolaştığını sanmak: madde döngüsel, enerji tek yönlü akar."},"9:ede1k1":{"a":"İletişim ve Dilin İşlevleri","o":["İletişim ögeleri: gönderici, alıcı, ileti, kanal, bağlam, dönüt","Dilin işlevleri: göndergesel (bilgi), heyecana bağlı (duygu), alıcıyı harekete geçirme, şiirsel, kanalı kontrol, dil ötesi","Edebî metin: sanatsal amaçlı, çok anlamlı, kurmaca · Öğretici metin: bilgi verir, tek anlamlı","Edebiyat; dil, tarih, sosyoloji, psikoloji, felsefe gibi alanlarla ilişkilidir."],"t":["İletişim, bir göndericinin iletisini bir kanal aracılığıyla alıcıya ulaştırmasıdır; bağlam iletinin anlamını belirler, dönüt ise alıcının tepkisidir. Dil, iletişimde farklı işlevlerle kullanılır: bilgi aktarırken göndergesel, duygu yansıtırken heyecana bağlı, emir ve rica cümlelerinde alıcıyı harekete geçirme işlevi öne çıkar. Edebî metinlerde ise dilin şiirsel (sanatsal) işlevi baskındır.","Edebî metinler sanatsal kaygıyla yazılır, kurmaca ve yan anlamlarla zengindir; öğretici metinler ise bilgi aktarır, açık ve tek anlamlı bir dil kullanır. Edebiyat; dönemin tarihî ve toplumsal yapısını, insan psikolojisini ve düşünce dünyasını yansıttığı için diğer bilim ve sanat dallarıyla ilişkilidir."],"e":["Edebî metinlerde, özellikle şiirde öne çıkan işlev hangisidir?   A) Göndergesel işlev   B) Kanalı kontrol işlevi   C) Dil ötesi işlev   D) Şiirsel (sanatsal) işlev","Doğru cevap: D) Şiirsel (sanatsal) işlev. Dil estetik amaçla kullanılır."]},"10:edb2k1":{"a":"Gazel, Kaside ve Aruz Ölçüsü","o":["Divan şiiri: İslamiyet etkisinde gelişen, Arapça-Farsça etkili, aruz ölçülü yazılı şiir","Aruz: hecelerin uzunluk-kısalığına dayanır; kapalı hece uzun (–), açık hece kısa (.)","Gazel: 5-15 beyit, aşk-şarap-güzellik; ilk beyit matla, son beyit makta (mahlas)","Kaside: 33-99 beyit; din ve devlet büyüklerini övme; nesib, girizgâh, methiye, fahriye, dua bölümleri","Nazım birimi beyittir; uyak düzeni gazel ve kasidede aa, ba, ca …"],"t":["Gazelde her beyit kendi içinde anlamca bağımsız olabilir; buna 'müstakil beyit' denir. Fuzûlî aşk, Bâkî rindlik ve İstanbul güzellikleri, Nedîm ise mahallîleşme (yerli hayat) özellikleriyle öne çıkan gazel şairleridir.","Aruzda hece değerleri belirlenirken uzun ünlülü heceler ve ünsüzle biten heceler uzun sayılır. Türkçede uzun ünlü az olduğu için şairler 'imale' (kısa heceyi uzun okuma) ve 'zihaf' (uzun heceyi kısa okuma) başvurur; bunlar aruz kusurları sayılır."],"e":["Gazelin ilk beytine ne denir?   A) Matla   B) Hüsn-i matla   C) Beyt-i gazel   D) Makta","Doğru cevap: A) Matla. Matlanın dizeleri kendi arasında uyaklıdır."]},"9:ede2k2":{"a":"Şiirde Söz Sanatları ve İmge","o":["Teşbih (benzetme): \"Aslan gibi asker\"","İstiare: yalnız benzeyen ya da benzetilen kullanılır.","Teşhis (kişileştirme) ve intak (konuşturma)","Mübalağa (abartma), tezat (karşıtlık), tenasüp (ilgili sözcükler)","İmge: duyulara seslenen zihinsel resim"],"t":["Şair duygu ve düşüncelerini etkili kılmak için söz sanatlarına başvurur. Benzetmede (teşbih) benzeyen ve benzetilen birlikte kullanılır; istiarede bunlardan yalnızca biri bulunur: 'Bir aslan geldi' (askere aslan denmesi). Kişileştirmede insan dışındaki varlıklara insana ait özellikler verilir.","Tezat zıt kavramların bir arada kullanılması, tenasüp ise anlamca ilgili sözcüklerin bir arada kullanılmasıdır. İmge, şiirde okurun zihninde görsel, işitsel ya da dokunsal bir resim oluşturan anlatımdır."],"e":["\"Ağlarım hatıra geldikçe gülüştüklerimiz\" dizesinde hangi sanat vardır?   A) Kişileştirme   B) Teşbih   C) Tezat   D) İstiare","Doğru cevap: C) Tezat. Ağlamak ve gülmek zıt kavramlardır."]},"10:edb4k1":{"a":"Hikâye, Roman ve Geleneksel Tiyatro","o":["Anlatının unsurları: olay örgüsü, kişiler, zaman, mekân, anlatıcı, bakış açısı","Anlatıcı: kahraman anlatıcı (1. kişi), gözlemci ya da ilahi bakış açılı anlatıcı (3. kişi)","Roman: uzun, çok olaylı, çok kişili anlatı · Hikâye: kısa, tek olay çevresinde yoğunlaşır","Geleneksel Türk tiyatrosu: Karagöz (gölge oyunu), Orta oyunu, Meddah","Karagöz'ün bölümleri: mukaddime, muhavere, fasıl, bitiş"],"t":["İlahi bakış açısında anlatıcı her şeyi bilir, kahramanların iç dünyasını da yansıtır; gözlemci anlatıcı ise yalnızca gördüklerini aktarır. Bakış açısı, okurun olaylara nereden baktığını belirler.","Karagöz'de halk kültürünü temsil eden Karagöz ile okumuş, kibar konuşan Hacivat arasındaki söz oyunları ve yanlış anlamalar mizahın kaynağıdır. Meddah tek kişilik anlatıdır; elinde mendil ve sopayla hikâye anlatır."],"e":["Açık alanda, dekorsuz oynanan geleneksel Türk tiyatrosu türü hangisidir?   A) Meddah   B) Orta oyunu   C) Opera   D) Karagöz","Doğru cevap: B) Orta oyunu. Pişekâr ve Kavuklu baş kişilerdir."]},"9:ede5k2":{"a":"Tiyatro","o":["Tiyatro: sahnede canlandırılmak üzere yazılan metin; diyalog ağırlıklı","Unsurlar: perde, sahne, diyalog, monolog, yan metin (parantez içi açıklamalar)","Türler: trajedi, komedi, dram","Geleneksel Türk tiyatrosu: Karagöz, orta oyunu, meddah, köy seyirlik oyunları"],"t":["Tiyatro, olayların oyuncular tarafından sahnede canlandırılması için yazılan edebî türdür. Anlatım ağırlıklı olarak diyalogla yapılır; yan metinler (parantez içindeki açıklamalar) oyuncuların hareketlerini, dekoru ve ışığı belirtir.","Trajedi acıklı olayları, komedi güldürü unsurlarıyla toplumun aksayan yönlerini, dram ise trajik ve komik unsurları birlikte işler. Geleneksel Türk tiyatrosunda Karagöz gölge oyunu, orta oyunu ve meddah önemli yer tutar."],"e":["Tiyatro eserinin büyük bölümlerine ne denir?   A) Perde   B) Cilt   C) Kıta   D) Sahne","Doğru cevap: A) Perde. Perdeler sahnelere ayrılır."]},"10:edb1k1":{"a":"Koşuk, Türkü, Koşma ve Ninni","o":["Koşuk: İslamiyet öncesi sözlü edebiyatta sığır törenlerinde söylenen lirik şiir; doğa, aşk, kahramanlık","Türkü: anonim halk şiiri; bentler ve her bentten sonra tekrarlanan bağlama (kavuştak)","Koşma: âşık edebiyatı; çoğunlukla 11'li hece, 3-5 dörtlük, son dörtlükte mahlas","Ninni: çocuğu uyutmak için ezgiyle söylenen, genellikle anonim kısa şiir","Ortak özellik: ezgiyle söylenme, hece ölçüsü, yarım ve tam uyak, redif"],"t":["Bu türler sözün müzikle birleştiği sözlü kültür ürünleridir. Türkü ve ninni anonimdir, yani söyleyeni bilinmez ve ağızdan ağıza geçerken değişebilir; koşma ise âşık tarzı şiirdir ve şair kendini son dörtlükte mahlasıyla tanıtır.","Şiiri incelerken dize ve dörtlük/bent yapısı, hece sayısı ve duraklar, uyak ve redif, tema ve duygu birlikte değerlendirilir. Halk şiirinde uyak çoğunlukla yarım uyak ve redifle kurulur."],"e":["Halk edebiyatında aşk, doğa ve ayrılık konularını işleyen, hece ölçüsüyle yazılan nazım şekli hangisidir?   A) Gazel   B) Kaside   C) Rubai   D) Koşma","Doğru cevap: D) Koşma. Genellikle 11'li hece ölçüsüyle yazılır."]},"10:edb3k1":{"a":"Destan, Efsane ve Dede Korkut Hikâyeleri","o":["Destan: millî hayatı etkileyen olayların (savaş, göç, kuruluş) olağanüstü kahramanlarla anlatıldığı uzun manzum anlatı","İslamiyet öncesi destanlar: Oğuz Kağan, Göktürk (Ergenekon, Bozkurt), Türeyiş, Göç","Efsane: bir yerin, varlığın ya da olayın olağanüstü kökenini anlatan kısa anlatı","Dede Korkut Hikâyeleri: destan geleneğinden halk hikâyesine geçiş; Oğuz boylarının yaşayışı; nazım-nesir karışık","Halk hikâyesi: âşıklar tarafından anlatılır; aşk (Kerem ile Aslı) ve kahramanlık (Köroğlu) konuları"],"t":["Destanlar oluşum, yayılma ve derlenme evrelerinden geçer. Ergenekon Destanı, düşmanlarına yenilen Göktürklerin bozkurt rehberliğinde dağı eriterek çıkışını anlatır ve millî kimliği güçlendiren bir anlatıdır.","Dede Korkut Hikâyeleri, İslamiyet'in kabulünden sonra yazıya geçirilmiş olsa da eski Türk geleneklerini ve İslami unsurları birlikte taşır. Hikâyeleri Dede Korkut adlı bilge ozan düzenler ve sonunda dua eder."],"e":["Doğal destanlarda yazarı bilinir mi?   A) Evet, her zaman bilinir   B) Divan şairlerine aittir   C) Sadece Yunus Emre'dir   D) Hayır, anonimdir","Doğru cevap: D) Hayır, anonimdir. Yapma destanların ise yazarı bellidir."]},"12:edb1k1":{"a":"Cumhuriyet Dönemi Şiirinde Akımlar","o":["Beş Hececiler / Millî Edebiyat zevki: hece ölçüsü, Anadolu, memleket sevgisi (Faruk Nafiz Çamlıbel, Kemalettin Kamu)","Saf şiir: ahenk, musiki, imge (Ahmet Hamdi Tanpınar, Ahmet Haşim etkisi)","Garip (I. Yeni): Orhan Veli, Oktay Rifat, Melih Cevdet; ölçü-uyak ve söz sanatlarına karşı, sıradan insan","İkinci Yeni: anlamda kapalılık, imge ve soyutlama (Cemal Süreya, Edip Cansever, Turgut Uyar, İlhan Berk)","Toplumcu gerçekçi şiir: Nâzım Hikmet, serbest vezin; Mistik-metafizik şiir: Necip Fazıl, Sezai Karakoç"],"t":["Garip hareketi 1941'de yayımlanan 'Garip' kitabıyla başladı; şiiri ölçü, uyak ve söz sanatlarından arındırarak günlük konuşma diline yaklaştırdı. 'Kitabe-i Seng-i Mezar'daki Süleyman Efendi gibi sıradan insanı şiire soktu.","İkinci Yeni şairleri Garip'in sadeliğine tepki olarak anlamı geri plana iten, imge yoğun, çağrışımlı ve kapalı bir şiir anlayışı geliştirdi.","Cumhuriyet dönemi şiirinin başlıca toplulukları: Beş Hececiler (Faruk Nafiz Çamlıbel, Enis Behiç Koryürek, Halit Fahri Ozansoy, Orhan Seyfi Orhon, Yusuf Ziya Ortaç) hece ölçüsü ve memleket konularıyla; Saf şiir (Ahmet Hamdi Tanpınar, Ahmet Muhip Dıranas, Cahit Sıtkı Tarancı) musiki ve imgeyle; Toplumcu gerçekçiler (Nazım Hikmet, Ahmet Arif, Enver Gökçe) serbest ölçü ve toplumsal temalarla öne çıkar.","Garip akımı (Orhan Veli Kanık, Oktay Rifat, Melih Cevdet Anday, 1941) ölçü, uyak ve süslü söyleyişi reddetti; sokaktaki insanı günlük dille anlattı. İkinci Yeni (Cemal Süreya, Edip Cansever, Turgut Uyar, İlhan Berk, Ece Ayhan) ise Garip'e tepki olarak anlamı kapalı, imge yoğun şiiri savundu. Necip Fazıl Kısakürek ve Sezai Karakoç mistik-metafizik çizginin önemli adlarıdır."],"e":["\"Yaşamak şakaya gelmez, / büyük bir ciddiyetle yaşayacaksın / bir sincap gibi mesela\" dizeleri hangi şiir anlayışının özelliklerini taşır?","Serbest ölçü, uyak kaygısının olmaması, insanı ve yaşamı merkeze alan coşkulu söyleyiş Nazım Hikmet'in temsil ettiği toplumcu gerçekçi şiirin özellikleridir."],"h":"Garip ile İkinci Yeni'yi karıştırmak: Garip anlaşılır ve sade, İkinci Yeni kapalı ve imge yoğundur."},"12:ink4k1":{"a":"Atatürk Dönemi Dış Politika, II. Dünya Savaşı ve Soğuk Savaş","o":["İlke: 'Yurtta sulh, cihanda sulh'; tam bağımsızlık, barışçı ve gerçekçi politika","Musul sorunu (1926 Ankara Antlaşması), Nüfus mübadelesi, Milletler Cemiyeti'ne giriş (1932)","Balkan Antantı (1934), Sadabat Paktı (1937), Montrö Boğazlar Sözleşmesi (1936)","Hatay'ın anavatana katılması (1939)","II. Dünya Savaşı'nda Türkiye savaş dışı kaldı; sonrasında NATO'ya girdi (1952), Soğuk Savaş'ta Batı Bloku'nda yer aldı"],"t":["Montrö Boğazlar Sözleşmesi ile Lozan'da uluslararası komisyona bırakılan Boğazların denetimi Türkiye'ye geçti ve Türkiye Boğazları silahlandırma hakkı kazandı. Bu, sorunların barışçı yoldan çözülmesinin önemli bir örneğidir.","Hatay meselesi, Atatürk'ün 'kişisel meselem' dediği konudur; 1938'de Hatay Devleti kuruldu, 1939'da Hatay Meclisi'nin kararıyla Türkiye'ye katıldı."],"e":["Montrö Boğazlar Sözleşmesi'nin (1936) Türkiye açısından önemi nedir?","Lozan'da uluslararası bir komisyona bırakılan Boğazlar'ın denetimi tamamen Türkiye'ye geçti; Türkiye Boğazlar'da asker bulundurma hakkı kazandı. Barışçı yollarla egemenlik hakkının tamamlanmasıdır."],"h":"Musul'un Türkiye'ye katıldığını sanmak: 1926 Ankara Antlaşması ile Musul Irak'a bırakılmıştır."},"12:cog2k1":{"a":"Şehirlerin Fonksiyonları ve Türkiye'de Ekonomik Faaliyetler","o":["Şehir fonksiyonları: sanayi (Kocaeli), ticaret, liman (Mersin), turizm (Antalya), kültür-eğitim, yönetim (Ankara)","Etki alanı: bir şehrin çevresine hizmet verdiği alan; büyük şehirler geniş etki alanına sahiptir","Türkiye'de tarım: iklim çeşitliliği sayesinde ürün çeşitliliği (fındık Karadeniz, pamuk Çukurova-GAP, çay Doğu Karadeniz)","Sanayi: Marmara'da yoğun; dağılışı etkileyenler: ham madde, enerji, pazar, ulaşım, sermaye, iş gücü","Ulaşım: kara yolu en yaygın; demir yolu, deniz ve hava yolu gelişiyor"],"t":["Bir şehrin fonksiyonu, o şehirde hangi ekonomik etkinliğin öne çıktığını gösterir. Zonguldak madencilik, Kocaeli sanayi, Nevşehir turizm fonksiyonuyla öne çıkar.","Sanayi tesislerinin Marmara'da toplanmasının nedenleri; büyük pazar, liman ve ulaşım olanakları, sermaye birikimi ve nitelikli iş gücüdür."],"e":["Bir şehrin fonksiyonunu belirlemede hangi ölçütlere bakılır? Bir örnek veriniz.","Şehirde öne çıkan ekonomik ve sosyal faaliyetlere bakılır. Örneğin Zonguldak madencilik, Antalya turizm, Kocaeli sanayi, Eskişehir eğitim (üniversite) fonksiyonuyla öne çıkar."],"h":"Her büyük şehrin tek fonksiyonlu olduğunu sanmak: İstanbul gibi şehirler çok fonksiyonludur."},"12:cog4k1":{"a":"Doğal Kaynakların Sürdürülebilir Kullanımı ve Çevre Sorunları","o":["Doğal kaynaklar: yenilenebilir (su, güneş, rüzgâr, orman) ve yenilenemez (petrol, kömür, maden)","Çevre sorunları: hava, su ve toprak kirliliği, erozyon, ormansızlaşma, çölleşme","Türkiye'de erozyonu artıran etkenler: eğimli arazi, bitki örtüsünün tahribi, yanlış tarım uygulamaları","Çevre koruma: millî parklar, tabiat parkları, sulak alan koruması (Ramsar), atık yönetimi","Sürdürülebilir kalkınma: ekonomik büyüme, toplumsal refah ve çevre korumanın dengelenmesi"],"t":["Erozyon toprağın akarsu, rüzgâr ve yer çekimiyle taşınmasıdır; bitki örtüsü toprağı köklerle tuttuğu için ormansızlaşma erozyonu hızlandırır. Eğime dik sürüm, taraçalama ve ağaçlandırma erozyonu azaltır.","Çölleşme kurak ve yarı kurak alanlarda arazinin verimini yitirmesidir; aşırı otlatma, yanlış sulama (tuzlanma) ve iklim değişikliği başlıca nedenlerdir."],"e":["Sürdürülebilir kalkınma ne demektir? Bir uygulama örneği veriniz.","Bugünün ihtiyaçlarını, gelecek nesillerin ihtiyaçlarını karşılama imkânını yok etmeden karşılamaktır. Örnek: yenilenebilir enerji kullanımı, damla sulama, atıkların geri dönüşümü, ağaçlandırma."],"h":"Yenilenebilir kaynakların sınırsız kullanılabileceğini sanmak: su ve orman gibi kaynaklar aşırı kullanımla tükenebilir."},"11:cog3k1":{"a":"Tarım, Madenler, Enerji Kaynakları ve Sanayi","o":["Tarımı etkileyenler: iklim, yer şekilleri, toprak, sulama, teknoloji","Ürünler: çay (Doğu Karadeniz), fındık (Karadeniz), pamuk (Çukurova, GAP), zeytin (Ege, Akdeniz)","Madenler: bor (Türkiye dünya rezervinin büyük kısmı), krom, linyit","Enerji: hidroelektrik, rüzgâr, güneş, jeotermal (Denizli, Aydın)","Sanayi tesislerinin yer seçimi: ham madde, enerji, iş gücü, ulaşım, pazar"],"t":["Türkiye'nin farklı iklim bölgelerine sahip olması tarım ürünü çeşitliliğini artırır. Çay nemli ve yağışlı Doğu Karadeniz'de, pamuk sıcak ve sulanabilen Çukurova ile GAP bölgesinde, zeytin Akdeniz iklimine uygun Ege ve Akdeniz kıyılarında yetişir.","Türkiye bor madeni rezervlerinde dünyada ilk sıradadır. Enerji ihtiyacı için yenilenebilir kaynakların (hidroelektrik, rüzgâr, güneş, jeotermal) payı artmaktadır. Sanayi tesislerinin yeri ham madde, enerji, ulaşım ve pazara yakınlık gibi etkenlere göre seçilir."],"e":["Rüzgâr enerjisi santrallerinin yoğun olduğu bölgeler hangileridir?   A) Güneydoğu   B) Ege ve Marmara   C) İç Anadolu ve Doğu Anadolu   D) Karadeniz iç kesimleri","Doğru cevap: B) Ege ve Marmara. Rüzgâr potansiyeli yüksektir."]},"12:cog3k1":{"a":"Kültür Bölgeleri, Ülkeler ve Küresel Ticaret","o":["Kültür bölgeleri: dil, din, yaşam tarzı ortak alanlar (Türk-İslam, Batı, Çin, Hint, Afrika, Latin Amerika)","İlk kültür merkezleri büyük akarsu boylarında doğdu: Mezopotamya, Nil, İndus, Çin (Huang He)","Küresel ticaret: hammadde ihraç eden ülkeler ile sanayi ürünü ihraç eden ülkeler arasındaki akış","Ekonomik örgütler: AB, OPEC (petrol), G20, Türk Devletleri Teşkilatı","Gelişmişlik göstergeleri: kişi başı gelir, sanayileşme, eğitim, ortalama yaşam süresi, İnsani Gelişme Endeksi"],"t":["Kültür bölgeleri sınırları kesin olmayan, ortak özelliklerin yoğunlaştığı alanlardır. Ticaret, göç ve iletişim teknolojileri kültürlerin etkileşimini hızlandırır.","Petrol gibi stratejik kaynaklar ülkeler arası ilişkileri doğrudan etkiler. OPEC üyesi ülkeler üretim miktarını ayarlayarak dünya petrol fiyatlarını etkileyebilir."],"e":["Kültür bölgelerinin oluşmasında etkili olan unsurlar nelerdir?","Din, dil, tarih, gelenek-görenek, yaşam tarzı ve ekonomik faaliyetler. Örneğin Türk-İslam kültür bölgesi ortak din ve tarih bağlarıyla oluşmuştur."],"h":"Kültür bölgelerini yalnızca siyasi sınırlarla eşleştirmek: kültür bölgeleri ülke sınırlarını aşabilir."},"12:lp1a":{"a":"Psikolojinin Tanımı, Amaçları ve Yöntemleri","o":["Psikoloji: insan davranışlarını ve zihinsel süreçleri bilimsel yöntemlerle inceleyen bilim","Amaçları: betimlemek, açıklamak, yordamak (tahmin), kontrol etmek","1879: Wilhelm Wundt Leipzig'de ilk psikoloji laboratuvarını kurdu","Yöntemler: gözlem, deney, anket, görüşme, vaka (örnek olay) incelemesi","Deneyde neden-sonuç ilişkisi kurulabilir; korelasyon neden-sonuç göstermez"],"t":["Psikoloji, insan ve hayvan davranışlarını ve bu davranışların arkasındaki düşünme, algılama, öğrenme, hatırlama ve duygu gibi zihinsel süreçleri bilimsel yöntemlerle inceleyen bilimdir. Felsefenin içinden doğmuş, 1879'da Wilhelm Wundt'un Leipzig'de ilk psikoloji laboratuvarını kurmasıyla bağımsız bir bilim olarak kabul görmüştür.","Psikolojinin dört amacı vardır: davranışı betimlemek (ne oluyor?), açıklamak (neden oluyor?), yordamak (ne zaman ve hangi koşulda yeniden olur?) ve kontrol etmek ya da değiştirmek (istenmeyen davranışı nasıl azaltırız?). Örneğin sınav kaygısı yaşayan öğrencilerin belirtilerini tanımlamak betimleme, kaygının nedenlerini bulmak açıklamadır.","Psikologlar gözlem, anket, görüşme, vaka incelemesi ve deney gibi yöntemler kullanır. Neden-sonuç ilişkisi yalnızca kontrollü deneyle kurulabilir. İki değişkenin birlikte değişmesi (korelasyon) birinin diğerine neden olduğunu göstermez: dondurma satışı ile boğulma vakalarının yazın birlikte artması, dondurmanın boğulmaya yol açtığı anlamına gelmez; ikisinin ortak nedeni sıcak havadır."],"e":["'Uyku süresi arttıkça not ortalaması artıyor.' bulgusu uykunun başarıyı artırdığını kanıtlar mı?","Hayır, bu bir korelasyondur. Neden-sonuç için uyku süresinin deneysel olarak değiştirildiği, diğer koşulların sabit tutulduğu bir deney gerekir."],"h":"Korelasyonu neden-sonuç sanmak."},"12:lp1c":{"a":"Duygular, Stres ve Başa Çıkma","o":["Temel duygular: mutluluk, üzüntü, korku, öfke, şaşkınlık, tiksinme","Stres: zorlayıcı durumlara bedenin ve zihnin tepkisi","Az stres performansı artırabilir; aşırı stres düşürür (Yerkes–Dodson)","Problem odaklı başa çıkma: sorunu çözmeye yönelmek","Duygu odaklı başa çıkma: nefes, spor, konuşma, düşünceyi yeniden çerçeveleme"],"t":["Duygular, olaylara verdiğimiz bedensel, zihinsel ve davranışsal tepkilerdir. Mutluluk, üzüntü, korku, öfke, şaşkınlık ve tiksinme farklı kültürlerde benzer yüz ifadeleriyle görülen temel duygulardır. Duygular bize bilgi verir: korku tehlikeye karşı uyarır, öfke bir sınırın aşıldığını gösterir.","Stres, zorlayıcı ya da tehdit edici olarak algılanan durumlara karşı verilen tepkidir; kalp atışı hızlanır, kaslar gerilir, dikkat daralır. Yerkes–Dodson yasasına göre orta düzeyde uyarılma performansı artırır, ama aşırı stres performansı düşürür. Sınav öncesi biraz heyecan normaldir ve hatta faydalıdır.","Stresle başa çıkmanın iki yolu vardır. Problem odaklı başa çıkmada sorunun kendisi çözülmeye çalışılır: çalışma planı yapmak, eksik konuları belirlemek, yardım istemek. Duygu odaklı başa çıkmada ise duygunun yoğunluğu azaltılır: derin nefes, düzenli uyku ve spor, güvenilir biriyle konuşmak, 'Bu sınav hayatımın sonu değil, bir basamak' gibi düşünceyi yeniden çerçevelemek. Stres uzun süre günlük hayatı zorluyorsa rehber öğretmenden ya da bir uzmandan destek almak doğru adımdır."]},"12:lp1b":{"a":"Öğrenme ve Bellek","o":["Öğrenme: yaşantı sonucu davranışta oluşan kalıcı değişme","Klasik koşullanma (Pavlov): nötr uyarıcı ile doğal tepki arasında bağ","Edimsel koşullanma (Skinner): davranışın sonucu (pekiştirme/ceza) davranışı belirler","Bellek aşamaları: duyusal bellek → kısa süreli bellek (7±2 birim) → uzun süreli bellek","Ebbinghaus unutma eğrisi: unutma ilk saatlerde hızlıdır; aralıklı tekrar unutmayı yavaşlatır"],"t":["Öğrenme, yaşantı ya da tekrar sonucunda davranışta oluşan kalıcı değişmedir; büyüme veya yorgunluktan kaynaklanan geçici değişmeler öğrenme sayılmaz. Rus fizyolog Ivan Pavlov, köpeklere yemek verirken zil çaldığında, bir süre sonra köpeklerin yalnızca zil sesine salya salgıladığını gösterdi. Bu, klasik koşullanmadır.","B. F. Skinner ise davranışın sonucuna göre öğrenildiğini gösterdi: ödüllendirilen (pekiştirilen) davranış tekrar edilir, cezalandırılan davranış azalır. Buna edimsel koşullanma denir. Ödevi yapınca övgü alan öğrencinin ödev yapma davranışının artması bunun örneğidir. Gözlem yoluyla, başkalarını izleyerek öğrenme (Bandura) de önemli bir öğrenme biçimidir.","Bilgi önce çok kısa süre duyusal bellekte tutulur; dikkat edilen bilgi kısa süreli belleğe geçer. Kısa süreli bellek yaklaşık 7±2 birim bilgiyi 15–30 saniye tutabilir. Tekrar ve anlamlandırma ile bilgi uzun süreli belleğe aktarılır. Hermann Ebbinghaus'un unutma eğrisi, öğrenilen bilginin büyük kısmının ilk saatlerde unutulduğunu; aralıklı tekrarın ise unutmayı belirgin biçimde yavaşlattığını gösterir. Bu uygulamadaki Aralıklı Tekrar özelliği bu bilgiye dayanır."],"e":["Telefon numarasını 0532 418 27 63 gibi gruplara bölerek hatırlamak hangi bellek özelliğinden yararlanır?","Kısa süreli belleğin sınırlı kapasitesinden (7±2 birim): bilgiyi gruplamak (kümeleme) daha fazla bilgiyi tutmayı sağlar."]},"12:ls1a":{"a":"Sosyoloji Nedir? Toplum ve Birey","o":["Sosyoloji: toplumu, toplumsal ilişkileri ve kurumları bilimsel yöntemle inceleyen bilim","'Sosyoloji' terimini Auguste Comte kullanmıştır","İbn Haldun (Mukaddime) sosyolojinin öncülerindendir","Emile Durkheim sosyolojiyi akademik bilim hâline getirdi","Türkiye'de öncü: Ziya Gökalp"],"t":["Sosyoloji, insanların bir arada yaşarken kurduğu ilişkileri, grupları, kurumları ve toplumsal değişmeyi bilimsel yöntemlerle inceleyen bilimdir. 'Sosyoloji' terimini 19. yüzyılda Fransız düşünür Auguste Comte kullanmıştır. Ancak 14. yüzyılda yaşamış İbn Haldun, Mukaddime adlı eserinde toplumların yükseliş ve çöküşünü 'asabiyet' kavramıyla açıklayarak sosyolojinin öncülerinden olmuştur.","Emile Durkheim, toplumsal olguların bireylerin dışında ve onlara rağmen var olduğunu savunmuş, sosyolojiyi üniversitede ders olarak okutulan bir bilim hâline getirmiştir. Max Weber ise bireylerin davranışlarına yükledikleri anlamı anlamanın önemini vurgulamıştır. Türkiye'de sosyolojinin öncüsü Ziya Gökalp'tir.","Birey ile toplum arasındaki ilişki karşılıklıdır: Birey toplum içinde doğar, dili, değerleri ve rollerini toplumdan öğrenir; buna sosyalleşme denir. Aile, okul, arkadaş grupları ve medya sosyalleşmenin başlıca araçlarıdır. Birey de yaptıklarıyla toplumu değiştirebilir."]},"12:ls1b":{"a":"Toplumsal Yapı: Statü, Rol ve Kurumlar","o":["Statü: bireyin toplumdaki konumu (öğrenci, öğretmen, anne)","Doğuştan (verilmiş) statü ve kazanılmış statü","Rol: statünün gerektirdiği davranışlar","Rol çatışması: farklı rollerin beklentilerinin çakışması","Temel kurumlar: aile, eğitim, din, ekonomi, siyaset"],"t":["Toplumsal yapı, bir toplumu oluşturan statüler, roller, gruplar ve kurumlardan oluşan bütündür. Statü, bireyin toplumda bulunduğu konumdur: öğrenci, doktor, abla, takım kaptanı. Kadın ya da erkek olmak, bir aileye doğmak gibi doğuştan gelen statüler verilmiş statü; çalışarak elde edilen öğretmenlik, doktorluk gibi statüler kazanılmış statüdür.","Rol, bir statünün gerektirdiği davranışlar bütünüdür. Öğrenci statüsündeki kişiden derse katılması, ödevlerini yapması beklenir. Bir kişinin aynı anda birden çok statüsü ve rolü vardır; bu rollerin beklentileri çakıştığında rol çatışması yaşanır: maçın olduğu akşam ertesi günkü sınava çalışması gereken bir takım oyuncusu gibi.","Toplumsal kurumlar, toplumun temel ihtiyaçlarını karşılayan, süreklilik gösteren yapılardır. Aile neslin devamını ve ilk eğitimi, eğitim kurumu bilgi ve becerilerin aktarılmasını, ekonomi üretim ve tüketimi, siyaset düzen ve yönetimi, din ise inanç ve değerleri düzenler. Kurumlar birbirini etkiler; ekonomideki bir değişim aile yapısını da değiştirebilir."],"e":["Ayşe hem öğrenci, hem okul voleybol takımının kaptanı, hem de küçük kardeşine bakan bir abladır. Turnuva günü kardeşinin de okul gösterisi vardır. Bu durum neye örnektir?","Rol çatışmasına: kaptan ve abla rollerinin beklentileri aynı zamanda çakışmaktadır."]},"12:ls1c":{"a":"Kültür ve Toplumsal Değişme","o":["Kültür: bir toplumun maddi ve manevi değerlerinin bütünü","Maddi kültür: araç-gereç, yapılar, kıyafet; manevi kültür: dil, din, gelenek, değerler","Kültürleşme: farklı kültürlerin karşılaşıp etkileşmesi","Kültürel gecikme: teknoloji hızlı, değerler yavaş değişir","Toplumsal değişme nedenleri: teknoloji, göç, eğitim, ekonomi, doğa olayları"],"t":["Kültür, bir toplumun geçmişten bugüne yarattığı maddi ve manevi değerlerin bütünüdür. Evler, araçlar, kıyafetler ve yiyecekler maddi kültürü; dil, din, gelenekler, sanat ve değerler manevi kültürü oluşturur. Kültür öğrenilir, kuşaktan kuşağa aktarılır ve zamanla değişir.","Farklı kültürler göç, ticaret, turizm ve medya aracılığıyla karşılaştığında birbirini etkiler; buna kültürleşme denir. Kültürel gecikme ise maddi kültürün (teknoloji) manevi kültürden (değerler, kurallar) daha hızlı değişmesidir: akıllı telefonlar çok hızlı yayılmış, ama telefon kullanım görgü kuralları ve dijital güvenlik bilinci aynı hızla gelişmemiştir.","Toplumsal değişme; teknolojik gelişmeler, sanayileşme ve kentleşme, göç, eğitimdeki yaygınlaşma, ekonomik krizler ve doğal afetler gibi nedenlerle gerçekleşir. Örneğin köyden kente göçle geniş ailelerin yerini çekirdek aileler almış, kadınların iş hayatına katılımı artmıştır."]},"12:lm1a":{"a":"Mantık Nedir? Kavram, Terim ve Tanım","o":["Mantık: doğru düşünmenin kurallarını inceleyen disiplin","Kurucusu Aristoteles; eserleri 'Organon' adıyla toplanmıştır","Kavram: nesnelerin zihindeki ortak tasarımı; terim: kavramın dile getirilmiş hâli","İçlem: kavramın nitelikleri; kaplam: kapsadığı nesneler","İçlem arttıkça kaplam azalır (canlı → hayvan → kedi)"],"t":["Mantık, doğru düşünmenin ve geçerli akıl yürütmenin kurallarını inceleyen disiplindir. Klasik mantığın kurucusu Antik Yunan filozofu Aristoteles'tir; mantıkla ilgili eserleri sonradan 'Organon' (alet) adıyla bir araya getirilmiştir. İslam dünyasında Farabi ve İbn Sina mantığı geliştirmiştir; Farabi'ye 'Muallim-i Sani' (ikinci öğretmen) denir.","Kavram, aynı türden nesnelerin zihnimizdeki ortak tasarımıdır; 'kitap' kavramı tek bir kitabı değil, bütün kitapları kapsar. Kavram bir kelimeyle ifade edildiğinde terim adını alır. Kavramın nitelikleri içlemini, kapsadığı nesneler ise kaplamını oluşturur.","İçlem ile kaplam ters orantılıdır: 'canlı' kavramının kaplamı çok geniş, içlemi azdır; 'hayvan' kavramında nitelikler artar, kaplam daralır; 'kedi' kavramında içlem daha da artar, kaplam daha da daralır. Tanım ise bir kavramın ne olduğunu, onu başka kavramlardan ayıran özelliklerle belirtmektir: 'İnsan düşünen bir canlıdır.'"]},"12:lm1b":{"a":"Önerme ve Kıyas","o":["Önerme: doğru ya da yanlış olabilen yargı bildiren cümle","Soru, emir ve dilek cümleleri önerme değildir","Kıyas: iki öncülden bir sonuç çıkaran akıl yürütme","Büyük öncül + küçük öncül → sonuç","Geçerlilik biçimle, doğruluk içerikle ilgilidir"],"t":["Önerme, doğru ya da yanlış olabilen bir yargı bildiren cümledir: 'Ankara Türkiye'nin başkentidir.' (doğru), 'Su 50 °C'de kaynar.' (yanlış). Soru ('Saat kaç?'), emir ('Kapıyı kapat!') ve dilek ('Keşke yağmur yağsa') cümleleri doğru ya da yanlış olarak değerlendirilemediği için önerme sayılmaz.","Kıyas, iki öncülden zorunlu olarak bir sonuç çıkaran tümdengelimli akıl yürütmedir. En bilinen örnek: 'Bütün insanlar ölümlüdür. (büyük öncül) Sokrates bir insandır. (küçük öncül) O hâlde Sokrates ölümlüdür. (sonuç)' Öncüllerde ortak olan 'insan' terimine orta terim denir; orta terim sonuçta yer almaz.","Bir kıyasın geçerli olması biçimiyle, doğru olması içeriğiyle ilgilidir. 'Bütün kuşlar uçar. Penguen bir kuştur. O hâlde penguen uçar.' kıyası biçim olarak geçerlidir ama ilk öncül yanlış olduğu için sonuç yanlıştır. Doğru sonuç için kıyasın hem geçerli hem de öncüllerinin doğru olması gerekir."],"e":["'Bütün metaller elektriği iletir. Bakır bir metaldir. O hâlde …' Sonuç ve orta terim nedir?","Sonuç: Bakır elektriği iletir. Orta terim: metal (her iki öncülde geçer, sonuçta geçmez)."],"h":"Geçerli kıyasın her zaman doğru sonuç verdiğini sanmak: öncüller yanlışsa geçerli kıyas da yanlış sonuç verebilir."},"12:din1k1":{"a":"İslam Medeniyetinde Bilim ve Bilim İnsanları","o":["Kur'an'da akıl, düşünme ve araştırmaya teşvik: 'Hiç düşünmüyor musunuz?'","Beytü'l-Hikme (Bağdat): çeviri ve araştırma merkezi","Harezmî (cebir, algoritma), İbn Sina (El-Kanun fi't-Tıb), Biruni (astronomi, coğrafya), İbnü'l-Heysem (optik), Uluğ Bey (astronomi)","Medreseler, rasathaneler, darüşşifalar ve kütüphaneler bilim kurumlarıdır","Din ve bilim farklı alanlarda insanın anlam ve bilgi arayışına cevap verir"],"t":["Abbasiler döneminde Bağdat'ta kurulan Beytü'l-Hikme'de Yunanca, Süryanice ve Farsça eserler Arapçaya çevrildi; bu birikim geliştirilerek sonraki yüzyıllarda Avrupa'ya aktarıldı.","İbn Sina'nın El-Kanun fi't-Tıb adlı eseri yüzyıllarca Avrupa üniversitelerinde tıp ders kitabı olarak okutuldu."],"e":["İslam medeniyetinde bilime katkı yapan bilim insanlarına ve alanlarına örnek veriniz.","Harezmî (cebir, algoritma kavramı), İbn Sina (tıp – El-Kanun), Bîrûnî (astronomi, coğrafya), İbnü'l-Heysem (optik), Uluğ Bey ve Ali Kuşçu (astronomi)."],"h":"Din ile bilimin her zaman çatıştığını varsaymak: İslam medeniyetinde pek çok bilim insanı aynı zamanda din âlimiydi."},"12:din2k1":{"a":"Anadolu'da İslam'ın Yayılışı ve Gönül Erleri","o":["Malazgirt (1071) sonrası Türkmenlerle birlikte İslam Anadolu'da yaygınlaştı","Ahmet Yesevi'nin talebeleri (Horasan erenleri) Anadolu'ya gelerek İslam'ı yaydı","Mevlana Celaleddin Rumi (Mesnevi, hoşgörü), Yunus Emre (Türkçe ilahiler, sevgi), Hacı Bektaş-ı Veli (Makalat)","Ahi Evran: Ahilik teşkilatı; esnaf ahlakı ve dayanışma","Hoşgörü ve birlikte yaşama kültürü"],"t":["Yunus Emre, 'Yaratılanı severiz Yaratan'dan ötürü' anlayışıyla sevgi ve hoşgörüyü öne çıkardı; şiirlerini sade Türkçeyle yazarak halkın dinî kavramları anlamasını kolaylaştırdı.","Mevlana'nın 'Gel, ne olursan ol yine gel' çağrısıyla özetlenen hoşgörü anlayışı Anadolu'da farklı toplulukların bir arada yaşamasına katkı sağladı."],"e":["Anadolu'nun İslamlaşmasında gönül erlerinin rolü nedir? Örnek veriniz.","Ahmet Yesevî'nin talebeleri, Hacı Bektaş-ı Velî, Mevlânâ, Yunus Emre ve Ahi Evran gibi gönül erleri hoşgörü, sevgi ve ahlak öğütleriyle İslam'ın Anadolu'da benimsenmesine ve farklı toplulukların bir arada yaşamasına katkı sağladılar."],"h":"Ahiliği yalnızca dinî bir yapı sanmak: Ahilik aynı zamanda esnaf ve zanaatkâr dayanışma teşkilatıdır."}};
